window.__DATA={"schede":[{"anno":2020,"area":"cam","autori":"Daron Acemoglu, Pascual Restrepo","autoriIds":["daron-acemoglu","pascual-restrepo"],"collegamenti":["emery-trist","kelly"],"concetti":["trasformazione digitale","contingenza","carico di lavoro","sistemi aperti"],"contesto":["manifattura","mercato del lavoro"],"creata":"2026-11-05","doi":"10.1086/705716","etichetta":"Acemoglu","evidenza":"","fonte":"Journal of Political Economy, 128(6), 2188-2244, 2020","inAzienda":"Un investimento in automazione va valutato anche per l'effetto sulle persone e sul territorio, e chiede piani di riqualificazione prima, non dopo.","leve":["car","rel"],"macro":"tra","microtemi":["automazione","trasformazione digitale","ambiente esterno","costi nascosti","interdipendenza"],"motivi":{"ambiente esterno":"Gli effetti si misurano sui mercati del lavoro locali, cioè sull'ambiente delle imprese.","automazione":"Misura gli effetti dei robot industriali su occupazione e salari.","costi nascosti":"Fa emergere costi sociali che non compaiono nel bilancio dell'impresa.","interdipendenza":"Lega le scelte produttive delle imprese al benessere dei territori.","trasformazione digitale":"Riguarda l'ingresso di una tecnologia che sostituisce mansioni."},"organizzazioni":[],"prova":"studio osservazionale","sinossi":"Acemoglu e Restrepo studiano l'effetto dei robot industriali sul lavoro negli Stati Uniti, un tema di cui si discuteva molto con pochi dati. Prima mostrano con un modello che i robot possono ridurre occupazione e salari, perché sostituiscono mansioni, oppure aumentarli, perché rendono più produttive le imprese. Poi misurano quanto ogni area locale è esposta ai robot combinando i progressi della robotica per settore con il peso di quei settori nell'occupazione locale. Trovano effetti negativi robusti: un robot in più ogni mille lavoratori riduce il rapporto fra occupati e popolazione di circa 0,2 punti percentuali e i salari dello 0,42 per cento. Le aree più esposte non mostravano andamenti diversi prima del 1990, e l'effetto dei robot si distingue da quello di altre tecnologie e investimenti. Lo studio è diventato il riferimento per discutere l'automazione in modo misurato e non profetico. Riguarda i robot industriali e non l'intelligenza artificiale, guarda ai mercati locali e non alle singole imprese, e il disegno è osservazionale anche se molto controllato.","tipo":"articolo","titolo":"Robots and Jobs: Evidence from US Labor Markets","url":"https://doi.org/10.1086/705716","id":"acemoglu-2020-robots"},{"anno":2010,"area":"nat","autori":"Jesper J. Alvarsson, Stefan Wiens, Mats E. Nilsson","autoriIds":["jesper-j-alvarsson","stefan-wiens","mats-e-nilsson"],"collegamenti":["ulrich"],"concetti":["paesaggio sonoro","recupero","stress lavorativo"],"contesto":["laboratorio"],"creata":"2026-11-04","doi":"10.3390/ijerph7031036","etichetta":"Alvarsson et al.","evidenza":"diretta","fonte":"International Journal of Environmental Research and Public Health, 7(3), 1036-1046, 2010","inAzienda":"Il rumore di fondo degli uffici e delle aree di pausa non è neutro: dopo un compito impegnativo rallenta il ritorno alla calma, mentre i suoni naturali lo accelerano. Ripensare il paesaggio sonoro delle sale relax è quindi un intervento sul recupero delle persone, a costo contenuto.","leve":["rig"],"macro":"ben","microtemi":["suoni naturali","recupero dallo stress","rumore","fisiologia dello stress"],"motivi":{},"organizzazioni":[],"prova":"esperimento di laboratorio","sinossi":"Jesper Alvarsson e i suoi colleghi dell'Università di Stoccolma sottopongono un gruppo di studenti a un compito di aritmetica mentale pensato per mettere sotto stress. Subito dopo i partecipanti ascoltano, in ordine diverso, suoni naturali come acqua che scorre e canto di uccelli, rumore di traffico stradale o il brusio di un ambiente affollato. La conduttanza cutanea, che misura l'attivazione del sistema nervoso simpatico, torna ai valori di partenza più in fretta con i suoni naturali che con i rumori. Altre misure fisiologiche non mostrano differenze chiare. È un esperimento di laboratorio su qualche decina di persone, utile come indizio più che come prova definitiva.","tipo":"articolo","titolo":"Stress recovery during exposure to nature sound and environmental noise","url":"https://doi.org/10.3390/ijerph7031036","id":"alvarsson-2010-sound"},{"anno":2015,"area":"nat","autori":"Lucy M. Aplin, Damien R. Farine, Julie Morand-Ferron, Andrew Cockburn, Alex Thornton e colleghi","autoriIds":["lucy-m-aplin","damien-r-farine","julie-morand-ferron","andrew-cockburn","alex-thornton"],"collegamenti":["kawai","rogers-e","asch"],"concetti":["diffusione delle innovazioni","conformità","cultura organizzativa","comunicazione"],"contesto":["uccelli"],"creata":"2026-11-05","doi":"10.1038/nature13998","etichetta":"Aplin et al.","evidenza":"formale","fonte":"Nature, 518(7540), 538-541, 2015","inAzienda":"Per diffondere una pratica nuova conviene affidarla prima a poche persone ben collegate con i colleghi e poi lasciare che diventi la norma del gruppo. La stessa conformità che la stabilizza renderà però difficile cambiarla di nuovo in futuro.","leve":["rel","app"],"macro":"cam","microtemi":["diffusione per relazioni","diffusione delle innovazioni","conformità","norme","reti di relazioni"],"motivi":{"conformità":"Gli uccelli adottano la variante più diffusa nel loro gruppo.","diffusione delle innovazioni":"Segue un'innovazione dall'introduzione alla stabilizzazione.","diffusione per relazioni":"La tecnica nuova si diffonde lungo i legami sociali misurati.","norme":"Nascono tradizioni locali stabili, simili a norme di gruppo.","reti di relazioni":"L'analisi delle reti sociali spiega la velocità della diffusione."},"organizzazioni":[],"prova":"esperimento di campo","sinossi":"Lucy Aplin, dell'Edward Grey Institute dell'Università di Oxford, e colleghi vogliono capire con un esperimento, e non solo con l'osservazione, come un comportamento nuovo si diffonde e si stabilizza in una popolazione animale selvatica. Nel bosco di Wytham, vicino a Oxford, addestrano due cinciallegre per ciascuna di alcune sottopopolazioni ad aprire una mangiatoia in uno di due modi possibili, spingendo una porta a destra o a sinistra. Con etichette elettroniche e analisi delle reti sociali seguono la diffusione: l'informazione corre lungo i legami sociali e raggiunge in media il 75 per cento degli individui, con 414 uccelli che imparano e quasi 58.000 aperture registrate. Ogni sottopopolazione resta fedele alla tecnica introdotta per prima, e questa tradizione locale dura per due generazioni nonostante un forte ricambio degli individui. Gli uccelli tendono ad adottare la variante più diffusa nel loro gruppo, anche quando ne conoscono un'altra, cioè mostrano conformità sociale. Lo studio è una delle prove sperimentali più chiare di cultura animale. Le cinciallegre non sono persone e il compito è semplice, per cui l'analogia vale per il meccanismo di diffusione e non per il contenuto delle culture umane.","tipo":"articolo","titolo":"Experimentally induced innovations lead to persistent culture via conformity in wild birds","url":"https://doi.org/10.1038/nature13998","id":"aplin-2015-innovations"},{"anno":1978,"area":"cam","autori":"Chris Argyris e Donald A. Schön","autoriIds":["chris-argyris","donald-a-schon"],"collegamenti":["schein","bateson","senge","kegan-lahey"],"concetti":["teoria dichiarata e teoria in uso","apprendimento organizzativo"],"contesto":["imprese"],"creata":"2026-11-04","etichetta":"Argyris e Schön","evidenza":"","fonte":"Organizational Learning, Addison-Wesley, 1978","inAzienda":"Quando un'azienda dichiara un valore, per esempio la collaborazione, ma premia altro, per esempio i risultati individuali, le persone seguono ciò che viene premiato. Per cambiare la cultura bisogna quindi partire dallo scarto fra valori dichiarati e comportamenti effettivamente premiati.","leve":["app","cul"],"macro":"app","microtemi":["teoria dichiarata","teoria in uso","doppio ciclo","routine difensive","apprendimento organizzativo"],"organizzazioni":[],"prova":"teoria","sinossi":"Chris Argyris e Donald Schön partono da un'osservazione che chiunque abbia lavorato in un'azienda riconosce: le persone dichiarano di agire secondo certi principi, la teoria dichiarata, ma si comportano secondo altri, la teoria in uso, di cui spesso non si accorgono. Un'organizzazione impara a ciclo singolo quando corregge un errore senza toccare le regole che lo hanno prodotto, come un termostato che riaccende il riscaldamento; impara a ciclo doppio quando mette in discussione quelle regole e gli obiettivi stessi. Il secondo tipo di apprendimento è raro, perché le routine difensive proteggono le persone dall'imbarazzo e dalla minaccia e intanto impediscono di vedere le cause vere dei problemi. Il libro unisce teoria e casi raccolti nell'attività di consulenza. È diventato il riferimento comune di chi parla di organizzazione che apprende, anche se la distinzione fra i due cicli è più facile da enunciare che da misurare.","tipo":"libro","titolo":"Organizational Learning","url":"https://openlibrary.org/works/OL4294379W","id":"argyris-schon"},{"anno":1956,"area":"soc","autori":"Solomon E. Asch","autoriIds":["solomon-e-asch"],"collegamenti":["janis","moscovici"],"concetti":["conformità","voce"],"contesto":["laboratorio"],"creata":"2026-11-04","doi":"10.1037/h0093718","etichetta":"Asch","evidenza":"","fonte":"«Studies of independence and conformity», Psychological Monographs, 70(9), 1956","inAzienda":"In una riunione chi parla per primo, soprattutto se ha autorità, orienta le opinioni di chi parla dopo. Raccogliere le valutazioni per iscritto prima della discussione, o nominare qualcuno che sostenga apertamente la posizione contraria, riduce questo effetto e migliora le decisioni.","leve":["gui","rel"],"macro":"com","microtemi":["conformità","pressione del gruppo","dissenso","alleato","ordine di parola"],"motivi":{"alleato":"Asch ha mostrato che, quando anche una sola persona del gruppo dà la risposta corretta, i partecipanti si adeguano molto meno alla maggioranza.","conformità":"Lo studio misura quanto spesso le persone ripetono una risposta evidentemente sbagliata solo perché la dà tutto il resto del gruppo.","dissenso":"Mostra quanto è difficile esprimere un'opinione diversa quando nessun altro la condivide.","ordine di parola":"Nell'esperimento il partecipante vero rispondeva dopo quasi tutti gli altri, quando la maggioranza si era già espressa: è la posizione in cui la pressione del gruppo pesa di più.","pressione del gruppo":"La maggioranza ottiene l'adeguamento senza chiederlo, con la sola forza della propria unanimità."},"organizzazioni":[],"prova":"esperimento di laboratorio","sinossi":"Negli esperimenti di Asch un partecipante doveva dire quale fra tre linee era lunga quanto una linea campione, dopo aver sentito le risposte di altri presenti, in realtà complici, che sbagliavano all'unanimità. In circa un terzo delle prove critiche i partecipanti si adeguavano alla risposta sbagliata, e tre su quattro lo fecero almeno una volta. Bastava però un solo complice che desse la risposta giusta perché la conformità crollasse. Le varianti mostrarono che la pressione cresce con l'unanimità più che con il numero. Gli studi furono condotti su studenti americani negli anni Cinquanta, e le repliche successive mostrano livelli di conformità diversi per epoca e cultura.","tipo":"articolo","titolo":"Studies of independence and conformity","url":"https://doi.org/10.1037/h0093718","id":"asch"},{"anno":1956,"area":"sis","autori":"W. Ross Ashby","autoriIds":["w-ross-ashby"],"collegamenti":["wiener","lawrence-lorsch","bienefeld-grote","gordon","holling"],"concetti":["varietà necessaria","decentralizzazione","turbolenza ambientale","regolazione distribuita","contingenza"],"contesto":["sistemi"],"creata":"2026-11-04","etichetta":"Ashby","evidenza":"","fonte":"An Introduction to Cybernetics, Chapman & Hall, 1956","inAzienda":"Se l'ambiente in cui opera un'azienda è molto variabile, un unico centro decisionale non può avere pronte tutte le risposte necessarie. Per questo le decisioni che dipendono da situazioni impreviste vanno affidate a chi le vede da vicino, mentre restano al centro quelle stabili e ad alto rischio.","leve":["gui","app"],"macro":"lea","microtemi":["varietà necessaria","decentralizzazione","complessità ambientale","regolazione","risposta all'ambiente"],"organizzazioni":[],"prova":"teoria","sinossi":"W. Ross Ashby, psichiatra inglese e uno dei fondatori della cibernetica, scrisse questo manuale per spiegare a chi non è matematico come si regola un sistema. Il risultato più noto è la legge della varietà necessaria: un sistema riesce a governare il proprio ambiente solo se dispone, al suo interno, di tanta varietà di risposte quanta è la varietà dei disturbi che riceve. In breve, solo la varietà può assorbire la varietà. Un'organizzazione che risponde a un mercato vario con poche procedure rigide perde il controllo, e un capo che vuole decidere tutto diventa il punto in cui la varietà si blocca. Il libro è formale in molte parti, ma la legge è entrata stabilmente negli studi di management.","tipo":"libro","titolo":"An Introduction to Cybernetics","url":"https://openlibrary.org/works/OL169933W","id":"ashby"},{"anno":2003,"area":"lav","autori":"Francesco Avallone, Mauro Bonaretti","autoriIds":["francesco-avallone","mauro-bonaretti"],"collegamenti":["lewin","francescato","maslach"],"concetti":["benessere organizzativo","silenzio organizzativo","partecipazione","stress lavorativo","cultura organizzativa"],"contesto":["pubblica amministrazione"],"creata":"2026-11-05","doi":"","etichetta":"Avallone","evidenza":"","fonte":"F. Avallone, M. Bonaretti (a cura di), Rubbettino, Soveria Mannelli, 2003, collana Analisi e strumenti per l'innovazione, I manuali, Dipartimento della Funzione Pubblica, Programma Cantieri","inAzienda":"Un'indagine sul benessere organizzativo serve se diventa ricerca-intervento, con la restituzione dei risultati alle persone e azioni concordate, e non un questionario archiviato.","leve":["rig","rel"],"macro":"ben","microtemi":["benessere organizzativo","clima","ricerca-azione","stress lavorativo","valori dichiarati"],"motivi":{"benessere organizzativo":"È il manuale che ha diffuso in Italia il concetto e lo strumento di misura.","clima":"Propone una metodologia di analisi e intervento sul clima organizzativo.","ricerca-azione":"Il questionario è pensato come primo passo di una ricerca-intervento.","stress lavorativo":"Lo stress è una delle dodici dimensioni misurate.","valori dichiarati":"Una dimensione riguarda la coerenza fra ciò che l'organizzazione dichiara e ciò che fa."},"organizzazioni":["Dipartimento della Funzione Pubblica"],"prova":"indagine con questionario","sinossi":"Il manuale nasce dal Laboratorio Benessere organizzativo del Programma Cantieri del Dipartimento della Funzione Pubblica, a cui parteciparono la Facoltà di Psicologia 2 della Sapienza, ministeri, enti e amministrazioni locali. Il punto di partenza è che nelle amministrazioni pubbliche la gerarchia e le procedure non bastano a governare la convivenza organizzativa, e che la qualità delle relazioni pesa quanto le regole. Gli autori definiscono il benessere organizzativo attraverso dodici dimensioni: l'ambiente fisico, la chiarezza degli obiettivi e la coerenza fra dichiarazioni e pratiche, il riconoscimento delle competenze, la comunicazione circolare, la circolazione delle informazioni, la prevenzione dei rischi, il clima relazionale, la scorrevolezza operativa, la giustizia organizzativa, l'apertura all'innovazione, lo stress e la conflittualità. Su queste dimensioni costruiscono un questionario e lo sperimentano in diverse amministrazioni, raccogliendo 3.197 questionari, di cui 3.122 validi. Il volume descrive anche come restituire i risultati e avviare azioni di ricerca-intervento, con esempi redatti dagli stessi funzionari. È diventato il riferimento italiano per le indagini sul benessere organizzativo nel settore pubblico. È un manuale operativo più che una ricerca con controlli, e il campione non è stato scelto in modo casuale.","tipo":"rapporto","titolo":"Benessere organizzativo. Per migliorare la qualità del lavoro nelle amministrazioni pubbliche","url":"","id":"avallone-2003-benessere"},{"anno":2007,"area":"lav","autori":"Arnold B. Bakker e Evangelia Demerouti","autoriIds":["arnold-b-bakker","evangelia-demerouti"],"collegamenti":["karasek","maslach","sonnentag-fritz"],"concetti":["stress lavorativo","burnout","motivazione intrinseca","benessere organizzativo"],"contesto":["imprese"],"creata":"2026-11-04","doi":"10.1108/02683940710733115","etichetta":"Bakker e Demerouti","evidenza":"","fonte":"«The job demands-resources model», Journal of Managerial Psychology, 22, 2007","inAzienda":"Il modello permette di leggere il disagio di un gruppo di lavoro come squilibrio fra ciò che il lavoro chiede e le risorse che offre, come autonomia, sostegno dei colleghi e chiarezza dei compiti. Ne segue che si può intervenire riducendo le richieste oppure aumentando le risorse, e che la seconda strada è spesso più praticabile.","leve":["car","rig"],"macro":"ben","microtemi":["richieste-risorse","esaurimento","coinvolgimento","risorse del lavoro","benessere organizzativo"],"motivi":{"benessere organizzativo":"È uno dei modelli più usati per misurare e spiegare il benessere delle persone al lavoro.","coinvolgimento":"Il modello mostra che le risorse del lavoro, come autonomia e sostegno, aumentano il coinvolgimento delle persone.","esaurimento":"Il modello spiega l'esaurimento come conseguenza di richieste elevate e prolungate senza risorse adeguate.","richieste-risorse":"È l'articolo che presenta in forma sistematica il modello richieste-risorse del lavoro.","risorse del lavoro":"Definisce le risorse del lavoro come gli aspetti che aiutano a raggiungere gli obiettivi e riducono il costo delle richieste."},"organizzazioni":[],"prova":"teoria","sinossi":"Il modello richieste-risorse allarga quello di Karasek: ogni aspetto di un lavoro può essere una richiesta che costa energia o una risorsa che aiuta a raggiungere gli obiettivi e a crescere. Le richieste alte e prolungate alimentano un processo di logoramento che porta all'esaurimento; le risorse alimentano un processo motivazionale che porta al coinvolgimento. Le risorse attenuano l'effetto delle richieste e contano di più proprio quando le richieste sono alte. La flessibilità del modello lo ha reso uno dei più usati al mondo nella psicologia del lavoro. La stessa flessibilità è il suo limite: quasi tutto può essere letto come richiesta o come risorsa.","tipo":"articolo","titolo":"The job demands-resources model","url":"https://doi.org/10.1108/02683940710733115","id":"bakker-demerouti"},{"anno":2008,"area":"nat","autori":"Michele Ballerini e colleghi","autoriIds":["michele-ballerini"],"collegamenti":["gordon","weick"],"concetti":["lavoro di squadra","coordinamento senza centro"],"contesto":["uccelli"],"creata":"2026-11-04","doi":"10.1073/pnas.0711437105","etichetta":"Ballerini et al.","evidenza":"funzionale","fonte":"«Interaction ruling animal collective behavior depends on topological rather than metric distance», PNAS, 105, 2008","inAzienda":"Per reagire in fretta a un cambiamento esterno non serve che ogni persona comunichi con tutte le altre, né che ogni informazione passi dal vertice. Basta che ciascuno sappia con chi deve coordinarsi direttamente e abbia con quelle poche persone un canale rapido e affidabile.","leve":["app","rel"],"macro":"tra","microtemi":["coordinamento","stormo","vicini topologici","risposta rapida","reti locali"],"motivi":{"coordinamento":"Lo studio spiega come migliaia di storni coordinano il volo senza che nessuno veda lo stormo intero né lo guidi.","reti locali":"Ogni storno regola il volo solo sui vicini, e da queste interazioni locali nasce il comportamento coordinato dell'intero stormo.","risposta rapida":"Gli autori mostrano che regolarsi su un numero fisso di vicini mantiene lo stormo compatto, condizione che gli permette di reagire insieme a un predatore.","stormo":"Le misure riguardano stormi reali di storni, ripresi in volo sopra Roma con fotocamere sincronizzate.","vicini topologici":"Ogni uccello si regola su sei o sette vicini scelti per posizione, qualunque sia la loro distanza in metri."},"organizzazioni":[],"prova":"osservazione sul campo","sinossi":"Gli stormi di storni che d'inverno volteggiano sopra Roma si muovono come un corpo solo, anche quando contano migliaia di uccelli. Un gruppo di fisici italiani, primo autore Michele Ballerini, ha ricostruito in tre dimensioni, con fotografie scattate da più punti insieme, la posizione di ogni uccello in diversi stormi. Hanno scoperto che ogni storno regola il proprio volo su un numero fisso di vicini, in media sei o sette, qualunque sia la distanza a cui si trovano, e non su tutti quelli entro un certo raggio. Questa regola rende lo stormo più compatto e più pronto a reagire quando la sua densità cambia, per esempio all'arrivo di un predatore. Lo studio è un esempio raro di comportamento collettivo misurato in natura e non solo simulato.","tipo":"articolo","titolo":"Interaction ruling animal collective behavior depends on topological rather than metric distance","url":"https://doi.org/10.1073/pnas.0711437105","id":"ballerini"},{"anno":1977,"area":"lav","autori":"Albert Bandura","autoriIds":["albert-bandura"],"collegamenti":["deci-ryan","kegan-lahey"],"concetti":["autoefficacia","cambiamento personale"],"contesto":["clinica"],"creata":"2026-11-04","doi":"10.1037/0033-295x.84.2.191","etichetta":"Bandura","evidenza":"","fonte":"«Self-efficacy: toward a unifying theory of behavioral change», Psychological Review, 84, 1977","inAzienda":"Le persone affrontano un cambiamento più volentieri se hanno già sperimentato di riuscirci. Per questo un percorso di sviluppo funziona meglio se è fatto di passi brevi, con risultati visibili e riconosciuti, che di grandi obiettivi annunciati.","leve":["app"],"macro":"ind","microtemi":["autoefficacia","esperienze di successo","modellamento","fiducia in sé","cambiamento di comportamento"],"motivi":{"autoefficacia":"È l'articolo in cui Bandura introduce il concetto di autoefficacia, cioè la convinzione di saper svolgere con successo un compito.","cambiamento di comportamento":"La teoria nasce per spiegare perché alcune persone riescono a cambiare un comportamento e altre no.","esperienze di successo":"Bandura indica le esperienze di riuscita come la fonte più forte di fiducia nelle proprie capacità.","fiducia in sé":"L'autoefficacia è una fiducia in sé specifica: riguarda la capacità di compiere una determinata azione, non il valore generale della persona.","modellamento":"Osservare una persona simile a sé che riesce è, secondo Bandura, una delle quattro fonti dell'autoefficacia."},"organizzazioni":[],"prova":"teoria","sinossi":"Albert Bandura propone di spiegare il cambiamento di comportamento con un'unica variabile, l'autoefficacia, cioè la convinzione di saper eseguire con successo l'azione richiesta. Chi si sente capace affronta il compito, insiste davanti agli ostacoli e tollera la fatica; chi non si sente capace evita o abbandona, anche quando avrebbe le competenze. L'autoefficacia si costruisce da quattro fonti: le esperienze di riuscita, che sono la più forte, l'osservazione di altri simili che riescono, la persuasione verbale e la lettura dei propri stati fisici. L'articolo nasce dal lavoro clinico sulle fobie ed è stato poi esteso alla scuola, allo sport e al lavoro. È uno dei testi più citati della psicologia, e le scale di autoefficacia sono strumenti di misura molto usati.","tipo":"articolo","titolo":"Self-efficacy: toward a unifying theory of behavioral change","url":"https://doi.org/10.1037/0033-295x.84.2.191","id":"bandura"},{"anno":1985,"area":"lea","autori":"Bernard M. Bass","autoriIds":["bernard-m-bass"],"collegamenti":["heifetz","pearce-conger","mech"],"concetti":["stile di guida"],"contesto":["imprese","esercito"],"creata":"2026-11-04","etichetta":"Bass","evidenza":"","fonte":"Leadership and Performance Beyond Expectations, Free Press, 1985","inAzienda":"Un responsabile che si limita a premiare e correggere ottiene le prestazioni concordate, ma raramente qualcosa di più. Chi dà un senso al lavoro e investe nella crescita dei collaboratori ottiene più impegno, e la formazione dei capi dovrebbe sviluppare questa seconda capacità.","leve":["gui"],"macro":"lea","microtemi":["leadership trasformazionale","leadership transazionale","ispirazione","stile di guida","sviluppo dei collaboratori"],"organizzazioni":[],"prova":"teoria","sinossi":"Bernard Bass riprende una distinzione proposta dallo storico James MacGregor Burns e la porta nello studio delle organizzazioni. La leadership transazionale funziona come uno scambio: premi e correzioni in cambio della prestazione attesa. La leadership trasformazionale va oltre lo scambio: ispira, dà un senso al lavoro, spinge a pensare in modo nuovo e presta attenzione alla crescita di ciascuno, e così ottiene prestazioni superiori alle attese. Bass costruisce anche un questionario per misurare i due stili, il Multifactor Leadership Questionnaire, che diventerà lo strumento più usato del settore. Le ricerche successive confermano un legame fra stile trasformazionale e risultati, ma criticano la difficoltà di distinguere bene le sue componenti.","tipo":"libro","titolo":"Leadership and Performance Beyond Expectations","url":"https://openlibrary.org/works/OL2421691W","id":"bass"},{"anno":1972,"area":"sis","autori":"Gregory Bateson","autoriIds":["gregory-bateson"],"collegamenti":["wiener","argyris-schon","maturana-varela"],"concetti":["apprendimento organizzativo","costruzione di senso","comunicazione"],"contesto":["sistemi"],"creata":"2026-11-04","etichetta":"Bateson","evidenza":"","fonte":"Steps to an Ecology of Mind, Chandler, 1972 (trad. it. Verso un'ecologia della mente, Adelphi)","inAzienda":"Molti problemi che si ripresentano in azienda non dipendono da un errore di esecuzione, ma dalle regole e dalle abitudini che quell'errore lo producono. Correggere l'errore senza cambiare le regole significa ritrovarlo poco tempo dopo.","leve":["app","rel"],"macro":"app","microtemi":["livelli di apprendimento","doppio legame","comunicazione","ecologia della mente","contesto"],"organizzazioni":[],"prova":"saggio","sinossi":"La raccolta riunisce saggi scritti in trent'anni da Gregory Bateson, antropologo, studioso della comunicazione e pioniere della cibernetica. L'idea che li lega è che mente, relazioni e ambiente formino un unico sistema, e che un comportamento non si capisca separandolo dal contesto in cui avviene. Bateson descrive diversi livelli di apprendimento, fino all'imparare a imparare, e propone il concetto di doppio legame, la trappola di chi riceve messaggi contraddittori senza poterli commentare. Il libro è difficile e poco sistematico, ma ha influenzato la terapia familiare, gli studi sull'apprendimento organizzativo e il pensiero ecologico. Va letto come una miniera di idee più che come una teoria verificata.","tipo":"libro","titolo":"Steps to an Ecology of Mind","url":"https://press.uchicago.edu/ucp/books/book/chicago/S/bo3620295.html","id":"bateson"},{"anno":2007,"area":"lav","autori":"Talya N. Bauer, Todd Bodner, Berrin Erdogan, Donald M. Truxillo, Jennifer S. Tucker","autoriIds":["talya-n-bauer","todd-bodner","berrin-erdogan","donald-m-truxillo","jennifer-s-tucker"],"collegamenti":["bandura","rousseau"],"concetti":["appartenenza","autoefficacia","lavoro di squadra"],"contesto":["imprese"],"creata":"2026-11-05","doi":"10.1037/0021-9010.92.3.707","etichetta":"Bauer et al.","evidenza":"","fonte":"Journal of Applied Psychology, 92(3), 707-721, 2007","inAzienda":"Un buon inserimento non è un pacchetto di documenti ma la costruzione rapida di chiarezza sul ruolo, fiducia nelle proprie capacità e legami con i colleghi.","leve":["rel","app"],"macro":"ind","microtemi":["onboarding","appartenenza","autoefficacia","turnover","ruoli"],"motivi":{"appartenenza":"L'accettazione sociale è una delle tre facce dell'adattamento.","autoefficacia":"La fiducia nelle proprie capacità media gli effetti dell'inserimento.","onboarding":"È la meta-analisi di riferimento sull'inserimento dei nuovi assunti.","ruoli":"La chiarezza del ruolo è una condizione centrale del modello.","turnover":"Fra gli esiti ci sono l'intenzione di restare e le dimissioni."},"organizzazioni":[],"prova":"meta-analisi","sinossi":"Talya Bauer, della Portland State University, e colleghi si chiedono come i nuovi assunti si inseriscano nell'organizzazione e che cosa decida il successo di questo passaggio. Mettono alla prova un modello con tecniche meta-analitiche e modelli di percorso su 70 campioni indipendenti di nuovi arrivati. Nel modello l'adattamento del nuovo assunto ha tre facce: la chiarezza del ruolo, la fiducia nelle proprie capacità e l'accettazione sociale da parte dei colleghi. Queste tre condizioni fanno da ponte fra le tattiche di inserimento dell'organizzazione e la ricerca di informazioni del nuovo assunto, da una parte, e gli esiti come soddisfazione, impegno, prestazione, intenzione di restare e dimissioni, dall'altra. I risultati sostengono in generale il modello. Gli autori mostrano anche che alcuni aspetti dei metodi di ricerca, come i dati longitudinali o trasversali e il passaggio dalla scuola al lavoro o da un lavoro all'altro, cambiano la forza delle relazioni. Molte misure sono autodichiarate e gli studi inclusi sono di qualità diversa.","tipo":"articolo","titolo":"Newcomer adjustment during organizational socialization: A meta-analytic review of antecedents, outcomes, and methods","url":"https://doi.org/10.1037/0021-9010.92.3.707","id":"bauer-2007-newcomer"},{"anno":2007,"area":"evo","autori":"Morten Bennedsen, Kasper Meisner Nielsen, Francisco Pérez-González, Daniel Wolfenzon","autoriIds":["morten-bennedsen","kasper-meisner-nielsen","francisco-perez-gonzalez","daniel-wolfenzon"],"collegamenti":["lebretonmiller-2004-succession","simon"],"concetti":["impresa familiare","decisione collettiva","carico di lavoro"],"contesto":["impresa familiare"],"creata":"2026-11-05","doi":"10.1162/qjec.122.2.647","etichetta":"Bennedsen et al.","evidenza":"","fonte":"The Quarterly Journal of Economics, 122(2), 647-691, 2007","inAzienda":"Nel passaggio generazionale conviene separare la proprietà dalla guida operativa e valutare i candidati familiari con gli stessi criteri usati per quelli esterni.","leve":["gui"],"macro":"cul","microtemi":["passaggio generazionale","impresa familiare","successione familiare","decisione","costi nascosti"],"motivi":{"costi nascosti":"Il calo di redditività dopo una successione in famiglia è un costo che di solito non si mette a bilancio.","decisione":"La scelta del successore è la decisione studiata.","impresa familiare":"Usa dati che collegano imprese e famiglie danesi.","passaggio generazionale":"Misura gli effetti della successione al vertice in famiglia.","successione familiare":"Confronta successori familiari ed esterni."},"organizzazioni":[],"prova":"studio osservazionale","sinossi":"Morten Bennedsen, della Copenhagen Business School, e colleghi usano un insieme di dati unico, che collega imprese e famiglie in Danimarca, per capire come le caratteristiche della famiglia influenzano le decisioni dell'impresa. Si concentrano sulla scelta di affidare la guida a un amministratore delegato della famiglia oppure esterno. Per separare la causa dall'effetto sfruttano il sesso del primo figlio dell'amministratore uscente: quando il primo figlio è maschio la guida passa più spesso a un familiare, ma il sesso del primo figlio non dovrebbe influire da solo sui risultati dell'impresa. Trovano che la successione in famiglia ha un forte effetto negativo sui risultati: la redditività operativa sulle attività scende di almeno quattro punti percentuali attorno al passaggio. Il danno è maggiore nei settori in rapida crescita, in quelli con lavoratori molto qualificati e nelle imprese più grandi. Lo studio è diventato centrale nel dibattito sulla professionalizzazione delle imprese familiari. Riguarda un solo paese, misura la redditività e non altri valori che le famiglie possono perseguire, e la variabile usata rispecchia norme di genere del periodo studiato.","tipo":"articolo","titolo":"Inside the Family Firm: The Role of Families in Succession Decisions and Performance","url":"https://doi.org/10.1162/qjec.122.2.647","id":"bennedsen-2007-family"},{"anno":1997,"area":"nat","autori":"Janine M. Benyus","autoriIds":["janine-m-benyus"],"collegamenti":["meadows"],"concetti":["biomimesi","diffusione delle innovazioni","connessione con la natura","design biofilico"],"contesto":["natura"],"creata":"2026-11-04","etichetta":"Benyus","evidenza":"","fonte":"Biomimicry, William Morrow, 1997","inAzienda":"Davanti a un problema di progettazione, che riguardi un prodotto o un processo, ci si può chiedere come un sistema vivente ha risolto un problema simile. La natura diventa così una fonte di soluzioni da verificare, non un elemento decorativo.","leve":["rel","car","gui","app","rig"],"macro":"tra","microtemi":["biomimesi","natura come modello","innovazione","sostenibilità","design"],"organizzazioni":["Biomimicry Institute"],"prova":"saggio","sinossi":"Janine Benyus, biologa e divulgatrice americana, dà un nome e un programma alla biomimesi: osservare forme, processi e sistemi naturali per risolvere problemi umani. Il libro presenta esempi in molti campi, dall'agricoltura che imita la prateria alla chimica che lavora a temperatura ambiente come le cellule, fino all'impresa che usa energia e materiali come un sistema naturale maturo. Benyus propone di considerare la natura insieme come modello, come misura e come maestra. Dopo il libro ha fondato il Biomimicry Institute e una società di consulenza. È un testo divulgativo e programmatico, non una ricerca: molti esempi sono promettenti più che dimostrati.","tipo":"libro","titolo":"Biomimicry","url":"https://openlibrary.org/works/OL3357280W","id":"benyus"},{"anno":1968,"area":"sis","autori":"Ludwig von Bertalanffy","autoriIds":["ludwig-von-bertalanffy"],"collegamenti":["katz-kahn","ashby","meadows"],"concetti":["sistemi aperti"],"contesto":["sistemi"],"creata":"2026-11-04","etichetta":"Bertalanffy","evidenza":"","fonte":"General System Theory, Braziller, 1968","inAzienda":"Un problema che si manifesta in un reparto, come ritardi o tensioni, spesso nasce dagli scambi di quel reparto con gli altri o con l'esterno. Per capirlo bisogna quindi osservare i flussi di informazioni, materiali e persone che lo attraversano, non solo il reparto stesso.","leve":["app"],"macro":"tra","microtemi":["sistema aperto","scambio con l'ambiente","olismo","equifinalità","interdipendenza"],"organizzazioni":[],"prova":"teoria","sinossi":"Ludwig von Bertalanffy, biologo austriaco, raccoglie in questo libro trent'anni di lavoro su un'idea: esistono principi comuni a sistemi molto diversi, dalle cellule agli organismi alle società. Il concetto centrale è il sistema aperto, che scambia di continuo materia, energia e informazione con l'ambiente e per questo può mantenersi e crescere invece di degradarsi. Un sistema aperto può raggiungere lo stesso stato finale partendo da condizioni diverse e per strade diverse, una proprietà che Bertalanffy chiama equifinalità. Contro l'abitudine di scomporre in parti isolate, propone di studiare le relazioni fra le parti. Il libro ha fondato la teoria generale dei sistemi e ha ispirato direttamente la psicologia delle organizzazioni di Katz e Kahn.","tipo":"libro","titolo":"General System Theory","url":"https://openlibrary.org/works/OL6332394W","id":"bertalanffy"},{"anno":2014,"area":"lea","autori":"Nadine Bienefeld e Gudela Grote","autoriIds":["nadine-bienefeld","gudela-grote"],"collegamenti":["pearce-conger","ashby","seeley-nido","ostrom"],"concetti":["guida distribuita","resilienza","decentralizzazione"],"contesto":["aviazione"],"creata":"2026-11-04","doi":"10.1177/0018720813488137","etichetta":"Bienefeld e Grote","evidenza":"","fonte":"«Shared leadership in multiteam systems», Human Factors, 56, 2014","inAzienda":"La guida condivisa migliora i risultati nelle situazioni complesse, ma solo se resta chiaro chi prende la decisione finale. In azienda conviene quindi distribuire la guida nelle attività variabili e lasciarla accentrata dove gli errori sono gravi e le procedure devono essere seguite.","leve":["gui"],"macro":"lea","microtemi":["guida distribuita","emergenza","sistemi multi-team","responsabilità finale","quando decentrare"],"motivi":{"emergenza":"Gli equipaggi studiati affrontavano emergenze simulate, situazioni in cui un errore di coordinamento ha conseguenze gravi.","guida distribuita":"Lo studio misura chi esercita comportamenti di guida in ogni momento e mostra che la guida passa da una persona all'altra.","quando decentrare":"I risultati indicano in quali gruppi e in quali momenti condividere la guida migliora la prestazione.","responsabilità finale":"La guida condivisa ha funzionato quando restava chiaro il ruolo del comandante, responsabile della decisione finale.","sistemi multi-team":"L'unità di analisi è l'insieme di due squadre, i piloti e gli assistenti di volo, che devono coordinarsi fra loro."},"organizzazioni":[],"prova":"osservazione sul campo","sinossi":"Nadine Bienefeld e Gudela Grote studiano la guida condivisa in situazioni in cui sbagliare costa caro: equipaggi aerei impegnati in emergenze simulate, con piloti in cabina di pilotaggio e assistenti di volo in cabina passeggeri che devono coordinarsi fra loro. Osservano 84 equipaggi e registrano chi esercita comportamenti di guida in ogni momento. La guida condivisa migliorava i risultati fra gli assistenti di volo, mentre fra i piloti contava soprattutto la guida del comandante. La conclusione è che la guida distribuita funziona se resta bilanciata con quella del capo formale: si condividono compiti di guida, non la responsabilità finale. Lo studio è condotto in simulazione e riguarda un contesto molto strutturato.","tipo":"articolo","titolo":"Shared leadership in multiteam systems","url":"https://doi.org/10.1177/0018720813488137","id":"bienefeld-grote"},{"anno":2015,"area":"lav","autori":"Nicholas Bloom, James Liang, John Roberts, Zhichun Jenny Ying","autoriIds":["nicholas-bloom","james-liang","john-roberts","zhichun-jenny-ying"],"collegamenti":["bloom-2024-hybrid","karasek"],"composto":false,"concetti":["lavoro a distanza e ibrido","trasformazione digitale","appartenenza","carico di lavoro"],"contesto":["servizi","assistenza clienti"],"creata":"2026-11-05","doi":"10.1093/qje/qju032","esito":"Prestazioni più alte del 13 per cento e dimissioni dimezzate, ma meno promozioni a parità di prestazione; dopo la nuova scelta più della metà dei partecipanti ha cambiato modalità e il guadagno è salito al 22 per cento.","etichetta":"Bloom et al.","evidenza":"","fonte":"The Quarterly Journal of Economics, 130(1), 165-218, 2015","inAzienda":"Una nuova forma di lavoro va sperimentata con un gruppo di controllo e poi lasciata scegliere di nuovo alle persone, perché la scelta informata migliora i risultati.","intervento":"Esperimento di nove mesi con i volontari assegnati a caso al lavoro da casa o in ufficio, seguito dall'estensione dell'opzione a tutta l'azienda e da una nuova scelta dei partecipanti.","leve":["car","rig"],"macro":"cam","microtemi":["lavoro a distanza","trasformazione digitale","turnover","produttività","esperimento di campo"],"motivi":{"esperimento di campo":"L'assegnazione al lavoro da casa è casuale dentro l'azienda.","lavoro a distanza":"È l'esperimento più citato sul lavoro da casa prima della pandemia.","produttività":"La prestazione cresce del 13 per cento, poi del 22.","trasformazione digitale":"Il lavoro da casa è reso possibile dalla tecnologia e cambia l'organizzazione del call center.","turnover":"Le dimissioni dei lavoratori da casa si dimezzano."},"organizzazioni":["Ctrip (Trip.com)"],"problema":"L'azienda aveva costi alti per gli uffici di Shanghai e un turnover elevato fra gli operatori, e voleva capire se il lavoro da casa avrebbe abbassato la produttività.","prova":"esperimento di campo","settore":"Agenzia di viaggi, call center (Cina)","sinossi":"Il caso riguarda Ctrip, un'agenzia di viaggi cinese quotata con circa 16.000 dipendenti, che voleva ridurre i costi degli uffici e il turnover del suo call center. Gli operatori che si offrivano volontari sono stati assegnati a caso al lavoro da casa o in ufficio per nove mesi. Il lavoro da casa ha aumentato le prestazioni del 13 per cento: 9 punti vengono da più minuti lavorati per turno, con meno pause e meno giorni di malattia, e 4 da più chiamate al minuto, attribuite a un ambiente più tranquillo. I lavoratori da casa erano più soddisfatti e le loro dimissioni si sono dimezzate, ma a parità di prestazione sono stati promossi meno. Dopo l'esperimento l'azienda ha esteso l'opzione a tutti e ha lasciato scegliere di nuovo ai partecipanti, e più della metà ha cambiato scelta, con un guadagno complessivo salito al 22 per cento. Lo studio mostra quanto contino l'apprendimento e la scelta personale quando si introduce una pratica organizzativa nuova. Riguarda un lavoro misurabile e ripetitivo, in un'azienda e in un paese specifici, prima della pandemia.","tipo":"caso","titolo":"Does Working from Home Work? Evidence from a Chinese Experiment","url":"https://doi.org/10.1093/qje/qju032","id":"bloom-2015-home"},{"anno":2024,"area":"lav","autori":"Nicholas Bloom, Ruobing Han, James Liang","autoriIds":["nicholas-bloom","ruobing-han","james-liang"],"collegamenti":["rousseau","hirschman"],"concetti":["lavoro a distanza e ibrido","appartenenza","silenzio organizzativo"],"contesto":["servizi","tecnologia"],"creata":"2026-11-05","doi":"10.1038/s41586-024-07500-2","etichetta":"Bloom et al.","evidenza":"","fonte":"Nature, 630(8018), 920-925, 2024","inAzienda":"Prima di imporre il ritorno in ufficio conviene provare uno schema ibrido con un gruppo di controllo e misurare dimissioni e prestazioni.","leve":["rig","car"],"macro":"cam","microtemi":["lavoro ibrido","lavoro a distanza","turnover","convinzioni manageriali","esperimento di campo"],"motivi":{"convinzioni manageriali":"I manager cambiano opinione sugli effetti del lavoro ibrido dopo averlo visto.","esperimento di campo":"È un esperimento con assegnazione casuale dentro un'azienda vera.","lavoro a distanza":"La parte a distanza è l'intervento studiato.","lavoro ibrido":"Prova sperimentalmente uno schema di due giorni a casa alla settimana.","turnover":"Il risultato principale è la riduzione di un terzo delle dimissioni."},"organizzazioni":["Ctrip (Trip.com)"],"prova":"esperimento di campo","sinossi":"Il lavoro ibrido, con alcuni giorni a casa e altri in ufficio, riguarda ormai decine di milioni di persone, ma molti dirigenti temono che danneggi produttività, innovazione e carriere. Gli autori conducono per sei mesi, fra il 2021 e il 2022, un esperimento controllato con assegnazione casuale su 1.612 dipendenti di un'azienda tecnologica cinese, in cui una parte lavora da casa due giorni alla settimana. Il lavoro ibrido aumenta la soddisfazione e riduce di un terzo le dimissioni, con effetti più forti per i non dirigenti, le donne e chi ha un tragitto lungo. Test di equivalenza mostrano che nei due anni successivi non cambiano le valutazioni delle prestazioni né le promozioni, e per gli ingegneri non cambia neppure la quantità di codice scritto. I 395 manager coinvolti cambiano opinione: prima dell'esperimento stimavano un effetto negativo sulla produttività, dopo un piccolo effetto positivo. È uno dei pochi studi sperimentali solidi sul lavoro ibrido. Riguarda una sola azienda e soprattutto ruoli tecnici e di ufficio, e lo schema provato è di due giorni a casa.","tipo":"articolo","titolo":"Hybrid working from home improves retention without damaging performance","url":"https://doi.org/10.1038/s41586-024-07500-2","id":"bloom-2024-hybrid"},{"anno":1999,"area":"nat","autori":"Eric Bonabeau, Marco Dorigo, Guy Theraulaz","autoriIds":["eric-bonabeau","marco-dorigo","guy-theraulaz"],"collegamenti":["gordon","seeley"],"concetti":["coordinamento senza centro","regolazione distribuita","biomimesi"],"contesto":["insetti sociali"],"creata":"2026-11-04","doi":"10.1093/oso/9780195131581.001.0001","etichetta":"Bonabeau et al.","evidenza":"funzionale","fonte":"Oxford University Press, New York, 1999","inAzienda":"Molti flussi di lavoro ripetitivi possono regolarsi da soli se le informazioni sullo stato del lavoro sono visibili a tutti, come una lavagna con le attività in attesa. In questo modo il responsabile non deve assegnare ogni compito e può concentrarsi sulle eccezioni.","leve":["gui","car"],"macro":"lea","microtemi":["intelligenza collettiva","coordinamento senza capo","divisione del lavoro","biomimesi"],"motivi":{},"organizzazioni":[],"prova":"teoria","sinossi":"Eric Bonabeau, Marco Dorigo e Guy Theraulaz raccolgono le ricerche su come formiche, api, vespe e termiti risolvono problemi difficili senza che nessuno abbia il quadro d'insieme. Trovare il percorso più breve verso il cibo, dividersi i compiti, smistare le larve, costruire il nido: ogni volta il risultato nasce da regole semplici seguite da molti individui e da tracce lasciate nell'ambiente, come le piste di feromone. Gli autori chiamano questa capacità intelligenza dello sciame e mostrano come abbia ispirato algoritmi di ottimizzazione, fra cui quelli basati sulle colonie di formiche ideati dallo stesso Dorigo, e sistemi di robot che collaborano. Il libro è tecnico in molte parti ma resta il testo di riferimento del campo.","tipo":"libro","titolo":"Swarm Intelligence: From Natural to Artificial Systems","url":"https://doi.org/10.1093/oso/9780195131581.001.0001","id":"bonabeau-1999-swarm"},{"anno":2014,"area":"nat","autori":"Mohamed Boubekri, Ivy N. Cheung, Kathryn J. Reid, Chia-Hui Wang, Phyllis C. Zee","autoriIds":["mohamed-boubekri","ivy-n-cheung","kathryn-j-reid","chia-hui-wang","phyllis-c-zee"],"collegamenti":["ulrich"],"concetti":["luce naturale","recupero","design biofilico"],"contesto":["uffici"],"creata":"2026-11-04","doi":"10.5664/jcsm.3780","etichetta":"Boubekri et al.","evidenza":"diretta","fonte":"Journal of Clinical Sleep Medicine, 10(6), 603-611, 2014","inAzienda":"La posizione delle scrivanie rispetto alle finestre incide sulla quantità di luce naturale che le persone ricevono, e quindi sul loro sonno e sulla loro energia. Assegnare le postazioni vicine alle finestre a chi passa più ore alla scrivania è una scelta che riguarda la salute, non solo il comfort.","leve":["rig"],"macro":"ben","microtemi":["luce naturale","ritmi circadiani","sonno","spazi di lavoro"],"motivi":{},"organizzazioni":[],"prova":"studio osservazionale","sinossi":"Mohamed Boubekri e un gruppo di ricercatori dell'Università dell'Illinois e della Northwestern University confrontano impiegati che lavorano in uffici con finestre e colleghi che lavorano in ambienti senza finestre. I primi ricevono molta più luce naturale durante l'orario di lavoro e, secondo le misure raccolte con sensori da polso, dormono di più nelle notti dei giorni lavorativi, circa tre quarti d'ora in più. Riferiscono anche una qualità della vita migliore sugli aspetti fisici e sulla vitalità. Lo studio è un pilota su meno di cinquanta persone e non può escludere che chi ha la finestra differisca dagli altri anche per ruolo o mansione.","tipo":"articolo","titolo":"Impact of windows and daylight exposure on overall health and sleep quality of office workers: a case-control pilot study","url":"https://doi.org/10.5664/jcsm.3780","id":"boubekri-2014-daylight"},{"anno":2015,"area":"nat","autori":"Gregory N. Bratman, J. Paul Hamilton, Kevin S. Hahn, Gretchen C. Daily, James J. Gross","autoriIds":["gregory-n-bratman","j-paul-hamilton","kevin-s-hahn","gretchen-c-daily","james-j-gross"],"collegamenti":["kaplan"],"concetti":["recupero","immersione nel bosco"],"contesto":["città","natura"],"creata":"2026-11-04","doi":"10.1073/pnas.1510459112","etichetta":"Bratman et al.","evidenza":"diretta","fonte":"Proceedings of the National Academy of Sciences, 112(28), 8567-8572, 2015","inAzienda":"Quando un gruppo o una persona continua a girare intorno allo stesso problema senza venirne a capo, una camminata in un ambiente verde può ridurre il rimuginio e rendere possibile una conversazione diversa. Per questo alcuni colloqui e riunioni conviene farli camminando all'aperto.","leve":["rig"],"macro":"ben","microtemi":["ruminazione","camminata","recupero dallo stress","salute mentale"],"motivi":{},"organizzazioni":[],"prova":"esperimento di campo","sinossi":"Gregory Bratman e i suoi colleghi dell'Università di Stanford chiedono a un gruppo di volontari di camminare per novanta minuti, alcuni in una zona verde vicino al campus, altri lungo una strada a quattro corsie trafficata. Prima e dopo la passeggiata misurano la ruminazione, cioè la tendenza a tornare con il pensiero sugli aspetti negativi di sé, e osservano con la risonanza magnetica il flusso di sangue nella corteccia prefrontale subgenuale, un'area associata a questo rimuginio. Dopo la camminata nel verde la ruminazione riferita diminuisce e l'attività dell'area si riduce, mentre dopo la camminata urbana non cambia nulla. Il campione è piccolo, meno di quaranta persone, e il risultato aspetta conferme più ampie.","tipo":"articolo","titolo":"Nature experience reduces rumination and subgenual prefrontal cortex activation","url":"https://doi.org/10.1073/pnas.1510459112","id":"bratman-2015-rumination"},{"anno":2009,"area":"nat","autori":"Tina Bringslimark, Terry Hartig, Grete G. Patil","autoriIds":["tina-bringslimark","terry-hartig","grete-g-patil"],"collegamenti":["ulrich","kaplan"],"concetti":["piante negli uffici","design biofilico","recupero"],"contesto":["uffici","sanità"],"creata":"2026-11-04","doi":"10.1016/j.jenvp.2009.05.001","etichetta":"Bringslimark et al.","evidenza":"diretta","fonte":"Journal of Environmental Psychology, 29(4), 422-433, 2009","inAzienda":"Mettere piante negli uffici può migliorare un po' il benessere percepito, ma le prove sono deboli e discordanti. Non può sostituire interventi sui carichi di lavoro, sui ritmi e sull'organizzazione.","leve":["rig"],"macro":"ben","microtemi":["piante indoor","spazi di lavoro","recupero dallo stress","evidenze deboli"],"motivi":{},"organizzazioni":[],"prova":"rassegna","sinossi":"Tina Bringslimark, Terry Hartig e Grete Patil esaminano gli esperimenti pubblicati sugli effetti psicologici delle piante negli ambienti chiusi, come uffici, ospedali e aule. Alcuni studi trovano benefici su stress, tolleranza al dolore e prestazione nei compiti, altri non trovano nulla, e molti hanno campioni piccoli, durate brevi o confronti poco controllati. Gli autori concludono che le prove di un effetto positivo esistono ma sono discordanti, e chiedono ricerche disegnate meglio prima di trarre raccomandazioni generali. È una rassegna critica, utile proprio perché non si limita a celebrare il verde.","tipo":"articolo","titolo":"The psychological benefits of indoor plants: A critical review of the experimental literature","url":"https://doi.org/10.1016/j.jenvp.2009.05.001","id":"bringslimark-2009-plants"},{"anno":2014,"area":"nat","autori":"William Browning, Catherine Ryan, Joseph Clancy","autoriIds":["william-browning","catherine-ryan","joseph-clancy"],"collegamenti":["ulrich","kaplan"],"concetti":["design biofilico","vista sul verde","luce naturale"],"contesto":["uffici","architettura"],"creata":"2026-11-04","doi":"","etichetta":"Browning et al.","evidenza":"diretta","fonte":"Terrapin Bright Green, New York, 2014","inAzienda":"I quattordici schemi offrono una lista di controllo per valutare uffici, mense e spazi comuni: quanta luce naturale entra, che cosa si vede dalle finestre, quali materiali si usano, dove ci si può appartare. Su questa base si possono decidere interventi mirati e misurarne l'effetto.","leve":["rig"],"macro":"ben","microtemi":["design biofilico","vista sul verde","luce naturale","acqua","spazi di lavoro"],"motivi":{},"organizzazioni":["Terrapin Bright Green"],"prova":"rapporto tecnico","sinossi":"William Browning, Catherine Ryan e Joseph Clancy, della società di consulenza Terrapin Bright Green, ordinano in quattordici schemi i modi di portare la natura negli edifici. Li dividono in tre gruppi: la natura nello spazio, come la vista sul verde, l'acqua o la luce che cambia; gli analoghi naturali, come forme, materiali e motivi che ricordano la natura; la natura dello spazio, come il riparo, la vista ampia e il senso di mistero. Per ogni schema il rapporto indica gli studi su stress, attenzione ed emozioni che lo sostengono. È uno strumento di progettazione molto usato da architetti e uffici tecnici, ma le prove a favore sono solide per alcuni schemi e deboli per altri.","tipo":"rapporto","titolo":"14 Patterns of Biophilic Design","url":"https://www.terrapinbrightgreen.com/14-patterns/","id":"browning-2014-patterns"},{"anno":2025,"area":"evo","autori":"Erik Brynjolfsson, Danielle Li, Lindsey Raymond","autoriIds":["erik-brynjolfsson","danielle-li","lindsey-raymond"],"collegamenti":["simon","march"],"concetti":["intelligenza artificiale","trasformazione digitale","carico di lavoro","comunicazione","apprendimento organizzativo"],"contesto":["assistenza clienti","tecnologia"],"creata":"2026-11-05","doi":"10.1093/qje/qjae044","etichetta":"Brynjolfsson et al.","evidenza":"","fonte":"The Quarterly Journal of Economics, 140(2), 889-942, 2025","inAzienda":"Introdurre l'intelligenza artificiale generativa può alzare in fretta il livello dei nuovi assunti, ma chiede di proteggere il ruolo e la motivazione dei più esperti, il cui sapere alimenta lo strumento.","leve":["app","car"],"macro":"tra","microtemi":["intelligenza artificiale","trasformazione digitale","produttività","sapere tacito","apprendimento organizzativo"],"motivi":{"apprendimento organizzativo":"Mostra un apprendimento più rapido dei nuovi assunti mediato dalla tecnologia.","intelligenza artificiale":"Studia sul campo un assistente basato su intelligenza artificiale generativa usato da migliaia di operatori.","produttività":"Il risultato principale è l'aumento dei problemi risolti per ora.","sapere tacito":"Lo strumento sembra trasmettere ai nuovi le pratiche implicite dei migliori operatori.","trasformazione digitale":"Misura che cosa cambia in un servizio quando una tecnologia nuova entra nel lavoro quotidiano."},"organizzazioni":[],"prova":"esperimento di campo","sinossi":"Erik Brynjolfsson, della Stanford University, e Danielle Li e Lindsey Raymond, del Massachusetts Institute of Technology, seguono l'introduzione graduale di un assistente conversazionale basato sull'intelligenza artificiale generativa in un grande servizio di assistenza clienti, con i dati di 5.172 operatori. Poiché l'assistente arriva in momenti diversi nei vari gruppi, si può confrontare chi lo usa con chi non lo usa ancora. In media i problemi risolti per ora crescono del 15 per cento, ma l'effetto è molto diverso da persona a persona. Gli operatori meno esperti e meno abili migliorano sia la velocità sia la qualità, mentre i più esperti guadagnano poco in velocità e perdono un poco in qualità. Lo strumento sembra trasmettere ai nuovi le pratiche dei migliori, come se distribuisse il loro sapere tacito, e i clienti diventano più cortesi e chiedono meno spesso di parlare con un responsabile. È uno dei primi studi sul campo su larga scala e ha spostato il dibattito dalla sostituzione del lavoro alla redistribuzione delle competenze. Riguarda una sola azienda e un compito molto strutturato, e non dice nulla sugli effetti di lungo periodo sull'apprendimento.","tipo":"articolo","titolo":"Generative AI at Work","url":"https://doi.org/10.1093/qje/qjae044","id":"brynjolfsson-2025-generative"},{"anno":1999,"area":"evo","autori":"Kim S. Cameron e Robert E. Quinn","autoriIds":["kim-s-cameron","robert-e-quinn"],"collegamenti":["schein","lawrence-lorsch"],"concetti":["cultura organizzativa","misura della cultura","cambiamento organizzativo"],"contesto":["imprese"],"creata":"2026-11-04","etichetta":"Cameron e Quinn","evidenza":"","fonte":"Diagnosing and Changing Organizational Culture, Addison-Wesley, 1999","inAzienda":"Il questionario permette di misurare in poco tempo la cultura attuale di un'azienda e quella che le persone desiderano. La distanza fra le due indica su quali aspetti concentrare un percorso di cambiamento, e ripetendo la misura alla fine si verifica se qualcosa è cambiato.","leve":["rel","gui","app","cul"],"macro":"cul","microtemi":["cultura organizzativa","valori in competizione","misura della cultura","flessibilità e controllo","cambiamento culturale"],"organizzazioni":[],"prova":"strumento di misura","sinossi":"Kim Cameron e Robert Quinn offrono uno strumento pratico per diagnosticare la cultura di un'organizzazione. Partono da un modello nato negli studi sull'efficacia organizzativa, il quadro dei valori in competizione, che dispone le organizzazioni lungo due assi: flessibilità o controllo, sguardo verso l'interno o verso l'esterno. Ne derivano quattro tipi di cultura: il clan, fondato sulla collaborazione; l'adhocrazia, fondata sull'innovazione; il mercato, fondato sul risultato; la gerarchia, fondata sulle regole. Con un questionario breve le persone descrivono la cultura attuale e quella desiderata, e la distanza fra le due diventa la base del piano di cambiamento. Lo strumento è molto diffuso e facile da usare, ma riduce la cultura a quattro profili e misura più i valori dichiarati che gli assunti profondi.","tipo":"libro","titolo":"Diagnosing and Changing Organizational Culture","url":"https://www.wiley.com/en-us/Diagnosing+and+Changing+Organizational+Culture%3A+Based+on+the+Competing+Values+Framework%2C+3rd+Edition-p-9780470650264","id":"cameron-quinn"},{"anno":2014,"area":"nat","autori":"Colin A. Capaldi, Raelyne L. Dopko, John M. Zelenski","autoriIds":["colin-a-capaldi","raelyne-l-dopko","john-m-zelenski"],"collegamenti":["lumber-2017-pathways"],"concetti":["connessione con la natura","motivazione intrinseca","benessere organizzativo"],"contesto":["natura"],"creata":"2026-11-04","doi":"10.3389/fpsyg.2014.00976","etichetta":"Capaldi et al.","evidenza":"diretta","fonte":"Frontiers in Psychology, 5, 976, 2014","inAzienda":"Le attività che rafforzano il legame delle persone con la natura possono contribuire al loro benessere, ma l'effetto atteso è piccolo. Vanno quindi proposte come una risorsa fra le altre, senza promettere cambiamenti radicali.","leve":["rig"],"macro":"ind","microtemi":["connessione con la natura","felicità","benessere","meta-analisi"],"motivi":{},"organizzazioni":[],"prova":"meta-analisi","sinossi":"Colin Capaldi, Raelyne Dopko e John Zelenski, della Carleton University in Canada, riuniscono in una meta-analisi gli studi che misurano insieme due cose: quanto le persone si sentono legate alla natura e quanto si dicono felici. L'associazione fra le due risulta piccola ma costante, e cambia poco a seconda dello strumento usato per misurare il legame con la natura. Gli studi raccolti sono quasi tutti correlazionali, quindi non dicono se il legame con la natura renda più felici o se le persone più serene cerchino di più la natura. Gli autori lo dichiarano e indicano la necessità di studi sperimentali e longitudinali.","tipo":"articolo","titolo":"The relationship between nature connectedness and happiness: a meta-analysis","url":"https://doi.org/10.3389/fpsyg.2014.00976","id":"capaldi-2014-connectedness"},{"anno":1948,"area":"cam","autori":"Lester Coch e John R.P. French","autoriIds":["lester-coch","john-r-p-french"],"collegamenti":["lewin","deci-ryan"],"concetti":["resistenza al cambiamento","partecipazione","carico di lavoro","appartenenza"],"contesto":["manifattura"],"creata":"2026-11-04","doi":"10.1177/001872674800100408","etichetta":"Coch e French","evidenza":"","fonte":"«Overcoming resistance to change», Human Relations, 1(4), 1948","inAzienda":"La resistenza a un nuovo modo di lavorare dipende in buona parte da come il cambiamento viene introdotto. Coinvolgere le persone nella definizione dei nuovi metodi riduce le resistenze e le uscite e accorcia il tempo necessario a tornare alla produttività precedente.","leve":["app","gui"],"macro":"cam","microtemi":["resistenza al cambiamento","partecipazione","produttività","turnover","esperimento di campo"],"motivi":{"esperimento di campo":"L'esperimento si svolse in una fabbrica vera, con operai al loro lavoro, e non in un laboratorio.","partecipazione":"I gruppi coinvolti nella definizione dei nuovi metodi recuperarono più in fretta la produttività e mostrarono meno resistenza.","produttività":"Il risultato principale misurato è il tempo necessario a tornare ai livelli di produzione precedenti al cambiamento.","resistenza al cambiamento":"È lo studio classico sulla resistenza delle persone ai cambiamenti di mansione e di metodo.","turnover":"Nel gruppo a cui il cambiamento era stato imposto, molte più persone lasciarono l'azienda nelle settimane successive."},"organizzazioni":["Harwood Manufacturing Corporation"],"prova":"esperimento di campo","sinossi":"Alla Harwood Manufacturing, una fabbrica di pigiami in Virginia, ogni cambio di metodo di lavoro provocava cali di produzione, lamentele e dimissioni. Coch e French confrontarono gruppi di operaie a cui il cambiamento veniva solo annunciato con gruppi che partecipavano, tramite rappresentanti o tutte insieme, a progettarlo. I gruppi che non partecipavano restarono a lungo sotto la produzione precedente, con ostilità verso i responsabili e molte uscite; quelli coinvolti recuperarono in fretta e superarono i livelli di partenza. Quando il gruppo di controllo fu coinvolto in un cambio successivo, si comportò come gli altri: la differenza stava nel metodo, non nelle persone. Una replica in una fabbrica norvegese trovò effetti più deboli, legati a quanto la partecipazione era considerata legittima dai lavoratori.","tipo":"articolo","titolo":"Overcoming resistance to change","url":"https://doi.org/10.1177/001872674800100408","id":"coch-french"},{"anno":2003,"area":"nat","autori":"Larissa Conradt, Timothy J. Roper","autoriIds":["larissa-conradt","timothy-j-roper"],"collegamenti":["seeley-nido","couzin-2005-leadership","janis","pearce-conger"],"concetti":["decisione collettiva","decentralizzazione","guida distribuita","mito del capo dominante","comunicazione"],"contesto":["animali sociali"],"creata":"2026-11-05","doi":"10.1038/nature01294","etichetta":"Conradt","evidenza":"formale","fonte":"Nature, 421(6919), 155-158, 2003","inAzienda":"La decisione centralizzata ha senso quando il gruppo è piccolo e uno ha informazioni nettamente migliori; negli altri casi il confronto riduce le scelte estreme.","leve":["gui"],"macro":"lea","microtemi":["decisione collettiva","quando decentrare","guida distribuita","dominanza","informazione"],"motivi":{"decisione collettiva":"Confronta decisioni prese da uno e decisioni prese dalla maggioranza.","dominanza":"Il dispotismo è uno dei due meccanismi messi a confronto.","guida distribuita":"Sostiene che le decisioni condivise siano più vantaggiose per il gruppo.","informazione":"La differenza di informazione fra individui decide quale meccanismo conviene.","quando decentrare":"Indica le condizioni in cui conviene seguire un solo individuo."},"organizzazioni":[],"prova":"modello matematico","sinossi":"Molti animali che vivono in gruppo devono prendere decisioni comuni, per esempio quando muoversi, in quale direzione andare o quale attività svolgere, ma si sapeva poco di come lo facciano. Conradt e Roper costruiscono un modello che confronta le conseguenze per la sopravvivenza di due meccanismi: il dispotismo, in cui decide un solo individuo, e la democrazia, in cui decide la maggioranza. Nella maggior parte delle condizioni i costi per i membri subordinati e per il gruppo nel suo insieme sono molto più alti con le decisioni dispotiche. Anche quando il despota è il membro più esperto, agli altri conviene seguirlo solo se il gruppo è piccolo e la differenza di informazione è grande. Le decisioni condivise sono vantaggiose soprattutto perché tendono a evitare le scelte estreme, più che perché ognuno conti. Gli autori prevedono che la decisione condivisa sia diffusa in natura e formulano previsioni verificabili. È un modello teorico, e le prove empiriche sono arrivate dopo e in parte lo hanno complicato.","tipo":"articolo","titolo":"Group decision-making in animals","url":"https://doi.org/10.1038/nature01294","id":"conradt-2003-group"},{"anno":2005,"area":"nat","autori":"Iain D. Couzin, Jens Krause, Nigel R. Franks, Simon A. Levin","autoriIds":["iain-d-couzin","jens-krause","nigel-r-franks","simon-a-levin"],"collegamenti":["gordon","seeley-nido","bienefeld-grote","ballerini"],"concetti":["guida distribuita","decisione collettiva","coordinamento senza centro"],"contesto":["animali sociali"],"creata":"2026-11-04","doi":"10.1038/nature03236","etichetta":"Couzin et al.","evidenza":"funzionale","fonte":"Nature, 433, 513-516, 2005","inAzienda":"In un gruppo la guida può passare spontaneamente a chi dispone dell'informazione giusta, senza che un capo lo stabilisca, purché le persone restino in contatto fra loro. Rendere visibile chi sa che cosa è quindi più utile che moltiplicare i livelli di comando.","leve":["gui"],"macro":"lea","microtemi":["guida distribuita","individui informati","decisione collettiva","coordinamento senza capo"],"motivi":{},"organizzazioni":[],"prova":"modello matematico","sinossi":"Iain Couzin, Jens Krause, Nigel Franks e Simon Levin costruiscono un modello al computer di animali che si muovono in gruppo, come banchi di pesci o stormi. Ogni individuo segue poche regole: evitare chi è troppo vicino, allinearsi ai vicini e restare unito al gruppo; alcuni individui sanno in quale direzione si trova una meta, gli altri no. Il modello mostra che una piccola quota di individui informati basta a guidare con precisione tutto il gruppo, senza segnali espliciti e senza che gli altri sappiano chi sia informato. Più il gruppo è numeroso, più piccola è la quota necessaria. Quando gli informati vogliono andare in direzioni diverse, il gruppo segue la maggioranza o un compromesso.","tipo":"articolo","titolo":"Effective leadership and decision-making in animal groups on the move","url":"https://doi.org/10.1038/nature03236","id":"couzin-2005-leadership"},{"anno":2000,"area":"lav","autori":"Edward L. Deci e Richard M. Ryan","autoriIds":["edward-l-deci","richard-m-ryan"],"collegamenti":["coch-french","bandura"],"concetti":["motivazione intrinseca","autonomia","autoefficacia","appartenenza","partecipazione"],"contesto":["scuola","lavoro"],"creata":"2026-11-04","doi":"10.1037/0003-066x.55.1.68","etichetta":"Deci e Ryan","evidenza":"","fonte":"«Self-determination theory and the facilitation of intrinsic motivation», American Psychologist, 55, 2000","inAzienda":"Le persone si impegnano di più quando hanno margine di scelta su come lavorare, si sentono capaci e hanno buone relazioni con i colleghi. Premi e controlli troppo stretti possono invece ridurre l'interesse per il lavoro, perché spostano l'attenzione dal lavoro alla ricompensa.","leve":["gui","rel"],"macro":"ind","microtemi":["motivazione intrinseca","autonomia","competenza","relazione","partecipazione"],"motivi":{"autonomia":"L'autonomia, cioè sentire di scegliere ciò che si fa, è il primo dei tre bisogni psicologici di base indicati dalla teoria.","competenza":"La competenza, cioè sentirsi capaci di affrontare il proprio lavoro, è il secondo bisogno di base.","motivazione intrinseca":"La teoria descrive le condizioni in cui una persona lavora per interesse verso il lavoro stesso, e quelle che riducono questo interesse.","partecipazione":"Partecipare alle decisioni sostiene l'autonomia e aiuta le persone a fare propri obiettivi che all'inizio venivano dall'esterno.","relazione":"Il bisogno di relazione, cioè di sentirsi legati agli altri, è il terzo bisogno di base."},"organizzazioni":[],"prova":"teoria","sinossi":"L'articolo riassume per un pubblico ampio la teoria dell'autodeterminazione, costruita dagli autori in trent'anni di esperimenti. La motivazione non è una quantità unica: va da quella imposta da premi e minacce a quella che una persona sente propria, fino all'interesse per il compito in sé. A sostenerla sono tre bisogni psicologici di base, autonomia, competenza e relazione, e gli ambienti che li soddisfano favoriscono impegno, apprendimento e benessere. Esperimenti precedenti avevano mostrato che premi materiali attesi e legati al compito possono ridurre la motivazione per l'interesse. La teoria è stata confermata in molti campi, dalla scuola al lavoro allo sport, anche se l'effetto dei premi sulla motivazione resta discusso.","tipo":"articolo","titolo":"Self-determination theory and the facilitation of intrinsic motivation","url":"https://doi.org/10.1037/0003-066x.55.1.68","id":"deci-ryan"},{"anno":2026,"area":"evo","autori":"Fabrizio Dell'Acqua, Edward McFowland III, Ethan R. Mollick, Hila Lifshitz-Assaf, Katherine C. Kellogg e colleghi","autoriIds":["fabrizio-dell-acqua","edward-mcfowland-iii","ethan-r-mollick","hila-lifshitz-assaf","katherine-c-kellogg"],"collegamenti":["simon","janis"],"concetti":["intelligenza artificiale","trasformazione digitale","carico di lavoro","decisione collettiva","guida distribuita"],"contesto":["consulenza","tecnologia"],"creata":"2026-11-05","doi":"10.1287/orsc.2025.21838","etichetta":"Dell'Acqua et al.","evidenza":"","fonte":"Organization Science, 37(2), 403-423, 2026 (versione precedente come Harvard Business School Working Paper, 2023)","inAzienda":"Prima di diffondere l'intelligenza artificiale generativa conviene classificare i compiti uno per uno e prevedere un controllo umano proprio dove lo strumento sembra convincente ma sbaglia.","leve":["gui","car"],"macro":"tra","microtemi":["intelligenza artificiale","trasformazione digitale","produttività","decisioni sbagliate","responsabilità finale"],"motivi":{"decisioni sbagliate":"Fuori dalla frontiera lo strumento porta le persone a soluzioni sbagliate.","intelligenza artificiale":"È un esperimento sull'uso di un modello linguistico avanzato nel lavoro di consulenza.","produttività":"Misura quanti compiti si completano, in quanto tempo e con quale qualità.","responsabilità finale":"Mette in evidenza chi deve controllare il risultato quando lo strumento sbaglia.","trasformazione digitale":"Mostra come cambia la distribuzione dei compiti in un lavoro di conoscenza."},"organizzazioni":["Boston Consulting Group"],"prova":"esperimento di campo","sinossi":"Lo studio nasce da una collaborazione con una grande società di consulenza strategica e si chiede che cosa succede al lavoro di persone molto qualificate quando possono usare un modello linguistico avanzato. In un esperimento preregistrato 758 consulenti, dopo una misura di partenza, vengono assegnati a caso a tre condizioni: senza intelligenza artificiale, con GPT-4, oppure con GPT-4 e una breve introduzione al suo uso. Nei diciotto compiti che lo strumento sa svolgere bene chi lo usa completa in media il 12,2 per cento di compiti in più, il 25,1 per cento più in fretta e con una qualità migliore. In un compito manageriale scelto apposta fuori dalla portata dello strumento, chi lo usa ha invece il 19 per cento di probabilità in meno di arrivare alla soluzione corretta. Gli autori parlano di una frontiera frastagliata: compiti in apparenza simili cadono da parti diverse del confine, e non è facile capire in anticipo da quale. Lo studio ha dato un linguaggio comune a chi deve decidere come distribuire il lavoro fra persone e strumenti. I compiti sono realistici ma costruiti per l'esperimento, i partecipanti appartengono a una sola azienda e la tecnologia cambia più in fretta dei risultati.","tipo":"articolo","titolo":"Navigating the Jagged Technological Frontier: Field Experimental Evidence of the Effects of Artificial Intelligence on Knowledge Worker Productivity and Quality","url":"https://doi.org/10.1287/orsc.2025.21838","id":"dellacqua-2026-jagged"},{"anno":2007,"area":"lea","autori":"James R. Detert e Ethan R. Burris","autoriIds":["james-r-detert","ethan-r-burris"],"collegamenti":["morrison-milliken","edmondson"],"concetti":["voce","stile di guida","sicurezza psicologica"],"contesto":["ristorazione"],"creata":"2026-11-04","doi":"10.5465/amj.2007.26279183","etichetta":"Detert e Burris","evidenza":"","fonte":"«Leadership behavior and employee voice: is the door really open?», Academy of Management Journal, 50(4), 2007","inAzienda":"Una politica della porta aperta funziona solo se il responsabile è davvero raggiungibile e se chi segnala un problema vede che la segnalazione produce qualcosa. Altrimenti le persone smettono di parlare, anche se la porta resta formalmente aperta.","leve":["gui","rel"],"macro":"com","microtemi":["voce","porta aperta","comportamento del capo","sicurezza psicologica","proposte di miglioramento"],"motivi":{"comportamento del capo":"Lo studio confronta l'effetto dello stile trasformazionale del capo con quello della sua disponibilità ad ascoltare.","porta aperta":"Mostra che la disponibilità ad ascoltare conta più di altri tratti del capo nel far parlare i collaboratori.","proposte di miglioramento":"Il comportamento misurato è la voce costruttiva, cioè le proposte dei collaboratori per migliorare il lavoro.","sicurezza psicologica":"L'effetto della disponibilità del capo passa attraverso la sicurezza psicologica: i collaboratori parlano quando non temono conseguenze.","voce":"La domanda di partenza è che cosa spinge i dipendenti a proporre miglioramenti invece di tacere."},"organizzazioni":[],"prova":"studio osservazionale","sinossi":"Detert e Burris si chiedono quali comportamenti del capo portano i dipendenti a proporre miglioramenti, cioè a usare la voce in modo costruttivo. Confrontano due tipi di guida orientata al cambiamento: la leadership trasformazionale, che ispira e stimola, e l'apertura del manager, cioè la disponibilità ad ascoltare, considerare le proposte e dare seguito. Lo studio è in due fasi e coinvolge 3.149 dipendenti e 223 manager di una catena di ristoranti. L'apertura risulta legata alla voce in modo più costante della leadership trasformazionale, anche tenendo conto della personalità, della soddisfazione e delle caratteristiche dei dipendenti. Il legame passa dalla sicurezza psicologica percepita, cioè dalla valutazione dei rischi che si corrono parlando. L'effetto dei comportamenti del capo è più forte proprio sui dipendenti migliori, che hanno più da perdere se parlano e vengono puniti. La porta aperta dichiarata conta meno della porta aperta vissuta ogni giorno. I dati vengono da un solo settore e da una sola azienda, e le misure di voce sono in parte valutazioni dei manager.","tipo":"articolo","titolo":"Leadership behavior and employee voice: is the door really open?","url":"https://doi.org/10.5465/amj.2007.26279183","id":"detert-burris"},{"anno":2001,"area":"lav","autori":"Amy C. Edmondson, Richard M. Bohmer, Gary P. Pisano","autoriIds":["amy-c-edmondson","richard-m-bohmer","gary-p-pisano"],"collegamenti":["edmondson","argyris-schon","senge"],"concetti":["lavoro di squadra","sicurezza psicologica","apprendimento organizzativo","trasformazione digitale"],"contesto":["sanità"],"creata":"2026-11-05","doi":"10.2307/3094828","etichetta":"Edmondson et al.","evidenza":"","fonte":"Administrative Science Quarterly, 46(4), 685-716, 2001","inAzienda":"Una tecnologia nuova viene adottata davvero quando il gruppo che la usa è scelto con cura, si prepara con prove in condizioni protette e riflette insieme su come sta andando. Installarla e formare le persone singolarmente non basta.","leve":["app"],"macro":"app","microtemi":["apprendimento di team","sicurezza psicologica","routine","trasformazione digitale","riflessività"],"motivi":{"apprendimento di team":"Il risultato centrale è un processo di apprendimento di team in quattro passi.","riflessività":"I momenti di riflessione dopo le prove distinguono i reparti riusciti.","routine":"La tecnologia richiede di cambiare una routine radicata della sala operatoria.","sicurezza psicologica":"Le prime prove sono progettate per creare sicurezza psicologica.","trasformazione digitale":"Riguarda l'adozione di una tecnologia nuova in un'organizzazione complessa."},"organizzazioni":[],"prova":"studio osservazionale","sinossi":"Amy Edmondson, Richard Bohmer e Gary Pisano, dell'Università di Harvard, hanno seguito sedici ospedali statunitensi mentre introducevano una tecnologia nuova per la chirurgia cardiaca mininvasiva, che chiedeva di cambiare in profondità la routine del team in sala operatoria. Tutti i reparti erano di alto livello, con ottima reputazione e buoni risultati sui pazienti, eppure hanno avuto esiti molto diversi nell'adottare la tecnologia. Con uno studio qualitativo sul campo, fatto di interviste e osservazioni, gli autori mostrano che chi ci è riuscito ha seguito un processo di apprendimento di team diverso. Il processo ha quattro passi: il coinvolgimento del team, la preparazione, le prime prove e la riflessione. I reparti riusciti hanno scelto e motivato il team, hanno progettato esercitazioni e prime prove in modo da creare sicurezza psicologica e incoraggiare comportamenti nuovi, e hanno usato momenti di riflessione per costruire un significato comune e migliorare il processo. Lo studio ha mostrato che l'adozione di una tecnologia è prima di tutto un apprendimento collettivo. I casi sono pochi e di un solo settore, e il disegno qualitativo non permette di stimare il peso dei singoli fattori.","tipo":"articolo","titolo":"Disrupted Routines: Team Learning and New Technology Implementation in Hospitals","url":"https://doi.org/10.2307/3094828","id":"edmondson-2001-disrupted"},{"anno":1999,"area":"lav","autori":"Amy C. Edmondson","autoriIds":["amy-c-edmondson"],"collegamenti":["morrison-milliken","janis","lewin","detert-burris"],"concetti":["sicurezza psicologica","lavoro di squadra","voce"],"contesto":["manifattura"],"creata":"2026-11-04","doi":"10.2307/2666999","etichetta":"Edmondson","evidenza":"","fonte":"«Psychological safety and learning behavior in work teams», Administrative Science Quarterly, 44, 1999; The Fearless Organization, Wiley, 2018","inAzienda":"In un gruppo le persone segnalano errori e chiedono aiuto solo se sono convinte che non verranno umiliate o punite. Questa convinzione si può misurare con un questionario breve e validato, e misurarla prima e dopo un intervento permette di capire se il clima è cambiato.","leve":["rel","app"],"macro":"com","microtemi":["sicurezza psicologica","errori","apprendimento di team","voce","fiducia"],"motivi":{"apprendimento di team":"Edmondson mostra che la sicurezza psicologica favorisce i comportamenti con cui un gruppo impara: chiedere aiuto, discutere gli errori, sperimentare.","errori":"La ricerca nasce da un risultato inatteso: i reparti ospedalieri migliori dichiaravano più errori, perché li segnalavano invece di nasconderli.","fiducia":"La sicurezza psicologica è una forma di fiducia condivisa da tutto il gruppo, non solo fra due persone.","sicurezza psicologica":"Lo studio definisce la sicurezza psicologica e propone la scala con cui misurarla nei gruppi di lavoro.","voce":"Chiedere aiuto e segnalare un problema sono forme di voce, e la sicurezza psicologica le rende possibili."},"organizzazioni":[],"prova":"studio osservazionale","sinossi":"Edmondson parte da un risultato inatteso raccolto in precedenza in reparti ospedalieri: i team con il clima migliore dichiaravano più errori, non perché ne commettessero di più ma perché li segnalavano. In questo studio su 51 team di un'azienda manifatturiera definisce la sicurezza psicologica come la convinzione condivisa che nel gruppo si possano correre rischi interpersonali, come ammettere un errore o fare una domanda. Con questionari, interviste e osservazioni mostra che la sicurezza psicologica favorisce i comportamenti di apprendimento (chiedere aiuto, discutere gli errori, cercare riscontri), e che questi a loro volta sono legati alle prestazioni del team. L'articolo ha aperto un filone di ricerca enorme, ripreso anche dagli studi interni di grandi aziende sui team efficaci. I dati sono di una sola azienda e in gran parte correlazionali.","tipo":"articolo","titolo":"Psychological safety and learning behavior in work teams","url":"https://doi.org/10.2307/2666999","id":"edmondson"},{"anno":1965,"area":"sis","autori":"Fred E. Emery e Eric L. Trist","autoriIds":["fred-e-emery","eric-l-trist"],"collegamenti":["lawrence-lorsch","katz-kahn","lewin"],"concetti":["turbolenza ambientale","contingenza","sistemi sociotecnici"],"contesto":["imprese"],"creata":"2026-11-04","doi":"10.1177/001872676501800103","etichetta":"Emery e Trist","evidenza":"","fonte":"«The causal texture of organizational environments», Human Relations, 18, 1965","inAzienda":"Prima di decidere come organizzarsi, un'azienda deve capire quanto è instabile e intrecciato l'ambiente in cui opera. In un ambiente turbolento i piani a lungo termine perdono valore, e diventano più importanti i valori condivisi e le alleanze con altre organizzazioni.","leve":["app"],"macro":"tra","microtemi":["turbolenza ambientale","incertezza","ambiente esterno","pianificazione","sociotecnico"],"motivi":{"ambiente esterno":"Gli autori propongono una classificazione dei tipi di ambiente in cui operano le organizzazioni.","incertezza":"Negli ambienti turbolenti i cambiamenti nascono dall'intreccio di molti attori, e per questo sono difficili da prevedere.","pianificazione":"Mostrano che il modo di pianificare deve cambiare a seconda del tipo di ambiente.","sociotecnico":"Emery e Trist appartengono alla scuola sociotecnica del Tavistock Institute, che studia insieme tecnologia e organizzazione del lavoro.","turbolenza ambientale":"L'articolo introduce il concetto di campo turbolento, l'ambiente più instabile della loro classificazione."},"organizzazioni":["Tavistock Institute"],"prova":"teoria","sinossi":"Fred Emery ed Eric Trist, ricercatori del Tavistock Institute di Londra, propongono di guardare l'ambiente di un'organizzazione come qualcosa che ha una propria struttura, una tessitura causale. Ne distinguono quattro tipi, dal più quieto e prevedibile al campo turbolento, in cui i cambiamenti non vengono più dalle singole organizzazioni ma dall'ambiente stesso, per l'intreccio di molti attori che si influenzano. In un ambiente turbolento nessuna organizzazione può adattarsi da sola: servono valori condivisi e collaborazioni fra organizzazioni. L'articolo parte da casi reali, fra cui un'azienda britannica di conserve che perse il proprio mercato senza accorgersi in tempo dei cambiamenti intorno a lei. È un testo fondativo degli studi sull'ambiente delle organizzazioni, scritto prima dell'era digitale ma ancora attuale.","tipo":"articolo","titolo":"The causal texture of organizational environments","url":"https://doi.org/10.1177/001872676501800103","id":"emery-trist"},{"anno":2002,"area":"soc","autori":"Donata Francescato, Manuela Tomai, Grazia Ghirelli","autoriIds":["donata-francescato","manuela-tomai","grazia-ghirelli"],"collegamenti":["kelly","lewin"],"concetti":["sistemi sociotecnici","autonomia","sistemi aperti"],"contesto":["comunità","pubblica amministrazione"],"creata":"2026-11-04","etichetta":"Francescato","evidenza":"","fonte":"Fondamenti di psicologia di comunità, Carocci, 2002","inAzienda":"Un problema organizzativo va letto su più piani: la strategia e la struttura, il funzionamento quotidiano, le dinamiche emotive e l'ambiente fisico. Lo schema dell'analisi multidimensionale evita di ridurlo a una sola causa, come il carattere di una persona.","leve":["rel","car","gui","rig","cul"],"macro":"cul","microtemi":["analisi organizzativa multidimensionale","empowerment","diagnosi","psicologia di comunità","profili di comunità"],"organizzazioni":[],"prova":"manuale","sinossi":"Il manuale di Donata Francescato, Manuela Tomai e Grazia Ghirelli è il riferimento della psicologia di comunità italiana. Presenta la storia, i concetti e gli strumenti della disciplina, adattando al contesto italiano un modello nato negli Stati Uniti. Fra gli strumenti più utili per le organizzazioni c'è l'analisi organizzativa multidimensionale, che legge un'organizzazione su quattro piani: strategico-strutturale, funzionale, psicodinamico e psicoambientale. Ogni piano chiede domande e metodi diversi, e insieme impediscono di ridurre un problema a una sola causa. Il libro tratta anche l'empowerment, il lavoro di rete e i profili di comunità.","tipo":"libro","titolo":"Fondamenti di psicologia di comunità","id":"francescato"},{"anno":2017,"area":"lav","autori":"M. Lance Frazier, Stav Fainshmidt, Ryan L. Klinger, Amir Pezeshkan, Veselina Vracheva","autoriIds":["m-lance-frazier","stav-fainshmidt","ryan-l-klinger","amir-pezeshkan","veselina-vracheva"],"collegamenti":["edmondson","detert-burris"],"concetti":["sicurezza psicologica","voce","lavoro di squadra"],"contesto":["imprese"],"creata":"2026-11-05","doi":"10.1111/peps.12183","etichetta":"Frazier et al.","evidenza":"","fonte":"Personnel Psychology, 70(1), 113-165, 2017","inAzienda":"La sicurezza psicologica conta per la prestazione anche al netto del buon rapporto con il capo, e dipende in buona parte da come il lavoro e la guida sono progettati.","leve":["rel","app"],"macro":"com","microtemi":["sicurezza psicologica","fiducia","voce","apprendimento di team","meta-analisi"],"motivi":{"apprendimento di team":"Fra gli esiti ci sono comportamenti che sostengono l'apprendimento dei gruppi.","fiducia":"La sicurezza psicologica è una forma di fiducia interpersonale nel gruppo.","meta-analisi":"Riassume 136 campioni indipendenti.","sicurezza psicologica":"È la meta-analisi di riferimento sulla sicurezza psicologica.","voce":"La sicurezza psicologica è la condizione per parlare e segnalare."},"organizzazioni":[],"prova":"meta-analisi","sinossi":"La ricerca sulla sicurezza psicologica è cresciuta molto dopo i lavori di Edmondson, ma restavano aperte domande su quali ne siano le cause più forti e quanto pesi davvero sui risultati. Gli autori raccolgono la letteratura in una meta-analisi di 136 campioni indipendenti, con oltre 22.000 persone e quasi 5.000 gruppi. Descrivono la rete di antecedenti ed esiti della sicurezza psicologica e confrontano la forza dei diversi antecedenti, come le caratteristiche delle persone, del lavoro, delle relazioni e della guida. Verificano se la sicurezza psicologica spieghi la prestazione nei compiti e i comportamenti di cittadinanza organizzativa anche al netto di concetti vicini, come un buon rapporto con il capo e il coinvolgimento nel lavoro. Esaminano anche se il disegno degli studi e la cultura nazionale cambino le relazioni, e se queste siano simili a livello individuale e di gruppo. La meta-analisi conferma il ruolo della sicurezza psicologica e ne precisa i confini rispetto a concetti affini. Gli studi inclusi sono in gran parte correlazionali, per cui le relazioni non dimostrano da sole un rapporto di causa.","tipo":"articolo","titolo":"Psychological Safety: A Meta-Analytic Review and Extension","url":"https://doi.org/10.1111/peps.12183","id":"frazier-2017-safety"},{"anno":2007,"area":"lav","autori":"Ravi S. Gajendran, David A. Harrison","autoriIds":["ravi-s-gajendran","david-a-harrison"],"collegamenti":["deci-ryan","karasek"],"concetti":["lavoro a distanza e ibrido","autonomia","appartenenza"],"contesto":["imprese"],"creata":"2026-11-05","doi":"10.1037/0021-9010.92.6.1524","etichetta":"Gajendran","evidenza":"","fonte":"Journal of Applied Psychology, 92(6), 1524-1541, 2007","inAzienda":"Le politiche di lavoro a distanza funzionano quando aumentano davvero l'autonomia e prevedono tempi in presenza per mantenere i rapporti con i colleghi.","leve":["rel","rig"],"macro":"cam","microtemi":["lavoro a distanza","lavoro ibrido","autonomia","relazione","meta-analisi"],"motivi":{"autonomia":"L'autonomia percepita spiega una parte dei benefici.","lavoro a distanza":"È la meta-analisi di riferimento sugli effetti del telelavoro.","lavoro ibrido":"Mostra che l'intensità, cioè quanti giorni a distanza, cambia gli effetti.","meta-analisi":"Riassume 46 studi su oltre dodicimila dipendenti.","relazione":"Oltre una certa intensità peggiorano i rapporti con i colleghi."},"organizzazioni":[],"prova":"meta-analisi","sinossi":"Gajendran e Harrison si chiedono quali siano gli effetti positivi e negativi del telelavoro e attraverso quali meccanismi si producano. Costruiscono un modello teorico e lo mettono alla prova con una meta-analisi di 46 studi condotti in contesti reali, per un totale di 12.883 dipendenti. Il telelavoro ha effetti piccoli ma in prevalenza favorevoli su autonomia percepita e conflitto fra lavoro e famiglia, e non peggiora in generale le relazioni sul lavoro. Ha effetti favorevoli anche su soddisfazione, prestazione, intenzione di lasciare l'azienda e stress di ruolo, in parte mediati dall'autonomia percepita. Quando supera i due giorni e mezzo alla settimana riduce di più il conflitto con la famiglia ma danneggia i rapporti con i colleghi. La meta-analisi è rimasta il punto di partenza degli studi sul lavoro a distanza, anche dopo la pandemia. Gli studi inclusi sono soprattutto correlazionali e precedenti alle tecnologie di collaborazione di oggi.","tipo":"articolo","titolo":"The good, the bad, and the unknown about telecommuting: Meta-analysis of psychological mediators and individual consequences","url":"https://doi.org/10.1037/0021-9010.92.6.1524","id":"gajendran-2007-telecommuting"},{"anno":2010,"area":"nat","autori":"Deborah M. Gordon","autoriIds":["deborah-m-gordon"],"collegamenti":["seeley","ostrom","ashby","seeley-nido"],"concetti":["coordinamento senza centro","regolazione distribuita","carico di lavoro"],"contesto":["formiche"],"creata":"2026-11-04","etichetta":"Gordon","evidenza":"funzionale","fonte":"Ant Encounters, Princeton University Press, 2010","inAzienda":"Nei lavori ripetitivi e a basso rischio, come la gestione delle richieste interne, le persone possono regolare da sole la distribuzione del carico se vedono in tempo reale quanto lavoro è in attesa. Il coordinamento centrale serve allora solo per le eccezioni.","leve":["gui","car"],"macro":"lea","microtemi":["coordinamento senza capo","interazioni locali","foraggiamento","regolazione distribuita","compiti ripetuti"],"organizzazioni":[],"prova":"osservazione sul campo","sinossi":"Deborah Gordon, biologa all'Università di Stanford, ha studiato per decenni le colonie di formiche raccoglitrici nel deserto dell'Arizona. In questo libro mostra che nessuna formica dà ordini: il lavoro della colonia nasce dagli incontri fra individui. Ogni formica decide se uscire a cercare cibo in base al ritmo con cui incontra, all'ingresso del nido, le compagne che rientrano cariche: se rientrano spesso, il cibo c'è e conviene uscire; se rientrano di rado, conviene restare. Così la colonia adegua lo sforzo alla disponibilità di cibo senza che nessuno abbia un quadro d'insieme. Gordon propone di leggere allo stesso modo altri sistemi senza centro.","tipo":"libro","titolo":"Ant Encounters","url":"https://press.princeton.edu/books/paperback/9780691138794/ant-encounters","id":"gordon"},{"anno":2000,"area":"lav","autori":"Rodger W. Griffeth, Peter W. Hom, Stefan Gaertner","autoriIds":["rodger-w-griffeth","peter-w-hom","stefan-gaertner"],"collegamenti":["hirschman","rousseau"],"concetti":["appartenenza","resilienza"],"contesto":["imprese"],"creata":"2026-11-05","doi":"10.1177/014920630002600305","etichetta":"Griffeth et al.","evidenza":"","fonte":"Journal of Management, 26(3), 463-488, 2000","inAzienda":"I segnali di uscita si vedono prima delle dimissioni, e riconoscerli permette di intervenire sul rapporto con il lavoro e con il capo invece che sulla sola retribuzione.","leve":["rel","rig"],"macro":"ind","microtemi":["turnover","uscita","appartenenza","segnali di declino","meta-analisi"],"motivi":{"appartenenza":"L'impegno verso l'organizzazione è uno degli antecedenti esaminati.","meta-analisi":"Riassume quantitativamente un'ampia letteratura.","segnali di declino":"Intenzioni di uscita e comportamenti di ritiro anticipano le dimissioni.","turnover":"È una meta-analisi sulle cause delle dimissioni volontarie.","uscita":"Studia i fattori che portano le persone a lasciare l'organizzazione."},"organizzazioni":[],"prova":"meta-analisi","sinossi":"Rodger Griffeth e Stefan Gaertner, della Georgia State University, e Peter Hom, dell'Arizona State University, aggiornano una meta-analisi precedente degli stessi Hom e Griffeth sulle cause delle dimissioni volontarie, con l'obiettivo di stimare quanto ciascun fattore preveda davvero l'uscita delle persone. Raccolgono un'ampia serie di studi e confrontano la forza predittiva di molti antecedenti, dalla soddisfazione all'impegno verso l'organizzazione, dalle intenzioni di uscita alla ricerca di alternative, dal rapporto con il capo alle caratteristiche del lavoro. È a lungo rimasta la rassegna quantitativa più completa sul tema. Un contributo importante è l'individuazione di fattori che rendono più o meno forte la relazione fra un antecedente e l'uscita, come le caratteristiche dei campioni e dei disegni di ricerca. Fra i risultati più ripresi c'è il ruolo delle intenzioni di uscita e dei comportamenti di ritiro come segnali che precedono le dimissioni. Gli autori discutono le implicazioni per la teoria e per le politiche di ritenzione. La meta-analisi è precedente alle forme di lavoro ibrido e di piattaforma, e riassume relazioni in gran parte correlazionali.","tipo":"articolo","titolo":"A Meta-Analysis of Antecedents and Correlates of Employee Turnover: Update, Moderator Tests, and Research Implications for the Next Millennium","url":"https://doi.org/10.1177/014920630002600305","id":"griffeth-2000-turnover"},{"anno":2012,"area":"lav","autori":"Mario Gualandri, Roberta Fida, Francesco Avallone","autoriIds":["mario-gualandri","roberta-fida","francesco-avallone"],"collegamenti":["avallone-2003-benessere","karasek","bakker-demerouti"],"concetti":["benessere organizzativo","carico di lavoro","stress lavorativo","diversità"],"contesto":["sanità"],"creata":"2026-11-05","doi":"10.3280/pds2012-001005","etichetta":"Gualandri et al.","evidenza":"","fonte":"Psicologia della Salute, 1, 61-85, 2012","inAzienda":"Nelle organizzazioni sanitarie il benessere passa prima di tutto da carichi, sicurezza ed equità, e da un ambiente fisico che non aggiunga fatica.","leve":["car","rig"],"macro":"ben","microtemi":["benessere organizzativo","carico di lavoro","stress lavorativo","equità","sanità"],"motivi":{"benessere organizzativo":"Misura il benessere organizzativo in un grande campione di aziende sanitarie.","carico di lavoro":"Il carico è uno dei fattori più legati a stress e disturbi.","equità":"L'equità percepita risulta critica, soprattutto per le donne.","sanità":"Il campione è composto da dipendenti delle aziende sanitarie locali.","stress lavorativo":"Lo stress è uno degli esiti principali misurati."},"organizzazioni":[],"prova":"indagine con questionario","sinossi":"Mario Gualandri, Roberta Fida e Francesco Avallone, della Sapienza Università di Roma, partono dall'osservazione che i contesti sanitari, per la complessità delle loro dinamiche organizzative, sono particolarmente esposti al rischio di malessere, con effetti sullo stress e sulla salute dei lavoratori. Usano i dati di una ricerca nazionale su circa 8.000 dipendenti di Aziende Sanitarie Locali italiane, raccolti con il Multidimensional Organizational Health Questionnaire e distinti per area geografica e per genere. I fattori con il maggiore effetto su disturbi psicosomatici, stress e soddisfazione risultano il carico di lavoro, la sicurezza, il conflitto e l'apertura all'innovazione. In tutte le aree, e soprattutto per le donne, l'equità percepita e il carico di lavoro sono gli aspetti più critici. Nel Sud e nelle Isole pesano in più la percezione della sicurezza e del comfort dell'ambiente di lavoro. Complessivamente i lavoratori riportano bassa soddisfazione e stress alto. Lo studio è trasversale e basato su misure autodichiarate, per cui mostra associazioni e non cause.","tipo":"articolo","titolo":"Benessere Organizzativo in un campione di Aziende Sanitarie italiane","url":"https://doi.org/10.3280/pds2012-001005","id":"gualandri-2012-benessere"},{"anno":2020,"area":"nat","autori":"Nalise Hähn, Emmanuel Essah, Tijana Blanusa","autoriIds":["nalise-hahn","emmanuel-essah","tijana-blanusa"],"collegamenti":["nieuwenhuis-2014-green","bringslimark-2009-plants","wilson-1984-biophilia"],"composto":false,"concetti":["piante negli uffici","design biofilico","carico di lavoro","biofilia"],"contesto":["uffici"],"creata":"2026-11-05","doi":"10.1080/17508975.2020.1732859","esito":"Miglioramento di attenzione, creatività e produttività percepite con le piante e peggioramento alla rimozione; nessun effetto su salute, stanchezza, motivazione e benessere generale.","etichetta":"Hähn et al.","evidenza":"diretta","fonte":"Intelligent Buildings International, 13(4), 241-260 (pubblicato online nel 2020)","inAzienda":"Le piante negli uffici migliorano soprattutto l'attenzione e la soddisfazione percepite, e toglierle produce un peggioramento che le persone notano.","intervento":"Introduzione di due piante in vaso per persona negli uffici individuali e otto negli spazi di pausa, poi rimozione, con questionari prima, durante e dopo.","leve":["rig"],"macro":"ben","microtemi":["piante indoor","design biofilico","spazi di lavoro","produttività","biofilia"],"motivi":{"biofilia":"Parte dall'ipotesi della biofilia per formulare la domanda.","design biofilico":"Il caso applica un principio del design biofilico a un ufficio reale.","piante indoor":"L'intervento consiste nell'introdurre e togliere piante vere.","produttività":"Rileva la produttività percepita prima e dopo.","spazi di lavoro":"Lo studio si svolge in uffici e spazi di pausa."},"organizzazioni":[],"problema":"Gli uffici progettati in modo snello erano privi di elementi naturali e si voleva capire se le piante cambiassero salute, benessere e prestazione percepiti.","prova":"caso studio","settore":"Uffici di un edificio moderno","sinossi":"Lo studio parte dal contrasto fra gli uffici snelli, spogliati della natura per massimizzare la prestazione, e l'ipotesi della biofilia, secondo cui la separazione dalla natura riduce salute e benessere. In un edificio per uffici moderno gli autori introducono e poi rimuovono piante vere: due vasi per persona negli uffici individuali e otto negli spazi di pausa. Partecipano 40 occupanti, e i cambiamenti sono rilevati con questionari ripetuti. L'introduzione delle piante migliora in modo significativo l'attenzione, la creatività e la produttività percepite, e la loro rimozione peggiora attenzione, produttività, stress ed efficienza percepiti. Le piante non hanno effetti significativi su salute percepita, stanchezza, motivazione o benessere generale, né contano le interazioni con le piante durante le pause. Gli occupanti risultano più soddisfatti dell'ambiente di lavoro quando hanno accesso fisico e visivo alle piante. Il campione è piccolo, le misure sono solo percepite e manca un gruppo di controllo separato.","tipo":"caso","titolo":"Biophilic design and office planting: a case study of effects on perceived health, well-being and performance metrics in the workplace","url":"https://doi.org/10.1080/17508975.2020.1732859","id":"hahn-2020-biophilic"},{"anno":1994,"area":"lea","autori":"Ronald A. Heifetz","autoriIds":["ronald-a-heifetz"],"collegamenti":["bass","kegan-lahey","lewin"],"concetti":["leadership adattiva","cultura organizzativa","cambiamento organizzativo"],"contesto":["politica","imprese"],"creata":"2026-11-04","etichetta":"Heifetz","evidenza":"","fonte":"Leadership Without Easy Answers, Harvard University Press, 1994","inAzienda":"Molti interventi falliscono perché trattano come tecnico un problema che richiede alle persone di cambiare abitudini e priorità. In questi casi un esperto o un nuovo regolamento non bastano: serve un lavoro con le persone coinvolte, che sono le uniche a poter cambiare.","leve":["gui","app"],"macro":"lea","microtemi":["sfide adattive","problemi tecnici","leadership adattiva","valori","cambiamento"],"organizzazioni":[],"prova":"saggio","sinossi":"Ronald Heifetz, psichiatra e docente alla Harvard Kennedy School, distingue due tipi di problemi. I problemi tecnici hanno una soluzione nota, e un esperto o un capo può risolverli. I problemi adattivi chiedono invece alle persone coinvolte di cambiare valori, abitudini e priorità, e nessuno può risolverli al posto loro. L'errore più comune dei leader è trattare un problema adattivo come se fosse tecnico, dando risposte quando servirebbe aiutare il gruppo a lavorare sulla questione. Per Heifetz guidare significa mobilitare le persone ad affrontare problemi difficili, regolando la tensione perché sia abbastanza alta da spingere al cambiamento ma non tanto da paralizzare. Il libro si basa su casi politici e organizzativi più che su ricerche quantitative.","tipo":"libro","titolo":"Leadership Without Easy Answers","url":"https://www.hup.harvard.edu/books/9780674518582","id":"heifetz"},{"anno":1970,"area":"cam","autori":"Albert O. Hirschman","autoriIds":["albert-o-hirschman"],"collegamenti":["morrison-milliken","rousseau"],"concetti":["appartenenza","voce","resilienza"],"contesto":["imprese","politica"],"creata":"2026-11-04","etichetta":"Hirschman","evidenza":"","fonte":"Exit, Voice, and Loyalty, Harvard University Press, 1970","inAzienda":"Quando le persone insoddisfatte non hanno un canale efficace per farsi ascoltare, l'unica scelta che resta loro è andarsene. Un turnover alto può quindi indicare che il disagio non ha trovato ascolto, e non solo che le persone hanno trovato condizioni migliori altrove.","leve":["rel"],"macro":"com","microtemi":["uscita","voce","lealtà","turnover","segnali di declino"],"organizzazioni":[],"prova":"teoria","sinossi":"Albert Hirschman, economista, si chiede che cosa succede quando un'impresa, un'associazione o uno Stato peggiorano. Chi ne fa parte, o ne compra i prodotti, ha due reazioni possibili: l'uscita, cioè andarsene, e la voce, cioè protestare e chiedere cambiamenti. Entrambe sono segnali che possono aiutare l'organizzazione a correggersi, ma funzionano in modo diverso: l'uscita è silenziosa e arriva tardi, la voce informa ma costa fatica a chi la esercita. La lealtà trattiene le persone e dà tempo alla voce di agire; dove la voce non ha canali, resta solo l'uscita. Il libro è breve e ha influenzato l'economia, la scienza politica e gli studi sul lavoro.","tipo":"libro","titolo":"Exit","url":"https://www.hup.harvard.edu/books/9780674276604","id":"hirschman"},{"anno":1973,"area":"nat","autori":"C.S. Holling","autoriIds":["c-s-holling"],"collegamenti":["ashby","march"],"concetti":["resilienza","varietà necessaria"],"contesto":["ecosistemi"],"creata":"2026-11-04","doi":"10.1146/annurev.es.04.110173.000245","etichetta":"Holling","evidenza":"formale","fonte":"«Resilience and stability of ecological systems», Annual Review of Ecology and Systematics, 4, 1973","inAzienda":"Un'azienda che elimina ogni riserva per essere più efficiente, come scorte, persone in grado di sostituirsi e fornitori alternativi, funziona bene finché tutto va come previsto e si blocca al primo imprevisto serio. Mantenere una certa varietà di persone, competenze e soluzioni ha un costo, ma è ciò che le permette di continuare a lavorare quando qualcosa va storto.","leve":["app","rig"],"macro":"tra","microtemi":["resilienza","stabilità","disturbo","varietà","efficienza e fragilità"],"motivi":{"disturbo":"Holling studia come gli ecosistemi rispondono a eventi che li alterano, come incendi, parassiti o cambiamenti del clima.","efficienza e fragilità":"Mostra che un ecosistema gestito solo per la resa massima diventa stabile in condizioni normali ma vulnerabile ai disturbi.","resilienza":"È l'articolo che introduce in ecologia il concetto di resilienza, la capacità di assorbire un disturbo senza perdere le proprie funzioni.","stabilità":"Distingue la stabilità, cioè il ritorno rapido all'equilibrio, dalla resilienza, e mostra che non coincidono.","varietà":"La varietà di specie e di risposte è ciò che permette a un ecosistema di assorbire disturbi diversi."},"organizzazioni":[],"prova":"teoria","sinossi":"C.S. Holling, ecologo canadese, confronta due modi di intendere la tenuta di un sistema naturale. La stabilità è la capacità di tornare in fretta all'equilibrio dopo un disturbo. La resilienza è la capacità di assorbire disturbi e cambiamenti mantenendo le proprie funzioni e relazioni, anche passando per stati diversi. I due concetti possono andare in direzioni opposte: alcune popolazioni oscillano molto, e quindi sono poco stabili, ma resistono a lungo; altre sono molto stabili finché un disturbo non le fa crollare. Holling mostra che una gestione che punta solo alla stabilità e alla resa massima può rendere un sistema fragile. L'articolo ha introdotto la resilienza in ecologia, da cui il termine è poi passato agli studi sulle organizzazioni e sulle persone.","tipo":"articolo","titolo":"Resilience and stability of ecological systems","url":"https://doi.org/10.1146/annurev.es.04.110173.000245","id":"holling"},{"anno":1972,"area":"soc","autori":"Irving L. Janis","autoriIds":["irving-l-janis"],"collegamenti":["asch","moscovici","edmondson"],"concetti":["pensiero di gruppo","lavoro di squadra","conformità","decisione collettiva"],"contesto":["politica"],"creata":"2026-11-04","etichetta":"Janis","evidenza":"","fonte":"Victims of Groupthink, Houghton Mifflin, 1972","inAzienda":"Un gruppo molto unito tende a scoraggiare le critiche per non incrinare l'armonia, e così prende decisioni peggiori. Chi conduce una riunione deve quindi proteggere attivamente le opinioni contrarie, per esempio chiedendole esplicitamente prima di esprimere la propria.","leve":["gui","rel"],"macro":"lea","microtemi":["pensiero di gruppo","coesione","dissenso","decisioni sbagliate","avvocato del diavolo"],"organizzazioni":[],"prova":"caso studio","sinossi":"Janis rilegge decisioni politiche americane finite male, come lo sbarco alla Baia dei Porci e l'escalation in Vietnam, e le confronta con decisioni prese bene, come la gestione della crisi dei missili a Cuba. Chiama pensiero di gruppo la tendenza dei gruppi molto coesi e sotto pressione a cercare l'accordo più che la scelta migliore. Ne elenca i sintomi: illusione di invulnerabilità, autocensura, illusione di unanimità, persone che proteggono il capo dalle notizie scomode. Propone rimedi pratici: un capo che non si schiera subito, un avvocato del diavolo, sottogruppi indipendenti, esperti esterni. Il libro si basa su casi storici, e le verifiche sperimentali successive hanno confermato solo in parte il modello.","tipo":"libro","titolo":"Victims of Groupthink","url":"https://openlibrary.org/works/OL1282016W","id":"janis"},{"anno":1989,"area":"nat","autori":"Rachel Kaplan, Stephen Kaplan","autoriIds":["rachel-kaplan","stephen-kaplan"],"collegamenti":["kaplan"],"concetti":["recupero dell'attenzione","design biofilico"],"contesto":["natura"],"creata":"2026-11-04","doi":"","etichetta":"Kaplan e Kaplan","evidenza":"","fonte":"Cambridge University Press, Cambridge, 1989","inAzienda":"Il lavoro mentale prolungato consuma la capacità di concentrarsi, e gli ambienti naturali la lasciano riposare. Pause brevi in spazi verdi, o anche solo con vista sul verde, proteggono quindi la qualità dell'attenzione durante la giornata di lavoro.","leve":["rig"],"macro":"ben","microtemi":["recupero dell'attenzione","preferenze ambientali","psicologia ambientale","fatica mentale"],"motivi":{},"organizzazioni":[],"prova":"rassegna","sinossi":"Rachel e Stephen Kaplan, psicologi ambientali all'Università del Michigan, riassumono vent'anni di ricerche su come le persone percepiscono e vivono gli ambienti naturali, dal giardino sotto casa ai parchi fino alla natura selvaggia. Mostrano quali paesaggi le persone preferiscono e perché, e quanto contino anche le piccole dosi di natura, come una vista dalla finestra. Il libro pone le basi della teoria del recupero dell'attenzione: il lavoro mentale consuma la capacità di concentrarsi volontariamente, e gli ambienti naturali la lasciano riposare perché attirano l'attenzione senza sforzo. La teoria ha avuto molte conferme, ma anche critiche sulla definizione dei suoi concetti.","tipo":"libro","titolo":"The Experience of Nature: A Psychological Perspective","url":"https://openlibrary.org/works/OL1928754W","id":"kaplan-1989-experience"},{"anno":1995,"area":"nat","autori":"Stephen Kaplan","autoriIds":["stephen-kaplan"],"collegamenti":["sonnentag-fritz","ulrich"],"concetti":["recupero dell'attenzione","recupero","immersione nel bosco"],"contesto":["natura"],"creata":"2026-11-04","doi":"10.1016/0272-4944(95)90001-2","etichetta":"Kaplan","evidenza":"diretta","fonte":"«The restorative benefits of nature», Journal of Environmental Psychology, 15, 1995","inAzienda":"Non tutte le pause rigenerano allo stesso modo: una pausa davanti al telefono continua a impegnare l'attenzione, una pausa all'aperto la lascia riposare. Progettare i luoghi e i tempi delle pause è quindi un modo per proteggere la concentrazione delle persone.","leve":["rig"],"macro":"ben","microtemi":["recupero dell'attenzione","fatica mentale","fascinazione","pause rigenerative","natura"],"motivi":{"fascinazione":"La teoria spiega che gli ambienti naturali attirano l'attenzione senza sforzo, e questa attenzione spontanea permette a quella volontaria di riposare.","fatica mentale":"Il punto di partenza è la fatica dell'attenzione volontaria, quella che serve per concentrarsi su un compito e ignorare le distrazioni.","natura":"Secondo la teoria gli ambienti naturali sono quelli che favoriscono di più il recupero dell'attenzione.","pause rigenerative":"La teoria spiega perché alcune pause rigenerano la capacità di concentrazione più di altre.","recupero dell'attenzione":"È l'articolo che presenta in forma compiuta la teoria del recupero dell'attenzione."},"organizzazioni":[],"prova":"teoria","sinossi":"Kaplan propone un quadro che unisce gli studi sul recupero dallo stress e quelli sulla fatica mentale. L'attenzione volontaria, che usiamo per concentrarci e ignorare le distrazioni, si affatica con l'uso. Certi ambienti la lasciano riposare perché attirano l'interesse senza sforzo e offrono la sensazione di essere altrove, un mondo coerente e abbastanza ampio, e una corrispondenza con ciò che vogliamo fare. Gli ambienti naturali hanno queste quattro qualità più spesso degli ambienti urbani. Le rassegne successive confermano effetti su alcune misure di attenzione e non su altre, e il meccanismo resta discusso.","tipo":"articolo","titolo":"The restorative benefits of nature","url":"https://doi.org/10.1016/0272-4944(95)90001-2","id":"kaplan"},{"anno":1979,"area":"lav","autori":"Robert A. Karasek","autoriIds":["robert-a-karasek"],"collegamenti":["bakker-demerouti","maslach"],"concetti":["stress lavorativo","autonomia","carico di lavoro"],"contesto":["lavoro"],"creata":"2026-11-04","doi":"10.2307/2392498","etichetta":"Karasek","evidenza":"","fonte":"«Job demands, job decision latitude, and mental strain», Administrative Science Quarterly, 24, 1979","inAzienda":"Lo stress di un lavoro dipende non solo da quanto è pesante, ma anche da quanto controllo la persona ha su come svolgerlo. Dare margine di decisione sui tempi e sui metodi riduce il logorio quanto ridurre il carico, e spesso costa meno.","leve":["car","gui","rig"],"macro":"ben","microtemi":["domanda-controllo","stress lavorativo","autonomia","carico di lavoro","margine decisionale"],"motivi":{"autonomia":"Il controllo sul lavoro, cioè poter decidere come e quando svolgerlo, è una forma di autonomia.","carico di lavoro":"Le richieste del lavoro, cioè il carico e la pressione dei tempi, sono uno dei due assi del modello.","domanda-controllo":"L'articolo propone il modello domanda-controllo, che spiega lo stress con la combinazione di richieste e margine di decisione.","margine decisionale":"Il margine decisionale è il secondo asse del modello, e la sua mancanza aggrava l'effetto delle richieste elevate.","stress lavorativo":"Secondo il modello lo stress più dannoso nasce quando richieste elevate si uniscono a un controllo scarso."},"organizzazioni":[],"prova":"studio osservazionale","sinossi":"Karasek usa grandi indagini nazionali su lavoratori svedesi e americani per chiedersi da dove nasca la tensione psicologica sul lavoro. Il risultato è il modello richieste-controllo: la tensione è più alta dove richieste elevate si combinano con poco margine di decisione sul proprio lavoro. Gli stessi carichi, accompagnati da autonomia, definiscono invece lavori attivi, in cui le persone imparano e si sviluppano. Il modello è stato poi esteso al sostegno sociale ed è diventato uno degli strumenti più usati negli studi sulla salute al lavoro. I dati sono autodichiarati e trasversali, quindi non provano da soli la direzione causale.","tipo":"articolo","titolo":"Job demands, job decision latitude, and mental strain","url":"https://doi.org/10.2307/2392498","id":"karasek"},{"anno":1966,"area":"sis","autori":"Daniel Katz e Robert L. Kahn","autoriIds":["daniel-katz","robert-l-kahn"],"collegamenti":["bertalanffy","lawrence-lorsch","schein"],"concetti":["sistemi aperti","lavoro di squadra","cultura organizzativa"],"contesto":["imprese"],"creata":"2026-11-04","etichetta":"Katz e Kahn","evidenza":"","fonte":"The Social Psychology of Organizations, Wiley, 1966","inAzienda":"I ruoli, le norme e i valori che regolano il comportamento delle persone si capiscono solo guardando ciò che l'azienda riceve dall'ambiente e ciò che gli restituisce. Molti conflitti di ruolo nascono da richieste contraddittorie che arrivano da parti diverse dell'organizzazione.","leve":["rel","app"],"macro":"tra","microtemi":["sistema aperto","ruoli","norme","valori","confini organizzativi"],"organizzazioni":[],"prova":"teoria","sinossi":"Daniel Katz e Robert Kahn, psicologi all'Università del Michigan, applicano alla psicologia delle organizzazioni la teoria dei sistemi aperti di Bertalanffy. Un'organizzazione prende energia, persone e informazioni dall'ambiente, le trasforma e restituisce prodotti e servizi, in un ciclo che deve ripetersi perché l'organizzazione sopravviva. Ciò che la tiene insieme non sono le persone in quanto tali ma i ruoli, le norme e i valori che regolano i loro comportamenti. Il libro dedica molto spazio ai ruoli: a come si costruiscono attraverso le attese reciproche e a come generano conflitti e ambiguità. È diventato un classico perché ha spostato lo sguardo dal singolo lavoratore al sistema in cui lavora.","tipo":"libro","titolo":"The Social Psychology of Organizations","url":"https://openlibrary.org/works/OL5273402W","id":"katz-kahn"},{"anno":1965,"area":"nat","autori":"Masao Kawai","autoriIds":["masao-kawai"],"collegamenti":["rogers-e","moscovici"],"concetti":["diffusione delle innovazioni","cultura organizzativa"],"contesto":["primati"],"creata":"2026-11-04","doi":"10.1007/bf01794457","etichetta":"Kawai","evidenza":"funzionale","fonte":"«Newly-acquired pre-cultural behavior of the natural troop of Japanese monkeys on Koshima Islet», Primates, 6(1), 1965","inAzienda":"Un nuovo modo di lavorare spesso nasce da una persona che nessuno ha incaricato di innovare, e si diffonde attraverso le relazioni personali più che attraverso la gerarchia. Chi vuole diffondere un cambiamento deve quindi sapere chi parla con chi.","leve":["rel","app","cul"],"macro":"cam","microtemi":["innovazione","diffusione per relazioni","giovani","periferia del gruppo","precultura","centesima scimmia"],"motivi":{"centesima scimmia":"Dal caso di Koshima è nata la leggenda della centesima scimmia, secondo cui un comportamento si diffonde all'improvviso a tutta la specie: lo studio non la sostiene.","diffusione per relazioni":"Il lavaggio delle patate passò prima ai compagni di gioco e ai parenti della giovane che lo aveva inventato.","giovani":"I giovani del gruppo furono i primi ad adottare il comportamento nuovo.","innovazione":"Kawai descrive comportamenti nuovi introdotti da singoli macachi, come il lavaggio delle patate dolci.","periferia del gruppo":"I maschi adulti, che avevano pochi legami con il resto del gruppo, in gran parte non adottarono il comportamento nuovo.","precultura":"Kawai chiama preculturali i comportamenti appresi e trasmessi all'interno di un gruppo animale."},"organizzazioni":[],"prova":"osservazione sul campo","sinossi":"Masao Kawai, primatologo giapponese, descrive i comportamenti nuovi comparsi nel gruppo di macachi selvatici dell'isola di Koshima, che i ricercatori nutrivano con patate dolci e grano sulla spiaggia. Nel 1953 una giovane femmina cominciò a lavare le patate nell'acqua prima di mangiarle. Il comportamento si diffuse prima fra i coetanei e i parenti, poi alle madri, mentre i maschi adulti, più ai margini delle relazioni, in gran parte non lo adottarono. Negli anni successivi il lavaggio passò dalle madri ai piccoli e diventò una tradizione del gruppo, che Kawai chiama comportamento preculturale. La storia della centesima scimmia, che si dice nata da questo studio, è una leggenda divulgativa senza fondamento.","tipo":"articolo","titolo":"Newly-acquired pre-cultural behavior of the natural troop of Japanese monkeys on Koshima Islet","url":"https://doi.org/10.1007/bf01794457","id":"kawai"},{"anno":2009,"area":"cam","autori":"Robert Kegan e Lisa Laskow Lahey","autoriIds":["robert-kegan","lisa-laskow-lahey"],"collegamenti":["heifetz","argyris-schon","bandura"],"concetti":["cambiamento personale","resistenza al cambiamento"],"contesto":["imprese"],"creata":"2026-11-04","etichetta":"Kegan e Lahey","evidenza":"","fonte":"Immunity to Change, Harvard Business Press, 2009","inAzienda":"Prima di chiedere a una persona di cambiare un comportamento conviene capire che cosa quel comportamento la protegge, per esempio dal timore di sbagliare o di perdere il controllo. Finché quella protezione resta necessaria, nessun proposito basta a cambiarlo.","leve":["app"],"macro":"cam","microtemi":["immunità al cambiamento","impegni nascosti","assunzioni","cambiamento personale","resistenza"],"organizzazioni":[],"prova":"saggio","sinossi":"Kegan e Lahey partono da una constatazione: molte persone non cambiano un comportamento anche quando lo vogliono davvero e ne conoscono l'importanza. Il motivo è un sistema di protezione, che chiamano immunità al cambiamento: impegni nascosti, in conflitto con l'obiettivo dichiarato, e grandi assunzioni date per vere. Il metodo è una mappa in quattro colonne: l'obiettivo di miglioramento, ciò che si fa o non si fa contro di esso, gli impegni nascosti, le assunzioni; poi si mettono alla prova le assunzioni con piccoli esperimenti sicuri. Il libro si appoggia sulla teoria dello sviluppo adulto di Kegan e su molti casi di persone e gruppi. Le prove sono soprattutto casi raccolti dagli autori, con poche verifiche controllate.","tipo":"libro","titolo":"Immunity to Change","url":"https://store.hbr.org/product/immunity-to-change-how-to-overcome-it-and-unlock-the-potential-in-yourself-and-your-organization/1736","id":"kegan-lahey"},{"anno":1993,"area":"nat","autori":"Stephen R. Kellert, Edward O. Wilson","autoriIds":["stephen-r-kellert","edward-o-wilson"],"collegamenti":["wilson-1984-biophilia"],"concetti":["biofilia","connessione con la natura","design biofilico"],"contesto":["natura"],"creata":"2026-11-04","doi":"","etichetta":"Kellert e Wilson","evidenza":"","fonte":"Island Press, Washington (DC), 1993","inAzienda":"Le persone cercano nella natura cose diverse: utilità, bellezza, conoscenza, significato. Conoscere queste differenze aiuta a progettare spazi e attività in natura che abbiano senso per gruppi diversi, invece di proporre a tutti la stessa esperienza.","leve":["rig"],"macro":"ind","microtemi":["biofilia","valori della natura","connessione con la natura","psicologia ambientale"],"motivi":{},"organizzazioni":[],"prova":"saggio","sinossi":"Stephen Kellert ed Edward O. Wilson curano un volume in cui biologi, psicologi e antropologi mettono alla prova l'ipotesi della biofilia, secondo cui gli esseri umani hanno una tendenza innata a cercare il legame con le altre forme di vita. Ogni contributo esamina l'ipotesi da un punto di vista diverso, dalla paura dei serpenti alle preferenze per certi paesaggi. Kellert vi propone una classificazione dei valori che le persone attribuiscono alla natura, dall'utilità pratica all'estetica fino al significato morale. Alcuni capitoli sono apertamente critici e mostrano quanto l'ipotesi sia difficile da verificare.","tipo":"libro","titolo":"The Biophilia Hypothesis","url":"https://openlibrary.org/works/OL17050956W","id":"kellert-1993-biophilia"},{"anno":2015,"area":"nat","autori":"Stephen R. Kellert, Elizabeth F. Calabrese","autoriIds":["stephen-r-kellert","elizabeth-f-calabrese"],"collegamenti":["browning-2014-patterns","kellert-1993-biophilia"],"concetti":["design biofilico","biofilia"],"contesto":["architettura"],"creata":"2026-11-04","doi":"","etichetta":"Kellert e Calabrese","evidenza":"diretta","fonte":"Pubblicazione online, 2015","inAzienda":"La guida traduce l'idea di biofilia in scelte concrete di progettazione: luce, materiali, viste, piante, disposizione degli spazi. Chi ripensa un ufficio può usarla come elenco di possibilità da valutare caso per caso.","leve":["rig"],"macro":"ben","microtemi":["design biofilico","materiali naturali","spazi di lavoro","biofilia"],"motivi":{"biofilia":"La guida si fonda sull'ipotesi della biofilia, secondo cui le persone hanno bisogno di un contatto con il mondo vivente.","design biofilico":"È una guida pratica per applicare il design biofilico alla progettazione degli edifici.","materiali naturali":"Legno, pietra e fibre naturali sono indicati fra i modi di portare un'esperienza indiretta della natura negli spazi.","spazi di lavoro":"I principi della guida si applicano anche agli edifici per uffici e agli spazi comuni delle aziende."},"organizzazioni":[],"prova":"rapporto tecnico","sinossi":"Stephen Kellert ed Elizabeth Calabrese scrivono una guida pratica per architetti, progettisti e committenti che vogliono applicare il design biofilico agli edifici. Partono dall'idea, sviluppata da Kellert in molti anni di lavoro, che le persone abbiano bisogno di un contatto con la natura anche negli ambienti costruiti. Organizzano la guida in tre tipi di esperienza. Il primo è l'esperienza diretta della natura, come luce, aria, acqua, piante, animali e paesaggi. Il secondo è l'esperienza indiretta, attraverso immagini, materiali, colori, forme e geometrie che ricordano la natura. Il terzo è l'esperienza dello spazio e del luogo, come la vista ampia insieme al rifugio, la complessità ordinata e il legame con la cultura e l'ecologia del posto, e per ciascun tipo elencano attributi concreti e principi di applicazione. È un documento operativo più che una ricerca, e i benefici attribuiti ai singoli attributi hanno prove di forza molto diversa.","tipo":"rapporto","titolo":"The Practice of Biophilic Design","url":"https://www.biophilic-design.com/_files/ugd/21459d_81ccb84caf6d4bee8195f9b5af92d8f4.pdf","id":"kellert-2015-practice"},{"anno":2020,"area":"evo","autori":"Katherine C. Kellogg, Melissa A. Valentine, Angèle Christin","autoriIds":["katherine-c-kellogg","melissa-a-valentine","angele-christin"],"collegamenti":["wiener","morrison-milliken","hirschman"],"concetti":["intelligenza artificiale","trasformazione digitale","autonomia","resistenza al cambiamento","voce"],"contesto":["tecnologia","piattaforme"],"creata":"2026-11-05","doi":"10.5465/annals.2018.0174","etichetta":"Kellogg et al.","evidenza":"","fonte":"Academy of Management Annals, 14(1), 366-410, 2020","inAzienda":"Un sistema algoritmico di assegnazione o valutazione va reso spiegabile e discutibile, altrimenti genera resistenza e silenzio invece di efficienza.","leve":["gui","rel"],"macro":"tra","microtemi":["intelligenza artificiale","piattaforme","controllo","resistenza","voce"],"motivi":{"controllo":"Il tema centrale è come cambia il controllo del lavoro.","intelligenza artificiale":"Studia gli algoritmi che dirigono, valutano e disciplinano il lavoro.","piattaforme":"Molti degli studi rivisti riguardano il lavoro organizzato da piattaforme digitali.","resistenza":"Descrive le tattiche con cui i lavoratori resistono al controllo algoritmico.","voce":"La possibilità di contestare un algoritmo è una forma di voce."},"organizzazioni":[],"prova":"rassegna","sinossi":"Le autrici si chiedono come gli algoritmi stiano cambiando il controllo del lavoro nelle organizzazioni, dalle piattaforme di consegna agli uffici. Riprendono l'idea di Edwards del lavoro come terreno conteso, in cui i manager introducono tecnologie per governare il lavoro e i lavoratori resistono, e la usano per ordinare una letteratura interdisciplinare. Individuano sei meccanismi di controllo algoritmico: limitare e raccomandare per dirigere, registrare e valutare per giudicare, sostituire e premiare per disciplinare. Sostengono che questo controllo è diverso da quello tecnico e burocratico del secolo scorso, perché è più completo, immediato e opaco. Notano che nascono nuove professioni legate agli algoritmi e che i lavoratori resistono con tattiche individuali e collettive che chiamano algoattivismo. La rassegna ha corretto una visione troppo entusiasta degli algoritmi al lavoro. È una sintesi teorica, con studi molto diversi fra loro e poco italiani.","tipo":"articolo","titolo":"Algorithms at Work: The New Contested Terrain of Control","url":"https://doi.org/10.5465/annals.2018.0174","id":"kellogg-2020-algorithms"},{"anno":2006,"area":"soc","autori":"James G. Kelly","autoriIds":["james-g-kelly"],"collegamenti":["lewin","francescato","bertalanffy"],"concetti":["sistemi aperti","contingenza","impresa familiare"],"contesto":["comunità"],"creata":"2026-11-04","doi":"10.1037/h0023598","etichetta":"J.G. Kelly","evidenza":"","fonte":"Becoming Ecological, Oxford University Press, 2006; «Ecological constraints on mental health services», American Psychologist, 21(6), 1966","inAzienda":"Prima di intervenire su un'organizzazione bisogna conoscerne le interdipendenze, le risorse, il modo in cui si adatta e la sua storia, perché ogni intervento produce effetti anche lontano dal punto in cui agisce. Quattro delle sei leggi del metodo sviluppano questi principi di Kelly.","leve":["rel","car","app","rig","cul"],"macro":"tra","microtemi":["interdipendenza","ciclicità delle risorse","adattamento","successione","psicologia di comunità"],"organizzazioni":[],"prova":"teoria","sinossi":"James G. Kelly, psicologo di comunità americano, propone nel 1966 di progettare gli interventi sulle comunità come si studia un sistema ecologico. Indica quattro principi. L'interdipendenza: ogni parte del sistema è legata alle altre, e un cambiamento in un punto produce effetti altrove. La ciclicità delle risorse: le risorse materiali, umane e simboliche nascono, circolano e si consumano, e vanno conosciute prima di intervenire. L'adattamento: le persone si adattano all'ambiente e insieme lo modificano. La successione: ogni sistema ha una storia e una traiettoria, che l'intervento deve rispettare. Il volume del 2006 raccoglie i suoi scritti principali e racconta come questa idea ha formato la psicologia di comunità.","tipo":"articolo","titolo":"Ecological constraints on mental health services","url":"https://doi.org/10.1037/h0023598","id":"kelly"},{"anno":2013,"area":"nat","autori":"Robin Wall Kimmerer","autoriIds":["robin-wall-kimmerer"],"collegamenti":["wilkinson"],"concetti":["reciprocità","connessione con la natura"],"contesto":["natura","piante"],"creata":"2026-11-04","doi":"","etichetta":"Kimmerer","evidenza":"","fonte":"Milkweed Editions, Minneapolis, 2013","inAzienda":"Il libro offre un linguaggio per parlare del rapporto fra impresa e ambiente come scambio reciproco, in cui si restituisce qualcosa di ciò che si prende. È utile nei percorsi sulla cultura e sul senso del lavoro, non come prova scientifica.","leve":["rig","rel","cul"],"macro":"cul","microtemi":["reciprocità","rapporto uomo natura","saperi tradizionali","cura"],"motivi":{"cura":"Il prendersi cura della terra e delle piante è uno dei temi che attraversano tutto il libro.","rapporto uomo natura":"Il libro tratta il rapporto fra le persone e le piante, unendo il punto di vista della botanica e quello della tradizione indigena.","reciprocità":"La reciprocità, cioè restituire ciò che si riceve, è l'idea centrale del libro.","saperi tradizionali":"Kimmerer intreccia le conoscenze della botanica con i saperi della nazione Potawatomi."},"organizzazioni":[],"prova":"saggio","sinossi":"Robin Wall Kimmerer è botanica, docente al College of Environmental Science and Forestry dell'Università statale di New York e membro della nazione Potawatomi. In questo libro, una raccolta di saggi, intreccia ciò che ha imparato studiando le piante con i saperi della tradizione indigena e con la propria storia personale. L'idea che tiene insieme i capitoli è che il rapporto con il mondo vivente dovrebbe fondarsi sulla reciprocità, cioè sul dare indietro in proporzione a ciò che si riceve. Racconta la raccolta dell'erba sacra, la coltivazione insieme di mais, fagioli e zucca, chiamati le tre sorelle, e le regole di un raccolto rispettoso che prende solo ciò che serve. Mette a confronto l'economia del dono con quella dello scambio di merci e si chiede che cosa cambi quando si considera la terra come un insieme di relazioni e non come una risorsa. Il libro ha avuto un ampio successo internazionale anche fuori dal pubblico specialistico. È un saggio narrativo e non una ricerca empirica, e va usato come fonte di immagini e di domande più che di prove.","tipo":"libro","titolo":"Braiding Sweetgrass","url":"https://milkweed.org/book/braiding-sweetgrass","id":"kimmerer-2013-sweetgrass"},{"anno":1967,"area":"evo","autori":"Paul R. Lawrence e Jay W. Lorsch","autoriIds":["paul-r-lawrence","jay-w-lorsch"],"collegamenti":["katz-kahn","emery-trist","ashby","mintzberg"],"concetti":["contingenza"],"contesto":["manifattura"],"creata":"2026-11-04","etichetta":"Lawrence e Lorsch","evidenza":"","fonte":"Organization and Environment, Harvard Business School, 1967","inAzienda":"Non esiste un modo migliore di organizzarsi valido per tutte le aziende: dipende da quanto è incerto l'ambiente in cui operano. Per questo la diagnosi parte dal verificare se l'organizzazione interna è adatta all'ambiente esterno, prima di proporre qualsiasi modello.","leve":["gui","app"],"macro":"tra","microtemi":["contingenza","differenziazione","integrazione","incertezza ambientale","struttura"],"organizzazioni":[],"prova":"studio osservazionale","sinossi":"Paul Lawrence e Jay Lorsch, della Harvard Business School, confrontano aziende di tre settori con livelli diversi di incertezza: la plastica, molto incerta; gli alimentari confezionati, a metà; i contenitori, stabili. Trovano che le aziende migliori di ciascun settore non si organizzano allo stesso modo. Dove l'ambiente è incerto, i reparti si differenziano molto fra loro per obiettivi, tempi e stili, e l'azienda investe molto per integrarli, con ruoli di collegamento e gruppi misti. Dove l'ambiente è stabile basta meno differenziazione, e l'integrazione può passare dalla gerarchia. Da qui nasce la teoria della contingenza: non esiste un modo migliore di organizzarsi in assoluto, ma solo un modo adatto all'ambiente.","tipo":"libro","titolo":"Organization and Environment","url":"https://openlibrary.org/works/OL43118257W","id":"lawrence-lorsch"},{"anno":2004,"area":"evo","autori":"Isabelle Le Breton-Miller, Danny Miller, Lloyd P. Steier","autoriIds":["isabelle-le-breton-miller","danny-miller","lloyd-p-steier"],"collegamenti":["schein","weick"],"concetti":["impresa familiare","cultura organizzativa"],"contesto":["impresa familiare"],"creata":"2026-11-05","doi":"10.1111/j.1540-6520.2004.00047.x","etichetta":"Le Breton-Miller et al.","evidenza":"","fonte":"Entrepreneurship Theory and Practice, 28(4), 305-328, 2004","inAzienda":"La successione va preparata per anni, con un percorso di formazione del successore e un'uscita del fondatore concordata, non decisa all'ultimo momento.","leve":["gui","rel"],"macro":"cul","microtemi":["passaggio generazionale","impresa familiare","successione familiare","cultura organizzativa","valori"],"motivi":{"cultura organizzativa":"Il contesto culturale di famiglia e impresa è parte del modello.","impresa familiare":"Il campo di studio sono le imprese possedute da famiglie.","passaggio generazionale":"È un modello integrato della successione al vertice nelle imprese familiari.","successione familiare":"Analizza le condizioni perché la successione riesca.","valori":"La trasmissione dei valori fra generazioni pesa sul passaggio."},"organizzazioni":[],"prova":"rassegna","sinossi":"Isabelle Le Breton-Miller e Lloyd Steier, dell'Università dell'Alberta, e Danny Miller, di HEC Montréal e della stessa università, partono da un dato spesso ripetuto negli studi sulle imprese familiari: meno del 10 per cento arriva alla terza generazione, e il passaggio al vertice è uno dei momenti in cui tutto si gioca. La letteratura sulla successione era frammentata, ciascuno studio guardava un pezzo diverso del problema, e l'articolo prova a ricomporla. Gli autori rileggono gli studi esistenti e costruiscono un modello integrato di che cosa serve perché una successione riesca. Il modello tiene insieme il contesto della famiglia, dell'impresa e del settore, la preparazione e la formazione del successore, i rapporti fra predecessore e successore, e le fasi del passaggio, dalla scelta all'uscita del predecessore. Indicano dove la ricerca è d'accordo, dove ci sono lacune e quali domande restano aperte. Il lavoro è diventato un riferimento per chi studia e accompagna il passaggio generazionale. È una sintesi teorica, senza dati nuovi, e il dato sul 10 per cento viene da stime diffuse e discusse più che da un campione controllato.","tipo":"articolo","titolo":"Toward an Integrative Model of Effective FOB Succession","url":"https://doi.org/10.1111/j.1540-6520.2004.00047.x","id":"lebretonmiller-2004-succession"},{"anno":2015,"area":"nat","autori":"Kate E. Lee, Kathryn J.H. Williams, Leisa D. Sargent, Nicholas S.G. Williams, Katherine A. Johnson","autoriIds":["kate-e-lee","kathryn-j-h-williams","leisa-d-sargent","nicholas-s-g-williams","katherine-a-johnson"],"collegamenti":["kaplan","ulrich"],"concetti":["vista sul verde","recupero","recupero dell'attenzione","design biofilico"],"contesto":["laboratorio"],"creata":"2026-11-04","doi":"10.1016/j.jenvp.2015.04.003","etichetta":"Lee et al.","evidenza":"diretta","fonte":"Journal of Environmental Psychology, 42, 182-189, 2015","inAzienda":"Durante un lavoro che richiede concentrazione continua, una pausa di pochi secondi guardando del verde riduce gli errori successivi. Disporre le postazioni in modo che chi lavora possa vedere alberi o piante è quindi un intervento utile e poco costoso.","leve":["rig"],"macro":"ben","microtemi":["vista sul verde","micro-pause","recupero dell'attenzione","spazi di lavoro"],"motivi":{"micro-pause":"La pausa studiata dura solo quaranta secondi, eppure ha un effetto misurabile sugli errori.","recupero dell'attenzione":"Lo studio mette alla prova sperimentalmente la teoria del recupero dell'attenzione dei Kaplan.","spazi di lavoro":"I risultati suggeriscono di progettare gli spazi di lavoro in modo da offrire viste sul verde.","vista sul verde":"La pausa consisteva nel guardare l'immagine di un tetto coperto di prato e fiori, confrontata con un tetto di cemento."},"organizzazioni":[],"prova":"esperimento di laboratorio","sinossi":"Kate Lee e i suoi colleghi dell'Università di Melbourne vogliono verificare se anche una pausa brevissima con vista sulla natura possa sostenere l'attenzione, come prevede la teoria del recupero dell'attenzione. Fanno svolgere a un gruppo di studenti universitari un compito noioso che richiede di restare concentrati a lungo e di trattenere una risposta automatica. A metà compito i partecipanti fanno una pausa di quaranta secondi guardando sullo schermo l'immagine di un tetto coperto di prato e fiori oppure quella di un tetto di cemento. Dopo la pausa chi ha guardato il tetto verde commette meno errori di distrazione e mantiene una prestazione più stabile. Chi ha guardato il cemento mostra invece un calo della concentrazione e una prestazione più irregolare. Gli autori suggeriscono che le micro-pause con vista sul verde, possibili anche da una finestra o da un tetto vicino, siano un modo semplice per sostenere l'attenzione al lavoro. L'esperimento è di laboratorio, con studenti e immagini su schermo, e misura effetti immediati, non nel corso di una giornata di lavoro.","tipo":"articolo","titolo":"40-second green roof views sustain attention: The role of micro-breaks in attention restoration","url":"https://doi.org/10.1016/j.jenvp.2015.04.003","id":"lee-2015-green-roof"},{"anno":2017,"area":"evo","autori":"Michael Y. Lee, Amy C. Edmondson","autoriIds":["michael-y-lee","amy-c-edmondson"],"collegamenti":["pearce-conger","mintzberg","bienefeld-grote","ostrom"],"concetti":["decentralizzazione","guida distribuita","lavoro di squadra"],"contesto":["imprese"],"creata":"2026-11-05","doi":"10.1016/j.riob.2017.10.002","etichetta":"Lee","evidenza":"","fonte":"Research in Organizational Behavior, 37, 35-58, 2017","inAzienda":"Prima di annunciare un'organizzazione senza capi conviene decidere quali decisioni si decentrano davvero, con quali regole e chi risponde quando qualcosa va storto.","leve":["gui"],"macro":"lea","microtemi":["decentralizzazione","guida distribuita","autogoverno","responsabilità finale","ruoli"],"motivi":{"autogoverno":"Il tema è l'autogestione a livello di intera organizzazione.","decentralizzazione":"Definisce le organizzazioni che decentralizzano l'autorità in modo radicale.","guida distribuita":"Discute i limiti della distribuzione dell'autorità.","responsabilità finale":"Si chiede chi decide e risponde quando la gerarchia si riduce.","ruoli":"Nelle organizzazioni autogestite i ruoli sostituiscono le posizioni gerarchiche."},"organizzazioni":[],"prova":"rassegna","sinossi":"Lee ed Edmondson osservano che molte organizzazioni dichiarano di voler ridurre la gerarchia, ma pochissime lo fanno davvero. Definiscono organizzazioni autogestite quelle che decentralizzano l'autorità in modo radicale, formale e sistematico in tutta l'organizzazione, e non solo in alcuni team o in alcuni progetti. Distinguono queste forme dalle pratiche di coinvolgimento e di team autonomi dentro una struttura gerarchica rimasta intatta. Esaminano esempi noti, come le aziende che hanno adottato l'olacrazia, e discutono che cosa cambia nella distribuzione dell'autorità, nei ruoli e nel modo di risolvere i conflitti. Si chiedono in quali condizioni questa forma funziona e dove incontra i suoi limiti, per esempio nella gestione delle tensioni e delle decisioni difficili. Propongono un programma di ricerca su questi limiti. È un saggio teorico che si basa su casi pubblicati e non su dati sistematici di efficacia.","tipo":"articolo","titolo":"Self-managing organizations: Exploring the limits of less-hierarchical organizing","url":"https://doi.org/10.1016/j.riob.2017.10.002","id":"lee-2017-selfmanaging"},{"anno":2011,"area":"lav","autori":"Stavroula Leka, Aditya Jain, Tom Cox, Evelyn Kortum","autoriIds":["stavroula-leka","aditya-jain","tom-cox","evelyn-kortum"],"collegamenti":["karasek","bakker-demerouti","avallone-2003-benessere"],"concetti":["benessere organizzativo","stress lavorativo"],"contesto":["politiche europee"],"creata":"2026-11-05","doi":"10.1539/joh.o10010","etichetta":"Leka et al.","evidenza":"","fonte":"Journal of Occupational Health, 53(2), 137-143, 2011","inAzienda":"La gestione dei rischi psicosociali segue lo stesso ciclo della gestione degli altri rischi: valutazione, intervento sull'organizzazione del lavoro, verifica nel tempo.","leve":["rig","car"],"macro":"ben","microtemi":["benessere organizzativo","stress lavoro correlato","stress lavorativo","rischi psicosociali","richieste-risorse"],"motivi":{"benessere organizzativo":"Inquadra il benessere al lavoro nella gestione europea dei rischi psicosociali.","richieste-risorse":"Gestire il rischio significa intervenire su richieste e risorse del lavoro.","rischi psicosociali":"È il quadro europeo di riferimento per la loro gestione.","stress lavorativo":"Lo stress è l'esito che il quadro vuole prevenire.","stress lavoro correlato":"I rischi psicosociali sono la fonte dello stress lavoro correlato."},"organizzazioni":[],"prova":"rapporto tecnico","sinossi":"L'articolo descrive come è nato PRIMA-EF, il quadro europeo per la gestione dei rischi psicosociali, cioè dei fattori di organizzazione del lavoro che possono produrre stress lavoro correlato e danni alla salute. Il quadro è stato costruito riesaminando, confrontando e armonizzando gli approcci di gestione dei rischi psicosociali e di promozione della salute mentale già usati in Europa. Gli autori partono da un'analisi teorica del processo di gestione del rischio, nei suoi principi, nelle strategie e procedure e nelle misure, e la applicano ai diversi modelli europei. Al lavoro hanno partecipato esperti, ricercatori, parti sociali e organizzazioni europee e internazionali, con rassegne di letteratura, studi di caso, interviste, questionari, gruppi di discussione e seminari. Ne sono nati strumenti pratici per le imprese e per i decisori pubblici, come linee guida, indicatori e schede operative. Il quadro vuole contenere tutti gli approcci esistenti e offrire indicatori sia a livello di impresa sia a livello nazionale. È un documento di politica e di metodo, non uno studio sugli effetti degli interventi.","tipo":"articolo","titolo":"The Development of the European Framework for Psychosocial Risk Management: PRIMA-EF","url":"https://doi.org/10.1539/joh.o10010","id":"leka-2011-psychosocial"},{"anno":1946,"area":"soc","autori":"Kurt Lewin","autoriIds":["kurt-lewin"],"collegamenti":["coch-french","emery-trist","schein","argyris-schon","edmondson","kelly","heifetz"],"concetti":["partecipazione","decisione collettiva","resistenza al cambiamento"],"contesto":["comunità"],"creata":"2026-11-04","doi":"10.1111/j.1540-4560.1946.tb02295.x","etichetta":"Lewin","evidenza":"","fonte":"«Action research and minority problems», Journal of Social Issues, 2(4), 1946; «Frontiers in group dynamics», Human Relations, 1, 1947","inAzienda":"Un cambiamento in azienda funziona meglio se le persone partecipano alla ricerca delle cause e alla scelta delle soluzioni, e se le decisioni vengono prese in gruppo. È il principio della ricerca-azione, su cui si fonda ogni percorso del metodo.","leve":["app","rel"],"macro":"cam","microtemi":["ricerca-azione","decisione di gruppo","scongelamento","teoria del campo","resistenza al cambiamento","partecipazione"],"motivi":{"decisione di gruppo":"Lewin mostrò che le decisioni prese in gruppo modificano i comportamenti più di quelle comunicate dall'alto.","partecipazione":"Nella ricerca-azione le persone coinvolte partecipano all'analisi del problema e alla scelta delle soluzioni.","resistenza al cambiamento":"Lewin descrive le forze che si oppongono al cambiamento come parte del campo in cui la persona si muove.","ricerca-azione":"Lewin propone la ricerca-azione, in cui si studia un sistema mentre si interviene per cambiarlo.","scongelamento":"Il cambiamento comincia rendendo discutibili le abitudini esistenti, fase che Lewin chiama scongelamento.","teoria del campo":"Lewin spiega il comportamento come risultato delle forze della persona e del suo ambiente."},"organizzazioni":[],"prova":"teoria","sinossi":"Lewin propone di studiare i problemi sociali con la ricerca-azione: un ciclo di pianificazione, azione e verifica dei risultati, ripetuto insieme alle persone coinvolte invece che su di loro. Alla base c'è la teoria del campo, per cui il comportamento dipende insieme dalla persona e dall'ambiente in cui si trova in quel momento. Negli studi sulle abitudini alimentari condotti durante la guerra, le decisioni prese in gruppo producevano cambiamenti più duraturi delle conferenze. Da questi lavori nasce la descrizione del cambiamento in tre momenti: scongelare l'equilibrio esistente, muoverlo, stabilizzarlo di nuovo. Gli storici del management hanno mostrato che la formula in tre fasi è stata semplificata dai manuali successivi, mentre Lewin la intendeva come parte di un metodo più ampio di ricerca e partecipazione.","tipo":"articolo","titolo":"Action research and minority problems","url":"https://doi.org/10.1111/j.1540-4560.1946.tb02295.x","id":"lewin"},{"anno":2010,"area":"nat","autori":"Qing Li","autoriIds":["qing-li"],"collegamenti":["meneguzzo-2022-terapia"],"concetti":["immersione nel bosco","stress lavorativo"],"contesto":["foreste"],"creata":"2026-11-04","doi":"10.1007/s12199-008-0068-3","etichetta":"Li","evidenza":"diretta","fonte":"Environmental Health and Preventive Medicine, 15(1), 9-17, 2010","inAzienda":"L'aria del bosco, con le sostanze volatili emesse dagli alberi, sembra avere effetti misurabili sul sistema immunitario, anche se le prove sono ancora preliminari. Le giornate in natura vanno quindi proposte come un'esperienza di recupero, senza promettere effetti sulla salute.","leve":["rig"],"macro":"ben","microtemi":["odori e fitoncidi","immersione nel bosco","sistema immunitario","salute"],"motivi":{},"organizzazioni":[],"prova":"esperimento di campo","sinossi":"Qing Li, medico della Nippon Medical School di Tokyo, riassume una serie di suoi studi sulle giornate di immersione nel bosco, la pratica che in Giappone si chiama shinrin-yoku. Gruppi di adulti trascorrono due o tre giorni camminando nella foresta, e prima e dopo l'autore misura nel sangue l'attività delle cellule natural killer, che fanno parte delle difese immunitarie. Dopo le escursioni l'attività di queste cellule aumenta e resta più alta per alcuni giorni, mentre una gita in città non produce lo stesso effetto. Li attribuisce una parte del risultato ai fitoncidi, le sostanze volatili emesse dagli alberi. I campioni sono piccoli e mancano gruppi di controllo randomizzati, quindi i risultati vanno presi come indicazioni.","tipo":"articolo","titolo":"Effect of forest bathing trips on human immune function","url":"https://doi.org/10.1007/s12199-008-0068-3","id":"li-2010-forest-bathing"},{"anno":2017,"area":"nat","autori":"Ryan Lumber, Miles Richardson, David Sheffield","autoriIds":["ryan-lumber","miles-richardson","david-sheffield"],"collegamenti":["capaldi-2014-connectedness"],"concetti":["connessione con la natura"],"contesto":["natura"],"creata":"2026-11-04","doi":"10.1371/journal.pone.0177186","etichetta":"Lumber et al.","evidenza":"","fonte":"PLoS ONE, 12(5), e0177186, 2017","inAzienda":"Un'attività in natura con un gruppo di lavoro rafforza il legame delle persone con la natura se le coinvolge con i sensi, le emozioni e il significato, più che se fornisce nozioni. Questo criterio orienta la progettazione delle giornate in natura del metodo.","leve":["rig","rel"],"macro":"ind","microtemi":["connessione con la natura","bellezza","emozione","esperienza diretta"],"motivi":{"bellezza":"Gli autori indicano la percezione della bellezza della natura come una delle cinque vie del legame.","connessione con la natura":"Lo studio cerca quali attività aumentano il senso di legame delle persone con la natura.","emozione":"Le emozioni suscitate dalla natura sono una delle cinque vie individuate.","esperienza diretta":"Il contatto diretto con i sensi rafforza il legame con la natura più della conoscenza di nozioni."},"organizzazioni":[],"prova":"indagine con questionario","sinossi":"Ryan Lumber, Miles Richardson e David Sheffield, dell'Università di Derby, partono da un dato: sentirsi legati alla natura fa bene al benessere e ai comportamenti verso l'ambiente, ma non si sapeva quali attività rafforzino davvero questo legame. Strutturano due indagini online, con 321 partecipanti in tutto, intorno ai nove valori della natura descritti dall'ipotesi della biofilia. Il legame con la natura è previsto dal contatto, dalle emozioni, dal significato e dalla compassione, quest'ultima mediata dal coinvolgimento con la bellezza naturale, mentre le attività basate sulla conoscenza non lo prevedono. In un terzo studio, con 72 partecipanti, mettono alla prova una passeggiata con attività costruite su queste vie. Questa passeggiata aumenta il legame con la natura più di una semplice passeggiata nel verde o di una passeggiata in un ambiente costruito. Da questi risultati nasce un modello di cinque vie, contatto, emozione, significato, compassione e bellezza, usato per progettare esperienze in natura. Gli studi si basano su questionari, su campioni piccoli e in buona parte di studenti, e misurano effetti a breve termine.","tipo":"articolo","titolo":"Beyond knowing nature: Contact, emotion, compassion, meaning, and beauty are pathways to nature connection","url":"https://doi.org/10.1371/journal.pone.0177186","id":"lumber-2017-pathways"},{"anno":1991,"area":"evo","autori":"James G. March","autoriIds":["james-g-march"],"collegamenti":["simon","seeley-nido","holling"],"concetti":["esplorazione e sfruttamento","apprendimento organizzativo","diffusione delle innovazioni","contingenza"],"contesto":["imprese"],"creata":"2026-11-04","doi":"10.1287/orsc.2.1.71","etichetta":"March","evidenza":"","fonte":"«Exploration and exploitation in organizational learning», Organization Science, 2(1), 1991","inAzienda":"Un'azienda che investe solo nel perfezionare ciò che sa già fare ottiene risultati immediati, ma perde gradualmente la capacità di cambiare quando il mercato cambia. Una che esplora soltanto disperde le risorse. Il compito della direzione è proteggere una quota stabile di esplorazione accanto allo sfruttamento.","leve":["app"],"macro":"app","microtemi":["esplorazione","sfruttamento","apprendimento organizzativo","innovazione","adattamento"],"motivi":{"adattamento":"L'equilibrio fra esplorazione e sfruttamento determina la capacità di un'organizzazione di adattarsi nel tempo.","apprendimento organizzativo":"L'articolo studia come le organizzazioni imparano e quali scelte di apprendimento le rendono più forti o più fragili.","esplorazione":"March definisce l'esplorazione come la ricerca di possibilità nuove, dai risultati incerti e lontani nel tempo.","innovazione":"L'esplorazione è la fonte delle innovazioni, e March mostra perché tende a essere sacrificata.","sfruttamento":"March definisce lo sfruttamento come il perfezionamento di ciò che l'organizzazione sa già fare."},"organizzazioni":[],"prova":"modello matematico","sinossi":"James March descrive un dilemma che ogni organizzazione deve gestire: sfruttare ciò che sa già fare, migliorandolo, oppure esplorare possibilità nuove, dai risultati incerti e lontani. Lo sfruttamento dà ritorni rapidi e sicuri; l'esplorazione dà ritorni incerti, spesso negativi, ma è l'unico modo di prepararsi a un ambiente che cambia. Con modelli di simulazione March mostra che l'apprendimento tende per sua natura a favorire lo sfruttamento, perché premia ciò che funziona subito, e che questo porta a una trappola: l'organizzazione diventa sempre più brava in qualcosa che sta perdendo valore. Lo stesso articolo mostra che un ricambio moderato di persone può aiutare l'organizzazione a imparare. È uno degli articoli più citati negli studi sull'innovazione.","tipo":"articolo","titolo":"Exploration and exploitation in organizational learning","url":"https://doi.org/10.1287/orsc.2.1.71","id":"march"},{"anno":1997,"area":"lav","autori":"Christina Maslach","autoriIds":["christina-maslach"],"collegamenti":["bakker-demerouti","karasek"],"concetti":["burnout","carico di lavoro","diversità","cultura organizzativa"],"contesto":["imprese"],"creata":"2026-11-04","etichetta":"Maslach","evidenza":"","fonte":"C. Maslach, M.P. Leiter, The Truth About Burnout, Jossey-Bass, 1997","inAzienda":"Il burnout nasce soprattutto da squilibri nelle condizioni di lavoro, come carico, controllo, riconoscimento, equità e valori, più che dalla debolezza dei singoli. Per prevenirlo bisogna quindi intervenire su quelle condizioni, non solo offrire corsi sulla gestione dello stress.","leve":["rig","car"],"macro":"ben","microtemi":["burnout","esaurimento","cinismo","carico di lavoro","equità","valori"],"motivi":{"burnout":"Il libro spiega il burnout attraverso le ricerche di chi ha costruito lo strumento più usato per misurarlo.","carico di lavoro":"Il carico eccessivo è la prima delle sei aree di squilibrio fra persona e lavoro che portano al burnout.","cinismo":"Il distacco cinico dal lavoro è, con l'esaurimento e il senso di inefficacia, una delle tre componenti del burnout.","equità":"La percezione di essere trattati in modo ingiusto è una delle sei aree di squilibrio.","esaurimento":"L'esaurimento delle energie è la componente più visibile del burnout.","valori":"Il contrasto fra i valori della persona e quelli dell'organizzazione è una delle sei aree di squilibrio."},"organizzazioni":[],"prova":"saggio","sinossi":"Christina Maslach e Michael Leiter scrivono per manager e direzioni del personale e spostano lo sguardo dalla persona fragile all'organizzazione che consuma chi ci lavora. Il burnout ha tre componenti, l'esaurimento, il cinismo e il senso di inefficacia, che Maslach aveva già misurato con il questionario che porta il suo nome. Secondo gli autori nasce da uno squilibrio cronico fra la persona e il lavoro, e questo squilibrio si osserva in sei aree: il carico, il controllo, il riconoscimento, la comunità, l'equità e i valori. Per ciascuna area descrivono come si presenta lo squilibrio e quali segnali lo rendono visibile in un gruppo. La prevenzione passa dal riequilibrare queste aree con interventi sull'organizzazione, più che dal rafforzare i singoli con corsi sullo stress. Il libro ha reso familiare questo modo di vedere il burnout anche fuori dalla ricerca. È un testo divulgativo, e le sei aree sono state studiate con misure dedicate solo in seguito.","tipo":"libro","titolo":"The Truth About Burnout","url":"https://www.wiley.com/en-us/The+Truth+About+Burnout%3A+How+Organizations+Cause+Personal+Stress+and+What+to+Do+About+It-p-9781118692134","id":"maslach"},{"anno":1980,"area":"sis","autori":"Humberto Maturana e Francisco Varela","autoriIds":["humberto-maturana","francisco-varela"],"collegamenti":["bateson","weick"],"concetti":["autopoiesi"],"contesto":["biologia"],"creata":"2026-11-04","doi":"10.1007/978-94-009-8947-4","etichetta":"Maturana e Varela","evidenza":"","fonte":"Autopoiesis and Cognition, Reidel, 1980","inAzienda":"Nessun intervento può imporre un cambiamento a un'organizzazione: può solo creare condizioni a cui l'organizzazione risponde secondo il proprio modo di funzionare. Per questo bisogna conoscere quel modo di funzionare prima di intervenire.","leve":["app","cul"],"macro":"cam","microtemi":["autopoiesi","chiusura operativa","perturbazione","cognizione","accoppiamento strutturale"],"organizzazioni":[],"prova":"teoria","sinossi":"Humberto Maturana e Francisco Varela, biologi cileni, propongono una definizione di vita: un sistema vivente è un'organizzazione che produce di continuo i componenti di cui è fatta, e così mantiene se stessa. Chiamano questa proprietà autopoiesi. Un sistema autopoietico cambia continuamente la propria struttura, ma conserva la propria organizzazione, cioè la propria identità. L'ambiente lo perturba ma non lo determina: è il sistema, secondo la propria struttura, a stabilire come reagire a ciò che gli arriva. Il libro riunisce due testi degli anni Settanta ed è di lettura difficile. Le sue idee sono state applicate alle organizzazioni e alle famiglie, anche se gli autori erano prudenti su questo uso.","tipo":"libro","titolo":"Autopoiesis and Cognition","url":"https://doi.org/10.1007/978-94-009-8947-4","id":"maturana-varela"},{"anno":2008,"area":"sis","autori":"Donella H. Meadows","autoriIds":["donella-h-meadows"],"collegamenti":["bertalanffy","senge","benyus"],"concetti":["cambiamento organizzativo","retroazione"],"contesto":["sistemi"],"creata":"2026-11-04","etichetta":"Meadows","evidenza":"","fonte":"Thinking in Systems, Chelsea Green, 2008; Leverage Points, Sustainability Institute, 1999","inAzienda":"In ogni organizzazione esistono punti in cui un intervento piccolo produce effetti grandi, e altri in cui grandi sforzi cambiano poco. Il metodo usa questa idea per scegliere, fra le sei leve, quella su cui agire per prima.","leve":["rel","car","gui","app","rig"],"macro":"cam","microtemi":["punti di leva","cicli di retroazione","pensiero sistemico","stock e flussi","obiettivi di sistema"],"organizzazioni":[],"prova":"teoria","sinossi":"Donella Meadows, scienziata ambientale e coautrice del rapporto sui limiti dello sviluppo del 1972, spiega in modo semplice come funzionano i sistemi: stock che si accumulano, flussi che li riempiono e li svuotano, cicli di retroazione che li stabilizzano o li fanno crescere. Il libro mostra perché i sistemi sorprendono spesso chi li governa, con ritardi, effetti lontani dalle cause e soluzioni che peggiorano il problema. Nel saggio sui punti di leva Meadows ordina i punti in cui si può intervenire su un sistema, dai meno efficaci, come cambiare un parametro, ai più efficaci, come cambiare gli obiettivi e il modo di pensare del sistema. Una piccola spinta nel punto giusto può produrre grandi effetti, ma i punti di leva sono spesso controintuitivi. È il testo di riferimento per chi vuole usare il pensiero sistemico senza matematica.","tipo":"libro","titolo":"Thinking in Systems","url":"https://openlibrary.org/works/OL3737036W","id":"meadows"},{"anno":1999,"area":"nat","autori":"L. David Mech","autoriIds":["l-david-mech"],"collegamenti":["bass"],"concetti":["mito del capo dominante","impresa familiare","stile di guida"],"contesto":["lupi"],"creata":"2026-11-04","doi":"10.1139/z99-099","etichetta":"Mech","evidenza":"funzionale","fonte":"«Alpha status, dominance, and division of labor in wolf packs», Canadian Journal of Zoology, 77, 1999","inAzienda":"Molte idee sul comando, come quella del capo che domina con la forza, si appoggiano a immagini della natura che la ricerca ha smentito. Prima di usare un esempio naturale bisogna quindi verificare che sia documentato.","leve":["gui"],"macro":"lea","microtemi":["lupo alfa","leggende","famiglia","dominanza","guida"],"motivi":{"dominanza":"Mech mostra che nei branchi selvatici le lotte per il rango sono rare.","famiglia":"Il branco selvatico è una famiglia formata dai genitori e dai loro figli.","guida":"I genitori guidano il branco perché sono i genitori, non perché hanno vinto una lotta.","leggende":"Mostra come osservazioni fatte su lupi in cattività siano diventate una leggenda sul comando.","lupo alfa":"L'articolo smentisce il modello del lupo alfa che domina il branco."},"organizzazioni":[],"prova":"osservazione sul campo","sinossi":"L. David Mech, il biologo che con un suo libro del 1970 aveva contribuito a rendere popolare il termine lupo alfa, riesamina le osservazioni su cui si basava questa idea. L'immagine di un branco in cui gli individui lottano di continuo per il rango, tenuti a bada da una coppia alfa, nasceva soprattutto da lupi estranei messi insieme in cattività. Mech descrive invece l'ordine sociale del branco come si presenta in natura, sulla base della letteratura e di tredici estati di osservazioni sui lupi dell'isola di Ellesmere, nell'Artico canadese. Il branco tipico è una famiglia: una coppia di genitori e i loro figli di uno o più anni, e i genitori guidano le attività perché sono i genitori. Le lotte per il rango sono rare, e la divisione del lavoro segue i ruoli familiari: la femmina prevale nella cura e nella difesa dei piccoli, il maschio nella caccia, nel rifornimento di cibo e negli spostamenti legati a queste attività. Mech chiede di abbandonare il termine alfa per i lupi selvatici. Lo studio si basa su poche famiglie in un ambiente estremo, ma i suoi risultati sono stati confermati da ricerche successive.","tipo":"articolo","titolo":"Alpha status, dominance, and division of labor in wolf packs","url":"https://doi.org/10.1139/z99-099","id":"mech"},{"anno":2022,"area":"nat","autori":"Francesco Meneguzzo, Federica Zabini (a cura di)","autoriIds":["francesco-meneguzzo","federica-zabini"],"collegamenti":["li-2010-forest-bathing"],"concetti":["immersione nel bosco","recupero"],"contesto":["foreste"],"creata":"2026-11-04","doi":"","etichetta":"Meneguzzo e Zabini","evidenza":"","fonte":"CNR Edizioni, Roma, 2022","inAzienda":"Chi propone giornate di benessere in natura a un'azienda trova qui criteri italiani per scegliere i luoghi, garantire la sicurezza e misurare gli effetti. Questo permette di presentare l'attività con dati e non solo con promesse.","leve":["rig"],"macro":"ben","microtemi":["terapia forestale","immersione nel bosco","odori e fitoncidi","recupero dallo stress"],"motivi":{},"organizzazioni":["Consiglio Nazionale delle Ricerche","Club Alpino Italiano"],"prova":"rassegna","sinossi":"Il secondo volume sulla terapia forestale, curato dal Consiglio Nazionale delle Ricerche insieme al Club Alpino Italiano, raccoglie gli studi internazionali e i risultati delle sperimentazioni condotte in Italia. Riporta una riduzione dello stress, con prove più solide negli adulti sani, e benefici su ansia, umore e sonno. Discute anche quanto contino la composizione del bosco, la stagione e la concentrazione delle sostanze volatili emesse dagli alberi, e propone criteri per riconoscere le stazioni adatte alla terapia forestale. È la fonte italiana più completa sull'argomento, scritta da chi conduce le sperimentazioni.","tipo":"rapporto","titolo":"Terapia forestale 2","url":"https://www.cnr.it/sites/default/files/public/media/attivita/editoria/TF_2_el_ed.pdf","id":"meneguzzo-2022-terapia"},{"anno":2023,"area":"nat","autori":"Suzanne W. Simard, Justine Karst","autoriIds":["suzanne-w-simard","justine-karst"],"collegamenti":["seeley"],"concetti":["reti fra piante e funghi","reciprocità"],"contesto":["foreste","piante"],"creata":"2026-11-04","etichetta":"Reti micorriziche","evidenza":"didattica","fonte":"S. Simard, Finding the Mother Tree, Knopf, 2021; J. Karst e colleghi, Nature Ecology & Evolution, 7, 2023","inAzienda":"L'immagine della rete sotterranea che scambia risorse fra gli alberi è efficace in aula, ma la ricerca recente ne ha ridimensionato le versioni più diffuse. Va quindi usata dichiarando che cosa è dimostrato e che cosa no.","leve":["car","rel"],"macro":"com","microtemi":["reti micorriziche","alberi madre","condivisione delle risorse","evidenze contestate","simbiosi"],"organizzazioni":[],"prova":"rassegna","sinossi":"Le micorrize sono associazioni fra funghi e radici delle piante, documentate da tempo: il fungo aiuta la pianta ad assorbire acqua e nutrienti e riceve in cambio zuccheri. Suzanne Simard, ecologa forestale canadese, racconta nel libro le sue ricerche sulle reti di funghi che collegherebbero gli alberi di un bosco, e propone l'idea degli alberi madre che nutrono i giovani e comunicano con loro. Nel 2023 Justine Karst e colleghi hanno riesaminato le prove sul campo e concluso che tre affermazioni molto diffuse non sono sostenute in modo solido: che le reti siano estese e comuni nelle foreste, che trasferiscano risorse in quantità importanti fra alberi, che gli alberi adulti favoriscano i giovani attraverso le reti. La scheda tiene insieme i due lavori per mostrare dove la divulgazione è andata oltre la scienza.","tipo":"libro","titolo":"Finding the Mother Tree","url":"https://www.penguinrandomhouse.com/books/602589/finding-the-mother-tree-by-suzanne-simard/9780525565994","id":"micorrize"},{"anno":1979,"area":"evo","autori":"Henry Mintzberg","autoriIds":["henry-mintzberg"],"collegamenti":["lawrence-lorsch","simon"],"concetti":["contingenza","lavoro di squadra"],"contesto":["imprese"],"creata":"2026-11-04","etichetta":"Mintzberg","evidenza":"","fonte":"The Structuring of Organizations, Prentice Hall, 1979","inAzienda":"Ogni struttura organizzativa funziona bene in certi ambienti e male in altri. Riconoscere quale configurazione ha un'azienda aiuta a capire perché alcuni interventi non danno risultati e quali meccanismi di coordinamento conviene rafforzare.","leve":["gui","car"],"macro":"tra","microtemi":["struttura organizzativa","coordinamento","adattamento reciproco","standardizzazione","configurazioni"],"organizzazioni":[],"prova":"teoria","sinossi":"Henry Mintzberg riordina la letteratura sulla struttura delle organizzazioni intorno a una domanda: come si coordinano le persone che si dividono il lavoro. Individua pochi meccanismi di coordinamento: l'adattamento reciproco fra colleghi, la supervisione diretta di un capo, la standardizzazione dei processi, dei risultati o delle competenze. Combinando questi meccanismi con le diverse parti dell'organizzazione e con l'ambiente, descrive alcune configurazioni tipiche, fra cui la struttura semplice, la burocrazia meccanica, la burocrazia professionale, la forma divisionale e l'adhocrazia. Ogni configurazione funziona in certi ambienti e fallisce in altri. Il libro è diventato un manuale di base per chi progetta organizzazioni.","tipo":"libro","titolo":"The Structuring of Organizations","url":"https://openlibrary.org/works/OL1837472W","id":"mintzberg"},{"anno":1986,"area":"evo","autori":"Gareth Morgan","autoriIds":["gareth-morgan"],"collegamenti":["katz-kahn","weick"],"concetti":["sistemi sociotecnici","autopoiesi","cultura organizzativa","varietà necessaria"],"contesto":["imprese"],"creata":"2026-11-04","etichetta":"Morgan","evidenza":"","fonte":"Images of Organization, Sage, 1986","inAzienda":"Ogni modo di descrivere un'organizzazione, come macchina, organismo o sistema politico, mette in luce alcuni aspetti e ne nasconde altri. Usare più descrizioni insieme evita di applicare a tutti i problemi la stessa soluzione.","leve":["app","cul"],"macro":"cul","microtemi":["metafore","organismo","cultura","complessità","lettura delle organizzazioni"],"organizzazioni":[],"prova":"teoria","sinossi":"Gareth Morgan propone di leggere le organizzazioni attraverso metafore diverse, perché ogni teoria dell'organizzazione ne usa una, spesso senza dirlo. Le principali sono otto: l'organizzazione come macchina, come organismo, come cervello, come cultura, come sistema politico, come prigione psichica, come flusso in trasformazione e come strumento di dominio. Ogni metafora illumina alcuni aspetti e ne nasconde altri: chi vede solo la macchina non vede la cultura, chi vede solo il conflitto politico non vede l'apprendimento. Morgan invita a usare più metafore insieme per leggere un caso. Il libro è un classico della formazione manageriale.","tipo":"libro","titolo":"Images of Organization","url":"https://collegepublishing.sagepub.com/products/images-of-organization-1-229704","id":"morgan"},{"anno":2000,"area":"soc","autori":"Elizabeth W. Morrison e Frances J. Milliken","autoriIds":["elizabeth-w-morrison","frances-j-milliken"],"collegamenti":["hirschman","edmondson","detert-burris"],"concetti":["silenzio organizzativo","voce"],"contesto":["imprese"],"creata":"2026-11-04","doi":"10.2307/259200","etichetta":"Morrison e Milliken","evidenza":"","fonte":"«Organizational silence», Academy of Management Review, 25(4), 2000","inAzienda":"Quando le informazioni non arrivano a chi decide, l'azienda perde idee utili e segnali di rischio. Il silenzio nasce spesso dalle convinzioni dei dirigenti, per esempio che il disaccordo sia dannoso, e per questo va affrontato lavorando con loro prima che con i collaboratori.","leve":["rel","gui"],"macro":"com","microtemi":["silenzio organizzativo","voce","clima","convinzioni manageriali","informazione che non risale"],"motivi":{"clima":"Gli autori descrivono il clima di silenzio che si forma quando le persone si convincono che parlare sia inutile o pericoloso.","convinzioni manageriali":"Il silenzio nasce da convinzioni implicite dei dirigenti, come l'idea che i dipendenti pensino solo al proprio interesse.","informazione che non risale":"Il silenzio impedisce alle informazioni su problemi e opportunità di arrivare a chi deve decidere.","silenzio organizzativo":"L'articolo introduce il concetto di silenzio organizzativo.","voce":"Il silenzio organizzativo è l'opposto collettivo della voce: le persone sanno ma non parlano."},"organizzazioni":[],"prova":"teoria","sinossi":"Morrison e Milliken propongono che il silenzio possa diventare una proprietà dell'intera organizzazione: un clima in cui le persone pensano che parlare sia inutile o pericoloso. Il silenzio nasce da convinzioni implicite dei vertici, per esempio che i dipendenti badino solo al proprio interesse, che il management sappia meglio e che il dissenso vada evitato. Queste convinzioni si traducono in strutture e pratiche che scoraggiano la voce, e le persone ne ricavano insieme che è meglio tacere. Le conseguenze sono decisioni peggiori, errori scoperti tardi e persone che si ritirano dal lavoro. È un articolo teorico, poi messo alla prova da molti studi.","tipo":"articolo","titolo":"Organizational silence","url":"https://doi.org/10.2307/259200","id":"morrison-milliken"},{"anno":1976,"area":"soc","autori":"Serge Moscovici","autoriIds":["serge-moscovici"],"collegamenti":["asch","janis","kawai"],"concetti":["influenza minoritaria","cultura organizzativa","diffusione delle innovazioni","conformità"],"contesto":["laboratorio"],"creata":"2026-11-04","etichetta":"Moscovici","evidenza":"","fonte":"Social Influence and Social Change, Academic Press, 1976","inAzienda":"Le idee nuove nascono spesso da una minoranza, e se vengono subito messe ai voti vengono respinte. Proteggere per un tempo una minoranza coerente e costante le dà la possibilità di convincere il resto del gruppo.","leve":["rel","app"],"macro":"com","microtemi":["influenza minoritaria","coerenza","innovazione","conversione","dissenso"],"organizzazioni":[],"prova":"esperimento di laboratorio","sinossi":"Serge Moscovici, psicologo sociale francese, ribalta la domanda degli studi sulla conformità: invece di chiedersi come la maggioranza pieghi l'individuo, si chiede come una minoranza possa cambiare la maggioranza. Nei suoi esperimenti piccoli gruppi giudicavano il colore di diapositive blu; quando due complici dicevano ogni volta verde, una parte dei partecipanti cominciava a vedere il verde, anche nei giudizi privati successivi. L'effetto si produceva solo se la minoranza era coerente e costante. Per Moscovici la maggioranza ottiene un'adesione esteriore, mentre la minoranza coerente produce una conversione più profonda, perché costringe gli altri a riflettere. Il libro ha aperto il filone dell'influenza minoritaria e ha dato una base all'idea che il dissenso faccia bene ai gruppi.","tipo":"libro","titolo":"Social Influence and Social Change","url":"https://openlibrary.org/works/OL1710979W","id":"moscovici"},{"anno":2015,"area":"evo","autori":"Sharda S. Nandram","autoriIds":["sharda-s-nandram"],"collegamenti":["lee-2017-selfmanaging","pearce-conger","deci-ryan"],"composto":false,"concetti":["decentralizzazione","guida distribuita","autonomia","lavoro di squadra","coordinamento senza centro"],"contesto":["sanità","assistenza domiciliare"],"creata":"2026-11-05","doi":"10.1007/978-3-319-11725-6","esito":"Crescita rapida dell'organizzazione e riconoscimento internazionale; il libro descrive i principi ma non offre misure comparative di costo o di esito, e il caso è letto in modo favorevole.","etichetta":"Nandram","evidenza":"","fonte":"Springer, Cham, 2015, collana Management for Professionals","inAzienda":"Semplificare significa togliere i passaggi che non servono al cliente e lasciare ai team le decisioni che riguardano il loro lavoro, con un centro che sostiene invece di controllare.","intervento":"Creazione di piccoli team autonomi di infermieri responsabili dei propri pazienti e della propria organizzazione, con un centro leggero e strumenti informatici semplici.","leve":["gui","car"],"macro":"lea","microtemi":["decentralizzazione","guida distribuita","autonomia","team","coordinamento senza capo"],"motivi":{"autonomia":"L'autonomia dei team è il principio organizzativo principale.","coordinamento senza capo":"I team si coordinano senza una gerarchia intermedia.","decentralizzazione":"Le decisioni operative sono affidate ai team di infermieri.","guida distribuita":"La guida è distribuita nei team con un centro leggero.","team":"L'unità organizzativa di base è il piccolo team."},"organizzazioni":["Buurtzorg Nederland"],"problema":"L'assistenza domiciliare era frammentata in prestazioni separate, con molta burocrazia e poco tempo per il rapporto con il paziente.","prova":"caso studio","settore":"Assistenza sanitaria domiciliare (Paesi Bassi)","sinossi":"Il libro studia Buurtzorg Nederland, l'organizzazione olandese di assistenza domiciliare fondata nel 2006 e diventata un riferimento internazionale per l'autogestione. Nandram, docente alla Nyenrode Business University, analizza il caso con la metodologia della teoria fondata sui dati, costruendo la teoria a partire da ciò che emerge dal caso. Il cuore dell'organizzazione sono piccoli team di infermieri che gestiscono in autonomia i propri pazienti, il lavoro e l'organizzazione interna, con un centro leggero e un supporto informatico semplice. Dal caso l'autrice ricava una teoria che chiama semplificazione integrante: togliere ciò che non serve al lavoro con il cliente e integrare ciò che serve, invece di aggiungere controlli. Capitoli dedicati descrivono la sintonia con i pazienti e la libertà imprenditoriale dei team. L'autrice sostiene che il principio può essere applicato in altri settori adattandolo al contesto. È il primo libro internazionale su Buurtzorg, ma si basa su un solo caso visto in modo favorevole, senza un confronto sistematico con altre organizzazioni dell'assistenza.","tipo":"caso","titolo":"Organizational Innovation by Integrating Simplification: Learning from Buurtzorg Nederland","url":"https://doi.org/10.1007/978-3-319-11725-6","id":"nandram-2015-buurtzorg"},{"anno":2014,"area":"nat","autori":"Marlon Nieuwenhuis, Craig Knight, Tom Postmes, S. Alexander Haslam","autoriIds":["marlon-nieuwenhuis","craig-knight","tom-postmes","s-alexander-haslam"],"collegamenti":["bringslimark-2009-plants","browning-2014-patterns","kaplan"],"concetti":["piante negli uffici","design biofilico","carico di lavoro","benessere organizzativo"],"contesto":["uffici"],"creata":"2026-11-05","doi":"10.1037/xap0000024","etichetta":"Nieuwenhuis et al.","evidenza":"diretta","fonte":"Journal of Experimental Psychology: Applied, 20(3), 199-214, 2014","inAzienda":"Portare piante negli uffici costa poco e, in esperimenti reali, migliora concentrazione, soddisfazione e produttività rispetto agli spazi spogli.","leve":["rig"],"macro":"ben","microtemi":["piante indoor","spazi di lavoro","design biofilico","produttività","benessere"],"motivi":{"benessere":"Rileva soddisfazione e qualità dell'aria percepita.","design biofilico":"Mette alla prova l'aggiunta di elementi naturali allo spazio di lavoro.","piante indoor":"Confronta uffici con e senza piante.","produttività":"Misura anche la produttività con indicatori oggettivi.","spazi di lavoro":"Gli esperimenti si svolgono in veri uffici commerciali."},"organizzazioni":[],"prova":"esperimento di campo","sinossi":"La gestione snella degli uffici chiede spazi spogli, senza decorazioni, per poterli adattare a numeri di persone e funzioni che cambiano. Gli autori mettono alla prova questa idea contro quella opposta, che arricchisce gli uffici con piante senza alcuna funzione lavorativa. Conducono tre esperimenti sul campo in grandi uffici commerciali nei Paesi Bassi e nel Regno Unito, confrontando ambienti spogli e ambienti con piante. Misurano la qualità dell'aria percepita, la concentrazione, la soddisfazione per il luogo di lavoro e, con misure oggettive, la produttività. Due studi sono longitudinali e seguono gli effetti per settimane e mesi. In tutti e tre gli esperimenti gli esiti migliorano negli uffici con le piante. Gli autori leggono il risultato anche come effetto del coinvolgimento e del sentirsi curati dall'organizzazione, non solo delle piante in sé, e i campioni dei singoli esperimenti sono piccoli.","tipo":"articolo","titolo":"The relative benefits of green versus lean office space: Three field experiments","url":"https://doi.org/10.1037/xap0000024","id":"nieuwenhuis-2014-green"},{"anno":2023,"area":"evo","autori":"Shakked Noy, Whitney Zhang","autoriIds":["shakked-noy","whitney-zhang"],"collegamenti":["brynjolfsson-2025-generative"],"concetti":["intelligenza artificiale","trasformazione digitale","carico di lavoro","diffusione delle innovazioni"],"contesto":["servizi professionali"],"creata":"2026-11-05","doi":"10.1126/science.adh2586","etichetta":"Noy","evidenza":"","fonte":"Science, 381(6654), 187-192, 2023","inAzienda":"Una parte del tempo dedicato a mail, relazioni e testi standard può essere liberata in fretta, ma l'organizzazione deve decidere in anticipo come reinvestirlo.","leve":["car"],"macro":"tra","microtemi":["intelligenza artificiale","automazione","produttività","carico di lavoro","adozione"],"motivi":{"adozione":"Chi ha provato lo strumento tende a usarlo anche nel lavoro reale.","automazione":"Una parte del lavoro di scrittura viene svolta dallo strumento.","carico di lavoro":"Riguarda compiti ripetitivi che pesano sul carico quotidiano.","intelligenza artificiale":"Misura l'effetto di un assistente generativo su compiti di scrittura professionale.","produttività":"Tempo ridotto e qualità aumentata sono i risultati principali."},"organizzazioni":[],"prova":"esperimento di laboratorio","sinossi":"Noy e Zhang si chiedono quanto un assistente come ChatGPT cambi la produttività nei compiti di scrittura professionale di livello intermedio. In un esperimento online preregistrato assegnano a 453 professionisti laureati compiti di scrittura legati al loro mestiere e pagati in base alla qualità, e a metà di loro danno accesso allo strumento. Il tempo medio per completare il compito scende del 40 per cento e la qualità valutata sale del 18 per cento. Le differenze fra i partecipanti si riducono, perché chi partiva più indietro guadagna di più. Due settimane dopo chi aveva usato lo strumento nell'esperimento lo usava nel lavoro reale con una probabilità doppia, e la differenza restava due mesi dopo. Lo studio è stato fra i primi a misurare in modo controllato l'effetto dell'intelligenza artificiale generativa sul lavoro d'ufficio. I compiti sono brevi e isolati, svolti online e non dentro un'organizzazione, e non dicono che cosa succede quando lo strumento entra nei processi e nelle relazioni.","tipo":"articolo","titolo":"Experimental evidence on the productivity effects of generative artificial intelligence","url":"https://doi.org/10.1126/science.adh2586","id":"noy-2023-experimental"},{"anno":2003,"area":"lav","autori":"Shaul Oreg","autoriIds":["shaul-oreg"],"collegamenti":["coch-french","lewin","kegan-lahey"],"concetti":["resistenza al cambiamento","cambiamento personale","apprendimento organizzativo","misura della cultura","partecipazione"],"contesto":["lavoro"],"creata":"2026-11-05","doi":"10.1037/0021-9010.88.4.680","etichetta":"Oreg","evidenza":"","fonte":"Journal of Applied Psychology, 88(4), 680-693, 2003","inAzienda":"Prima di attribuire la resistenza alle persone conviene chiedersi quanto del cambiamento è stato imposto, perché la reazione emotiva all'imposizione è una delle componenti principali.","leve":["app","rel"],"macro":"cam","microtemi":["resistenza al cambiamento","cambiamento personale","routine","misura","partecipazione"],"motivi":{"cambiamento personale":"Descrive le differenze fra persone nel modo di reagire al cambiamento.","misura":"Il contributo principale è una scala validata.","partecipazione":"La reazione al cambiamento imposto richiama il valore della partecipazione.","resistenza al cambiamento":"Misura la resistenza come disposizione individuale.","routine":"La ricerca della routine è una delle quattro componenti."},"organizzazioni":[],"prova":"strumento di misura","sinossi":"Oreg si chiede se la resistenza al cambiamento dipenda solo dalla situazione o anche da una disposizione stabile della persona. Costruisce una scala, la Resistance to Change Scale, e la verifica in sette studi successivi. Le analisi fanno emergere quattro componenti: la ricerca della routine, la reazione emotiva al cambiamento imposto, la rigidità cognitiva e lo sguardo rivolto al breve periodo. Gli studi di conferma ripetono questa struttura e mostrano che la scala si distingue da misure vicine. Altri studi, in tre contesti diversi, mostrano che la scala prevede le reazioni delle persone a cambiamenti concreti. Il lavoro ha dato alla ricerca un modo per separare la parte individuale della resistenza da quella prodotta dal modo in cui il cambiamento viene gestito. Le misure sono autodichiarate e la disposizione spiega solo una parte delle reazioni, per cui la scala non va usata per etichettare le persone.","tipo":"articolo","titolo":"Resistance to change: Developing an individual differences measure","url":"https://doi.org/10.1037/0021-9010.88.4.680","id":"oreg-2003-resistance"},{"anno":1991,"area":"evo","autori":"Charles A. O'Reilly, Jennifer Chatman, David F. Caldwell","autoriIds":["charles-a-o-reilly","jennifer-chatman","david-f-caldwell"],"collegamenti":["schein","cameron-quinn"],"concetti":["cultura organizzativa","misura della cultura","appartenenza"],"contesto":["imprese"],"creata":"2026-11-05","doi":"10.2307/256404","etichetta":"O'Reilly et al.","evidenza":"","fonte":"Academy of Management Journal, 34(3), 487-516, 1991","inAzienda":"La distanza fra i valori che le persone cercano e quelli che vivono in azienda si misura, e anticipa soddisfazione e dimissioni.","leve":["rel","app"],"macro":"cul","microtemi":["cultura organizzativa","misura della cultura","valori","turnover","appartenenza"],"motivi":{"appartenenza":"La corrispondenza prevede anche l'impegno verso l'organizzazione.","cultura organizzativa":"Propone uno strumento quantitativo per descrivere la cultura.","misura della cultura":"L'Organizational Culture Profile è uno dei principali strumenti di misura.","turnover":"La corrispondenza fra persona e cultura prevede le dimissioni dopo due anni.","valori":"Lo strumento si basa sull'ordinamento di affermazioni sui valori."},"organizzazioni":[],"prova":"strumento di misura","sinossi":"Charles O'Reilly, dell'Università della California a Berkeley, Jennifer Chatman, della Northwestern University, e David Caldwell, della Santa Clara University, vogliono misurare in modo quantitativo la cultura di un'organizzazione e la sua corrispondenza con le preferenze delle persone. Costruiscono l'Organizational Culture Profile, uno strumento in cui le persone ordinano una serie di affermazioni sui valori secondo quanto descrivono l'organizzazione o ciò che desiderano. Usano dati longitudinali su contabili e studenti di un master in gestione d'impresa e dati trasversali su dipendenti di amministrazioni pubbliche e di società di revisione. Le dimensioni delle preferenze individuali e delle culture risultano interpretabili e confrontabili. La corrispondenza fra persona e organizzazione prevede la soddisfazione e l'impegno un anno dopo e le dimissioni effettive dopo due anni. Lo strumento è diventato uno dei più usati nella misura della cultura e ha dato concretezza all'idea che la cultura riguardi valori condivisi. Misura i valori dichiarati più che gli assunti profondi, e i campioni appartengono a pochi settori professionali.","tipo":"articolo","titolo":"People and Organizational Culture: A Profile Comparison Approach to Assessing Person-Organization Fit","url":"https://doi.org/10.2307/256404","id":"oreilly-1991-culture"},{"anno":1990,"area":"cam","autori":"Elinor Ostrom","autoriIds":["elinor-ostrom"],"collegamenti":["gordon","bienefeld-grote","wilkinson"],"concetti":["beni comuni","decentralizzazione","sicurezza psicologica"],"contesto":["beni comuni"],"creata":"2026-11-04","doi":"10.1017/CBO9780511807763","etichetta":"Ostrom","evidenza":"","fonte":"Governing the Commons, Cambridge University Press, 1990","inAzienda":"Le risorse condivise fra reparti, come sale, persone e budget comuni, si gestiscono bene se chi le usa partecipa alla definizione delle regole e qualcuno ne controlla il rispetto. È un modello di decentralizzazione che funziona perché ha regole chiare, non perché ne è privo.","leve":["gui","car"],"macro":"lea","microtemi":["beni comuni","autogoverno","regole condivise","monitoraggio","decentralizzazione","fiducia"],"organizzazioni":[],"prova":"caso studio","sinossi":"Elinor Ostrom, economista e politologa, studia come le comunità gestiscono risorse comuni come pascoli, foreste, zone di pesca e sistemi di irrigazione. La teoria dominante prevedeva due sole soluzioni per evitarne l'esaurimento: l'autorità dello Stato o la proprietà privata. Ostrom documenta casi, alcuni durati secoli, in cui gli utenti stessi hanno costruito regole efficaci, dai pascoli alpini svizzeri ai sistemi di irrigazione in Spagna e nelle Filippine. Ne ricava otto principi che accomunano i casi riusciti, fra cui confini chiari, regole adatte alle condizioni locali, partecipazione di chi usa la risorsa alle decisioni, controllo reciproco e sanzioni graduali. Per questi studi ha ricevuto nel 2009 il premio Nobel per l'economia, prima donna a ottenerlo.","tipo":"libro","titolo":"Governing the Commons","url":"https://doi.org/10.1017/CBO9780511807763","id":"ostrom"},{"anno":2003,"area":"lea","autori":"Craig L. Pearce e Jay A. Conger (a cura di)","autoriIds":["craig-l-pearce","jay-a-conger"],"collegamenti":["bienefeld-grote","bass"],"concetti":["guida distribuita","lavoro di squadra","decentralizzazione","autonomia"],"contesto":["imprese"],"creata":"2026-11-04","doi":"10.4135/9781452229539","etichetta":"Pearce e Conger","evidenza":"","fonte":"Shared Leadership, Sage, 2003","inAzienda":"La guida può essere condivisa fra più membri di un gruppo a seconda del compito e delle competenze, con risultati migliori in molti contesti. Funziona però solo dentro confini chiari, che dicano chi risponde della decisione finale.","leve":["gui"],"macro":"lea","microtemi":["leadership condivisa","guida distribuita","team","delega","autonomia"],"organizzazioni":[],"prova":"rassegna","sinossi":"Craig Pearce e Jay Conger raccolgono in questo volume i contributi dei principali studiosi della leadership condivisa. L'idea è che la guida non debba per forza essere esercitata da una persona sola: in un team può passare da un membro all'altro a seconda del compito e delle competenze, e più persone possono influenzarsi a vicenda verso gli obiettivi comuni. Il libro ricostruisce le radici storiche dell'idea, propone modelli e discute quando la condivisione aiuta e quando confonde. Le ricerche successive, comprese alcune meta-analisi, hanno trovato un legame positivo fra guida condivisa e prestazioni dei team. Il limite è che il concetto viene misurato in modi molto diversi da uno studio all'altro.","tipo":"libro","titolo":"Shared Leadership","url":"https://doi.org/10.4135/9781452229539","id":"pearce-conger"},{"anno":1983,"area":"soc","autori":"James O. Prochaska, Carlo C. DiClemente","autoriIds":["james-o-prochaska","carlo-c-diclemente"],"collegamenti":["kegan-lahey","bandura","lewin"],"concetti":["cambiamento personale","appartenenza"],"contesto":["clinica"],"creata":"2026-11-05","doi":"10.1037/0022-006x.51.3.390","etichetta":"Prochaska","evidenza":"","fonte":"Journal of Consulting and Clinical Psychology, 51(3), 390-395, 1983","inAzienda":"Nei percorsi di sviluppo e di cambiamento conviene distinguere chi è pronto ad agire da chi deve ancora prendere coscienza, invece di dare a tutti lo stesso piano.","leve":["app","rig"],"macro":"cam","microtemi":["cambiamento personale","cambiamento di comportamento","stadi del cambiamento","ricaduta","relazione"],"motivi":{"cambiamento di comportamento":"Il comportamento studiato è smettere di fumare.","cambiamento personale":"Descrive come le persone cambiano da sole un'abitudine radicata.","relazione":"Nella fase di azione conta una relazione di aiuto.","ricaduta":"La ricaduta è trattata come uno stadio del percorso e non come un fallimento definitivo.","stadi del cambiamento":"Introduce la sequenza di stadi che dà nome al modello."},"organizzazioni":[],"prova":"studio longitudinale","sinossi":"Prochaska e DiClemente studiano come cambiano da sole le persone che cercano di smettere di fumare senza un trattamento. Coinvolgono 872 persone che si trovano in cinque stadi diversi: la precontemplazione, in cui non si pensa ancora di cambiare, la contemplazione, l'azione, il mantenimento e la ricaduta. Verificano se i dieci processi di cambiamento che avevano descritto, come prendere coscienza del problema, rivalutare se stessi o controllare gli stimoli, vengano usati in modo diverso nei vari stadi. Nella precontemplazione si usano pochissimi processi, nella contemplazione prevale la presa di coscienza, nell'azione contano l'impegno personale, una relazione di aiuto e la gestione dei rinforzi, mentre nel mantenimento servono soprattutto il controllo degli stimoli e la sostituzione dei comportamenti. Da questo lavoro nasce il modello transteorico del cambiamento, poi usato in molti campi della salute e del lavoro. L'idea centrale è che un intervento funziona quando è adatto allo stadio in cui la persona si trova. Lo studio riguarda un comportamento di salute, ha un disegno trasversale, e la validità degli stadi come categorie distinte è stata in seguito discussa.","tipo":"articolo","titolo":"Stages and processes of self-change of smoking: Toward an integrative model of change","url":"https://doi.org/10.1037/0022-006x.51.3.390","id":"prochaska-1983-stages"},{"anno":1962,"area":"cam","autori":"Everett M. Rogers","autoriIds":["everett-m-rogers"],"collegamenti":["kawai","moscovici"],"concetti":["diffusione delle innovazioni","comunicazione"],"contesto":["agricoltura","imprese"],"creata":"2026-11-04","etichetta":"E. Rogers","evidenza":"","fonte":"Diffusion of Innovations, Free Press, 1962","inAzienda":"Un cambiamento si diffonde attraverso le persone che i colleghi stimano e ascoltano, non attraverso gli annunci ufficiali. Individuare queste persone e coinvolgerle per prime accelera l'adozione di un nuovo modo di lavorare.","leve":["rel","app"],"macro":"cam","microtemi":["diffusione delle innovazioni","primi adottanti","reti di relazioni","opinion leader","adozione"],"organizzazioni":[],"prova":"teoria","sinossi":"Rogers riunisce centinaia di studi sulla diffusione di nuove pratiche, a partire da quelli sul mais ibrido fra gli agricoltori dello Iowa. Un'innovazione si diffonde nel tempo lungo i canali di comunicazione di un sistema sociale, seguendo una curva a S. Chi adotta si distribuisce in innovatori, primi adottanti, maggioranza anticipata, maggioranza tardiva e ritardatari, e i leader d'opinione hanno un peso decisivo. Cinque caratteristiche dell'innovazione ne spiegano la velocità: vantaggio, compatibilità, complessità, possibilità di provarla, visibilità dei risultati. Lo stesso Rogers ha riconosciuto un limite del filone: la tendenza a considerare ogni innovazione buona e chi non la adotta in ritardo.","tipo":"libro","titolo":"Diffusion of Innovations","url":"https://openlibrary.org/works/OL718011W","id":"rogers-e"},{"anno":1995,"area":"lav","autori":"Denise M. Rousseau","autoriIds":["denise-m-rousseau"],"collegamenti":["hirschman","schein"],"concetti":["contratto psicologico","sicurezza psicologica","appartenenza"],"contesto":["imprese"],"creata":"2026-11-04","etichetta":"Rousseau","evidenza":"","fonte":"Psychological Contracts in Organizations, Sage, 1995","inAzienda":"Ogni persona porta in azienda aspettative che nessuno ha messo per iscritto, sulla crescita, sulla stabilità o sul riconoscimento. Renderle esplicite al momento dell'assunzione e nei passaggi di ruolo previene delusioni e dimissioni.","leve":["rel"],"macro":"ind","microtemi":["contratto psicologico","aspettative","violazione","fiducia","turnover"],"organizzazioni":[],"prova":"teoria","sinossi":"Denise Rousseau descrive il contratto psicologico: l'insieme delle promesse che una persona crede di aver scambiato con la propria organizzazione, al di là del contratto scritto. Riguarda per esempio la crescita professionale, la stabilità, il riconoscimento, la flessibilità. Rousseau distingue i contratti transazionali, brevi e basati sullo scambio economico, da quelli relazionali, lunghi e basati su fiducia e lealtà. Quando la persona sente che una promessa è stata violata reagisce con delusione e rabbia, riduce l'impegno o se ne va, anche se dal punto di vista dell'azienda nessuna regola è stata infranta. Il libro ha dato basi solide a un filone di ricerca molto ampio su fiducia, impegno e turnover.","tipo":"libro","titolo":"Psychological Contracts in Organizations","url":"https://www.sagepub.com/shop/buy-a-book/psychological-contracts-in-organizations-1-5077","id":"rousseau"},{"anno":1985,"area":"evo","autori":"Edgar H. Schein","autoriIds":["edgar-h-schein"],"collegamenti":["argyris-schon","katz-kahn","cameron-quinn","lewin","rousseau"],"concetti":["cultura organizzativa","partecipazione"],"contesto":["imprese"],"creata":"2026-11-04","etichetta":"Schein","evidenza":"","fonte":"Organizational Culture and Leadership, Jossey-Bass, 1985; Humble Inquiry, Berrett-Koehler, 2013","inAzienda":"La cultura di un'azienda si cambia agendo su ciò a cui i dirigenti prestano attenzione, su ciò che premiano e su come reagiscono alle crisi, non scrivendo nuovi valori. Per questo i percorsi sulla cultura partono dall'osservazione dei comportamenti dei dirigenti.","leve":["rel","gui","cul"],"macro":"cul","microtemi":["cultura organizzativa","assunti di base","valori dichiarati","artefatti","indagine umile","consulenza di processo"],"organizzazioni":[],"prova":"teoria","sinossi":"Schein descrive la cultura di un gruppo come l'insieme degli assunti che il gruppo ha imparato risolvendo i propri problemi di adattamento all'esterno e di integrazione all'interno, e che col tempo dà per scontati. La divide in tre livelli: gli artefatti visibili, i valori dichiarati e gli assunti di base, che sono la parte decisiva e la più difficile da vedere. I fondatori e i leader creano e trasmettono la cultura con ciò a cui prestano attenzione, con le reazioni alle crisi, con i criteri di premi e promozioni. Il libro nasce dall'esperienza di consulente più che da misure quantitative. Schein ha poi sviluppato la consulenza di processo e l'indagine umile, cioè l'arte di fare domande senza presupporre la risposta.","tipo":"libro","titolo":"Organizational Culture and Leadership","url":"https://openlibrary.org/works/OL1906630W","id":"schein"},{"anno":2015,"area":"lav","autori":"Michaéla C. Schippers, Michael A. West, Jeremy F. Dawson","autoriIds":["michaela-c-schippers","michael-a-west","jeremy-f-dawson"],"collegamenti":["argyris-schon","senge","edmondson"],"concetti":["lavoro di squadra","diffusione delle innovazioni","carico di lavoro","retroazione"],"contesto":["imprese"],"creata":"2026-11-05","doi":"10.1177/0149206312441210","etichetta":"Schippers et al.","evidenza":"","fonte":"Journal of Management, 41(3), 769-788, 2015","inAzienda":"Nei periodi di carico alto conviene proteggere brevi momenti in cui il team riflette sul proprio modo di lavorare, perché lì nasce una parte dell'innovazione.","leve":["app","car"],"macro":"app","microtemi":["riflessività","apprendimento di team","innovazione","carico di lavoro","retroazione"],"motivi":{"apprendimento di team":"Riflettere insieme sul lavoro è una forma di apprendimento del gruppo.","carico di lavoro":"L'effetto della riflessività cresce quando le richieste di lavoro sono alte.","innovazione":"L'esito misurato è l'innovazione del team.","retroazione":"La riflessione funziona come un ciclo di retroazione sul proprio modo di lavorare.","riflessività":"La riflessività di team è la variabile principale dello studio."},"organizzazioni":[],"prova":"studio osservazionale","sinossi":"La riflessività di un team è la misura in cui i suoi membri riflettono insieme sul proprio modo di lavorare e lo adattano, e studi precedenti la legavano all'innovazione. Gli autori si chiedono se il suo effetto dipenda dal contesto in cui il team lavora. Studiano 98 team di assistenza sanitaria di base nel Regno Unito e misurano riflessività, richieste di lavoro, qualità dell'ambiente fisico e innovazione. La riflessività è legata positivamente all'innovazione del team. L'effetto è più forte quando le richieste di lavoro sono alte: i team riflessivi sotto pressione sono i più innovativi. Anche un ambiente fisico di cattiva qualità, unito a un'alta riflessività, si associa a più innovazione, come se la riflessione aiutasse a trasformare i disagi in miglioramenti. Lo studio è trasversale, in un solo settore, e non permette di stabilire la direzione causale.","tipo":"articolo","titolo":"Team Reflexivity and Innovation: The Moderating Role of Team Context","url":"https://doi.org/10.1177/0149206312441210","id":"schippers-2015-reflexivity"},{"anno":2010,"area":"nat","autori":"Thomas D. Seeley","autoriIds":["thomas-d-seeley"],"collegamenti":["bienefeld-grote","march","gordon"],"concetti":["decisione collettiva","guida distribuita"],"contesto":["api"],"creata":"2026-11-04","etichetta":"Seeley, sciame","evidenza":"funzionale","fonte":"Honeybee Democracy, Princeton University Press, 2010","inAzienda":"Per le decisioni rare e importanti conviene un processo lento, in cui le opzioni vengono valutate in modo indipendente e la scelta avviene solo al raggiungimento di un consenso sufficiente. Lo sciame mostra che questo processo produce scelte accurate anche senza un capo.","leve":["gui"],"macro":"lea","microtemi":["decisione collettiva","soglia di quorum","confronto fra opzioni","guida distribuita","decisioni rare"],"organizzazioni":[],"prova":"osservazione sul campo","sinossi":"Quando una colonia di api si divide, lo sciame di migliaia di individui deve scegliere in pochi giorni una nuova cavità in cui vivere, e una scelta sbagliata può costare la vita alla colonia. Seeley ricostruisce con anni di esperimenti come lo fanno poche centinaia di esploratrici: visitano i siti, li valutano in modo indipendente e li promuovono con danze tanto più lunghe quanto migliore è il sito. L'entusiasmo per ogni sito decade nel tempo e le esploratrici si ostacolano a vicenda con segnali di arresto, così i siti mediocri perdono sostegno. La scelta scatta quando sul sito si trova un numero sufficiente di esploratrici, una soglia di quorum, e lo sciame parte. Nell'ultima parte del libro Seeley ricava indicazioni per i gruppi umani: diversità di chi esplora, valutazioni indipendenti, confronto aperto, capo che non orienta.","tipo":"libro","titolo":"Honeybee Democracy","url":"https://press.princeton.edu/isbn/9780691147215","id":"seeley-nido"},{"anno":1995,"area":"nat","autori":"Thomas D. Seeley","autoriIds":["thomas-d-seeley"],"collegamenti":["wiener","gordon","micorrize"],"concetti":["regolazione distribuita","carico di lavoro","coordinamento senza centro"],"contesto":["api"],"creata":"2026-11-04","etichetta":"Seeley, alveare","evidenza":"formale","fonte":"The Wisdom of the Hive, Harvard University Press, 1995","inAzienda":"In un processo in cui una fase raccoglie lavoro e un'altra lo elabora, il tempo di attesa fra le due fasi è il segnale più utile per spostare le persone dove servono. Renderlo visibile permette di regolare il flusso senza che un responsabile debba decidere ogni spostamento.","leve":["car"],"macro":"lea","microtemi":["danza del tremito","flusso di lavoro","colli di bottiglia","regolazione","coordinamento senza capo"],"organizzazioni":[],"prova":"osservazione sul campo","sinossi":"Seeley studia l'alveare come un'unità che raccoglie e lavora il cibo senza un centro di comando. Con alveari di osservazione e api marcate una per una ricostruisce come migliaia di individui si distribuiscono fra raccolta e lavorazione del nettare. Le bottinatrici misurano quanto aspettano per scaricare: se l'attesa è breve reclutano altre raccoglitrici con la danza dell'addome, se è lunga fanno la danza del tremito, che porta più api alla lavorazione. Il tempo di attesa diventa così un segnale che regola il sistema senza che nessuno conti le scorte. Il libro è un classico dello studio dell'intelligenza collettiva.","tipo":"libro","titolo":"The Wisdom of the Hive","url":"https://www.hup.harvard.edu/books/9780674953765","id":"seeley"},{"anno":1990,"area":"evo","autori":"Peter M. Senge","autoriIds":["peter-m-senge"],"collegamenti":["meadows","argyris-schon"],"concetti":["apprendimento organizzativo","retroazione","lavoro di squadra"],"contesto":["imprese"],"creata":"2026-11-04","etichetta":"Senge","evidenza":"","fonte":"The Fifth Discipline, Doubleday, 1990","inAzienda":"Il linguaggio delle cinque discipline è già noto a molti dirigenti, e aiuta a introdurre il pensiero sistemico in azienda senza partire da zero. Gli archetipi sistemici aiutano a riconoscere i problemi che si ripetono.","leve":["app","rel"],"macro":"app","microtemi":["organizzazione che apprende","pensiero sistemico","modelli mentali","visione condivisa","apprendimento di gruppo"],"organizzazioni":[],"prova":"saggio","sinossi":"Peter Senge, del MIT, porta il pensiero sistemico nel linguaggio dei dirigenti. L'organizzazione che apprende poggia su cinque discipline: la padronanza personale, i modelli mentali, la visione condivisa, l'apprendimento di gruppo e il pensiero sistemico, che tiene insieme le altre. Senge descrive gli archetipi sistemici, schemi ricorrenti come la soluzione che si ritorce contro o i limiti alla crescita, e usa un gioco di simulazione sulla distribuzione della birra per mostrare come persone razionali producano insieme risultati disastrosi. Il libro ha avuto un successo enorme fra i manager. Le prove empiriche che l'organizzazione che apprende migliori i risultati sono però più deboli della sua fama.","tipo":"libro","titolo":"The Fifth Discipline","url":"https://www.penguinrandomhouse.com/books/163984/the-fifth-discipline-by-peter-m-senge/","id":"senge"},{"anno":1980,"area":"nat","autori":"Robert M. Seyfarth, Dorothy L. Cheney, Peter Marler","autoriIds":["robert-m-seyfarth","dorothy-l-cheney","peter-marler"],"collegamenti":["ballerini","weick"],"concetti":["comunicazione","coordinamento senza centro","regolazione distribuita","apprendimento organizzativo"],"contesto":["primati"],"creata":"2026-11-05","doi":"10.1126/science.7433999","etichetta":"Seyfarth et al.","evidenza":"funzionale","fonte":"Science, 210(4471), 801-803, 1980","inAzienda":"Un sistema di segnalazione funziona quando i segnali distinguono i tipi di problema e indicano già la risposta, e quando chi è nuovo viene aiutato a usarli bene.","leve":["rel","app"],"macro":"com","microtemi":["comunicazione","informazione","risposta rapida","segnali","apprendimento"],"motivi":{"apprendimento":"La classificazione dei predatori migliora con l'esperienza.","comunicazione":"È un classico della comunicazione animale con segnali specifici.","informazione":"Ogni richiamo trasmette un'informazione precisa sul tipo di predatore.","risposta rapida":"Il segnale giusto produce subito la risposta adatta.","segnali":"Lo studio riguarda il contenuto dei segnali d'allarme."},"organizzazioni":[],"prova":"esperimento di campo","sinossi":"Seyfarth, Cheney e Marler studiano i cercopitechi verdi del Kenya, scimmie che emettono richiami d'allarme diversi per predatori diversi. Per capire se i richiami contengano un'informazione specifica, registrano gli allarmi e li riproducono con un altoparlante quando nessun predatore è presente. Le scimmie rispondono in modo adatto al predatore indicato: corrono sugli alberi per l'allarme del leopardo, guardano in alto per quello dell'aquila e guardano in basso per quello del serpente. Gli adulti danno l'allarme soprattutto per leopardi, aquile marziali e pitoni, mentre i piccoli lo danno per molti mammiferi, uccelli e oggetti simili a serpenti. La capacità di classificare correttamente i predatori migliora con l'età e con l'esperienza. Lo studio è diventato il classico della comunicazione referenziale negli animali, cioè di segnali che indicano qualcosa nel mondo. La parola semantica va presa con cautela, perché non implica che le scimmie abbiano un linguaggio nel senso umano.","tipo":"articolo","titolo":"Monkey Responses to Three Different Alarm Calls: Evidence of Predator Classification and Semantic Communication","url":"https://doi.org/10.1126/science.7433999","id":"seyfarth-1980-alarm"},{"anno":1961,"area":"soc","autori":"Muzafer Sherif","autoriIds":["muzafer-sherif"],"collegamenti":["tajfel-turner"],"concetti":["conflitto fra gruppi","reciprocità","sistemi aperti"],"contesto":["gruppi giovanili"],"creata":"2026-11-04","etichetta":"Sherif","evidenza":"","fonte":"Intergroup Conflict and Cooperation: The Robbers Cave Experiment, University of Oklahoma, 1961","inAzienda":"Due reparti in conflitto tornano a collaborare quando hanno un obiettivo che nessuno dei due può raggiungere da solo. Il semplice contatto, come riunioni comuni o eventi aziendali, non basta e a volte peggiora le cose.","leve":["rel"],"macro":"ind","microtemi":["obiettivi sovraordinati","conflitto fra gruppi","competizione","cooperazione","interdipendenza"],"organizzazioni":[],"prova":"esperimento di campo","sinossi":"Muzafer Sherif e i suoi collaboratori organizzarono un campo estivo nel parco di Robbers Cave, in Oklahoma, con ragazzi di undici anni che non si conoscevano. Prima li divisero in due gruppi separati, che svilupparono ciascuno nomi, norme e capi propri. Poi li misero in competizione con gare e premi: in pochi giorni nacquero ostilità, insulti e incursioni. Il semplice contatto non bastò a riconciliarli; ci riuscirono invece obiettivi sovraordinati, problemi che nessun gruppo poteva risolvere da solo, come riparare la condotta dell'acqua o rimettere in moto un camion bloccato. Lo studio è un classico, ma è stato criticato per il ruolo attivo dei ricercatori nel provocare il conflitto.","tipo":"libro","titolo":"Intergroup Conflict and Cooperation: The Robbers Cave Experiment","url":"https://openlibrary.org/works/OL33164724W","id":"sherif"},{"anno":1947,"area":"lea","autori":"Herbert A. Simon","autoriIds":["herbert-a-simon"],"collegamenti":["march","ashby","mintzberg"],"concetti":["razionalità limitata","decisione collettiva","comunicazione","recupero dell'attenzione"],"contesto":["imprese","pubblica amministrazione"],"creata":"2026-11-04","etichetta":"Simon","evidenza":"","fonte":"Administrative Behavior, Macmillan, 1947","inAzienda":"L'attenzione di chi decide è limitata, e quando tutte le decisioni arrivano alla stessa persona la qualità delle scelte peggiora. Progettare le decisioni significa quindi portare le informazioni e la responsabilità dove le decisioni servono.","leve":["gui","rel"],"macro":"lea","microtemi":["razionalità limitata","decisione","informazione","attenzione","soddisfacimento"],"organizzazioni":[],"prova":"teoria","sinossi":"Herbert Simon studia come si prendono davvero le decisioni nelle organizzazioni. Chi decide non conosce tutte le alternative, non può prevederne tutte le conseguenze e ha poco tempo e poca attenzione: la sua razionalità è limitata. Per questo le persone non cercano la soluzione migliore possibile ma la prima abbastanza buona, un comportamento che Simon chiamerà poi soddisfacimento. L'organizzazione serve proprio a rendere gestibili le decisioni, dividendole in parti, fissando procedure e premesse e indirizzando l'attenzione. Per queste ricerche Simon ha ricevuto nel 1978 il premio Nobel per l'economia.","tipo":"libro","titolo":"Administrative Behavior","url":"https://openlibrary.org/works/OL1205037W","id":"simon"},{"anno":2007,"area":"lav","autori":"Sabine Sonnentag e Charlotte Fritz","autoriIds":["sabine-sonnentag","charlotte-fritz"],"collegamenti":["bakker-demerouti","kaplan"],"concetti":["recupero","autoefficacia","autonomia"],"contesto":["lavoro"],"creata":"2026-11-04","doi":"10.1037/1076-8998.12.3.204","etichetta":"Sonnentag e Fritz","evidenza":"","fonte":"«The Recovery Experience Questionnaire», Journal of Occupational Health Psychology, 12, 2007","inAzienda":"Il questionario sulle esperienze di recupero misura quanto le persone riescono a staccare dal lavoro nel tempo libero. Usarlo prima e dopo un intervento sui ritmi o sulle pause permette di verificare se il recupero è migliorato.","leve":["rig"],"macro":"ben","microtemi":["recupero","distacco psicologico","rilassamento","padronanza","controllo del tempo"],"motivi":{"controllo del tempo":"Decidere come usare il proprio tempo libero è la quarta delle esperienze di recupero misurate.","distacco psicologico":"Smettere di pensare al lavoro nel tempo libero è una delle quattro esperienze di recupero.","padronanza":"Le attività che mettono alla prova e fanno imparare qualcosa di nuovo sono una delle quattro esperienze di recupero.","recupero":"L'articolo presenta il questionario che misura le esperienze di recupero nel tempo libero.","rilassamento":"Il rilassamento, cioè uno stato di bassa attivazione fisica e mentale, è una delle quattro esperienze di recupero."},"organizzazioni":[],"prova":"strumento di misura","sinossi":"Sonnentag e Fritz partono dagli studi sulla regolazione dell'umore e sul recupero dallo stress lavorativo e si chiedono come misurare il modo in cui le persone si riprendono dal lavoro nel tempo libero. Nel primo studio costruiscono quattro misure brevi, ciascuna di quattro domande. Con analisi fattoriali su un campione di calibrazione e uno di verifica, per un totale di 930 persone, mostrano che si distinguono quattro esperienze di recupero: il distacco psicologico dal lavoro, il rilassamento, le esperienze di padronanza come imparare qualcosa di nuovo, e il controllo su come usare il proprio tempo. In un sottocampione di 271 persone le quattro esperienze risultano moderatamente legate ai fattori di stress del lavoro e al benessere psicologico. I legami con le strategie di fronteggiamento e con la personalità sono invece in genere bassi, il che mostra che il questionario misura qualcosa di distinto. Gli autori propongono di usare le quattro misure negli studi longitudinali e nei diari quotidiani, e il questionario è diventato lo strumento standard della ricerca sul recupero. Le misure sono autodichiarate e lo studio di validazione è trasversale.","tipo":"articolo","titolo":"The Recovery Experience Questionnaire","url":"https://doi.org/10.1037/1076-8998.12.3.204","id":"sonnentag-fritz"},{"anno":1979,"area":"soc","autori":"Henri Tajfel e John C. Turner","autoriIds":["henri-tajfel","john-c-turner"],"collegamenti":["sherif","moscovici"],"concetti":["conflitto fra gruppi","cambiamento organizzativo"],"contesto":["gruppi"],"creata":"2026-11-04","etichetta":"Tajfel e Turner","evidenza":"","fonte":"«An integrative theory of intergroup conflict», in W.G. Austin, S. Worchel (a cura di), The Social Psychology of Intergroup Relations, Brooks/Cole, 1979","inAzienda":"Quando le persone si identificano con il proprio reparto o con l'azienda di provenienza dopo una fusione, tendono a favorire il proprio gruppo e a diffidare dell'altro. Per superare questa divisione serve costruire un'identità comune senza cancellare quelle esistenti.","leve":["rel","cul"],"macro":"ind","microtemi":["identità sociale","noi e loro","favoritismo","conflitto fra gruppi","fusioni"],"organizzazioni":[],"prova":"teoria","sinossi":"Henri Tajfel e John Turner propongono la teoria dell'identità sociale per spiegare il conflitto fra gruppi. Il punto di partenza sono esperimenti sorprendenti, i gruppi minimi: persone divise in due gruppi con un criterio arbitrario, come la preferenza per un pittore, favorivano il proprio gruppo nella distribuzione di piccoli premi, anche senza conoscersi e senza alcun interesse personale. La spiegazione è che una parte della stima di sé viene dai gruppi a cui apparteniamo, e per questo cerchiamo di farli apparire migliori degli altri. Il conflitto non nasce quindi solo dalla competizione per risorse scarse, come nel campo di Sherif, ma anche dal bisogno di distinguersi. È una delle teorie più influenti della psicologia sociale.","tipo":"articolo","titolo":"An integrative theory of intergroup conflict","url":"https://openlibrary.org/works/OL19396369W","id":"tajfel-turner"},{"anno":2006,"area":"nat","autori":"Alex Thornton, Katherine McAuliffe","autoriIds":["alex-thornton","katherine-mcauliffe"],"collegamenti":["bandura","bauer-2007-newcomer"],"concetti":["apprendimento organizzativo","autoefficacia","appartenenza","stile di guida"],"contesto":["suricati"],"creata":"2026-11-05","doi":"10.1126/science.1128727","etichetta":"Thornton","evidenza":"funzionale","fonte":"Science, 313(5784), 227-229, 2006","inAzienda":"Chi insegna il mestiere può dosare la difficoltà dei compiti in base ai segnali di chi impara, togliendo protezioni man mano invece di lasciarlo solo o di sostituirsi a lui.","leve":["app","rel"],"macro":"app","microtemi":["apprendimento","esperienze di successo","onboarding","modellamento","sviluppo dei collaboratori"],"motivi":{"apprendimento":"Documenta l'insegnamento attivo in un animale selvatico.","esperienze di successo":"I piccoli ricevono compiti graduati che possono riuscire a svolgere.","modellamento":"Gli adulti modificano il proprio comportamento per favorire l'apprendimento.","onboarding":"È un'analogia per l'inserimento dei nuovi con compiti via via meno protetti.","sviluppo dei collaboratori":"Mostra come chi è esperto sostiene la crescita di chi impara."},"organizzazioni":[],"prova":"esperimento di campo","sinossi":"Insegnare, cioè modificare il proprio comportamento per far imparare un altro a un certo costo, era considerato quasi esclusivo della specie umana, e mancavano prove solide negli altri animali. Thornton e McAuliffe studiano i suricati selvatici del Kalahari, che si nutrono anche di prede pericolose come gli scorpioni. Con osservazioni ed esperimenti mostrano che gli adulti aiutanti offrono ai piccoli occasioni di maneggiare prede vive. Man mano che i piccoli crescono, gli aiutanti cambiano il modo di offrire le prede, passando da prede morte a prede rese inoffensive e poi a prede intatte, guidati dai richiami con cui i piccoli chiedono cibo. Questo accelera l'apprendimento senza bisogno di capacità cognitive complesse. Gli autori suggeriscono che l'insegnamento possa essere più diffuso di quanto si pensi e che manchino soprattutto i metodi per dimostrarlo. Il meccanismo è semplice e non implica che i suricati sappiano di insegnare.","tipo":"articolo","titolo":"Teaching in Wild Meerkats","url":"https://doi.org/10.1126/science.1128727","id":"thornton-2006-teaching"},{"anno":2016,"area":"evo","autori":"Catherine J. Turco","autoriIds":["catherine-j-turco"],"collegamenti":["detert-burris","morrison-milliken","hirschman"],"composto":false,"concetti":["voce","comunicazione","decentralizzazione"],"contesto":["tecnologia"],"creata":"2026-11-05","doi":"10.7312/turc17898","esito":"La conversazione aperta ha portato voce e apprendimento, ma le aspettative di partecipazione alle decisioni hanno generato tensioni dove l'autorità restava gerarchica.","etichetta":"Turco","evidenza":"","fonte":"Columbia University Press, New York, 2016","inAzienda":"Un'azienda può rendere la comunicazione molto aperta mantenendo decisioni centrali, ma deve dire con chiarezza dove finisce la consultazione e dove comincia la decisione.","intervento":"Apertura dei flussi di informazione e dei canali di discussione interna a tutti i dipendenti, con incontri plenari e domande dirette ai vertici, lasciando alla direzione le decisioni principali.","leve":["rel","gui"],"macro":"com","microtemi":["voce","comunicazione","decentralizzazione","informazione","porta aperta"],"motivi":{"comunicazione":"Il tema centrale è l'apertura della comunicazione interna.","decentralizzazione":"Mostra che aprire la comunicazione non significa decentrare le decisioni.","informazione":"Le informazioni vengono messe a disposizione di tutti i dipendenti.","porta aperta":"Le domande dirette ai vertici sono una porta aperta resa concreta.","voce":"L'azienda studiata apre a tutti la possibilità di parlare e criticare."},"organizzazioni":[],"problema":"Un'azienda giovane e in crescita voleva evitare la rigidità della burocrazia e diventare aperta come i mezzi di comunicazione che vendeva.","prova":"caso studio","settore":"Tecnologia, marketing sui social media (Stati Uniti)","sinossi":"Turco, sociologa del MIT, passa molti mesi dentro un'azienda statunitense di marketing sui social media, che nel libro chiama TechCo, per osservare un esperimento organizzativo. L'azienda vuole essere aperta come i mezzi di comunicazione che vende, e mette a disposizione di tutti informazioni, canali interni di discussione, incontri plenari e domande dirette ai vertici. Lo studio etnografico mostra che l'apertura della comunicazione funziona: le persone parlano, criticano e propongono, e l'organizzazione impara molto da questa conversazione. Le decisioni importanti restano invece in mano alla direzione, e la gerarchia dell'autorità non viene smontata. Turco sostiene che apertura della comunicazione e decentramento delle decisioni sono due dimensioni diverse, che molte riflessioni sulle organizzazioni senza burocrazia tengono confuse. Il libro descrive anche le tensioni nate quando le aspettative di partecipazione dei dipendenti superavano lo spazio concesso. È lo studio di una sola azienda giovane e tecnologica, e la sua generalizzazione ad altri settori va fatta con prudenza.","tipo":"caso","titolo":"The Conversational Firm: Rethinking Bureaucracy in the Age of Social Media","url":"https://doi.org/10.7312/turc17898","id":"turco-2016-conversational"},{"anno":1984,"area":"nat","autori":"Roger S. Ulrich","autoriIds":["roger-s-ulrich"],"collegamenti":["kaplan"],"concetti":["vista sul verde","recupero","design biofilico","benessere organizzativo"],"contesto":["sanità"],"creata":"2026-11-04","doi":"10.1126/science.6143402","etichetta":"Ulrich","evidenza":"diretta","fonte":"«View through a window may influence recovery from surgery», Science, 224, 1984","inAzienda":"La vista su elementi naturali ha effetti misurati sul recupero delle persone. Nella progettazione degli spazi di lavoro conviene quindi considerare che cosa si vede dalle finestre, oltre alla quantità di luce.","leve":["rig"],"macro":"ben","microtemi":["vista sul verde","recupero dallo stress","design biofilico","spazi di lavoro","benessere"],"motivi":{"benessere":"I pazienti con la finestra sugli alberi chiesero meno dosi di analgesici forti.","design biofilico":"È uno degli studi su cui si fonda il design biofilico.","recupero dallo stress":"I pazienti con la vista sugli alberi lasciarono l'ospedale prima di quelli con la vista su un muro.","spazi di lavoro":"Il risultato, ottenuto in ospedale, è stato poi esteso alla progettazione degli spazi di lavoro.","vista sul verde":"Lo studio confronta pazienti con la finestra rivolta verso gli alberi e pazienti con la finestra rivolta verso un muro."},"organizzazioni":[],"prova":"studio osservazionale","sinossi":"Ulrich confrontò le cartelle cliniche di pazienti operati alla cistifellea in un ospedale della Pennsylvania fra il 1972 e il 1981, appaiati per età, sesso e altre caratteristiche. Ventitré pazienti avevano una finestra sugli alberi, ventitré su un muro di mattoni. Chi vedeva gli alberi restava in ospedale in media quasi un giorno in meno, riceveva meno antidolorifici forti e meno note negative degli infermieri. Fu uno dei primi studi a misurare un effetto della natura sulla salute in un contesto reale, e aprì la strada al design di ospedali e uffici. Il campione è piccolo e lo studio è basato su registri, non su un esperimento.","tipo":"articolo","titolo":"View through a window may influence recovery from surgery","url":"https://doi.org/10.1126/science.6143402","id":"ulrich"},{"anno":2012,"area":"soc","autori":"Hans van Dijk, Marloes L. van Engen, Daan van Knippenberg","autoriIds":["hans-van-dijk","marloes-l-van-engen","daan-van-knippenberg"],"collegamenti":["tajfel-turner","sherif"],"concetti":["diversità","conflitto fra gruppi","lavoro di squadra"],"contesto":["gruppi di lavoro"],"creata":"2026-11-05","doi":"10.1016/j.obhdp.2012.06.003","etichetta":"van Dijk et al.","evidenza":"","fonte":"Organizational Behavior and Human Decision Processes, 119(1), 38-53, 2012","inAzienda":"La diversità non migliora né peggiora da sola le prestazioni; conta come il gruppo usa le differenze e chi giudica il risultato.","leve":["rel"],"macro":"ind","microtemi":["diversità","inclusione","pregiudizi","team","meta-analisi"],"motivi":{"diversità":"È una meta-analisi sul rapporto fra diversità e prestazione dei gruppi.","inclusione":"Mette in discussione l'idea che la diversità demografica danneggi i gruppi.","meta-analisi":"Riassume la letteratura con metodi quantitativi.","pregiudizi":"Parte dei risultati negativi emerge con valutazioni soggettive della prestazione.","team":"L'unità di analisi è il gruppo di lavoro."},"organizzazioni":[],"prova":"meta-analisi","sinossi":"Una convinzione diffusa vuole che la diversità legata al lavoro, come formazione, funzione ed esperienza, migliori i gruppi, mentre la diversità demografica, come genere, età ed etnia, li peggiori. Gli autori mettono alla prova questa idea con una meta-analisi degli studi sul rapporto fra diversità dei gruppi e prestazione. Distinguono i tipi di diversità, i tipi di prestazione, come innovazione e qualità, e il modo in cui la prestazione è misurata. La diversità legata al lavoro mostra relazioni positive ma piccole con alcune forme di prestazione, soprattutto innovazione e qualità. La diversità demografica, nel complesso, non risulta legata alla prestazione in modo apprezzabile. Le differenze fra i due tipi di diversità sono minori di quanto si pensasse, e una parte dei risultati negativi della diversità demografica emerge quando la prestazione è giudicata da valutatori soggettivi. Le meta-analisi riassumono studi molto diversi e dicono poco sulle condizioni concrete in cui la diversità aiuta o danneggia un gruppo.","tipo":"articolo","titolo":"Defying conventional wisdom: A meta-analytical examination of the differences between demographic and job-related diversity relationships with performance","url":"https://doi.org/10.1016/j.obhdp.2012.06.003","id":"vandijk-2012-diversity"},{"anno":2019,"area":"sis","autori":"Gregory Vial","autoriIds":["gregory-vial"],"collegamenti":["emery-trist","lawrence-lorsch","katz-kahn"],"concetti":["trasformazione digitale","sistemi sociotecnici","contingenza","resistenza al cambiamento"],"contesto":["tecnologia"],"creata":"2026-11-05","doi":"10.1016/j.jsis.2019.01.003","etichetta":"Vial","evidenza":"","fonte":"The Journal of Strategic Information Systems, 28(2), 118-144, 2019","inAzienda":"Un progetto digitale va letto insieme alla strategia, alla struttura e alle resistenze, perché lì si decide se produce valore o solo costi.","leve":["app","rel"],"macro":"tra","microtemi":["trasformazione digitale","sociotecnico","ambiente esterno","resistenza al cambiamento","adattamento"],"motivi":{"adattamento":"Descrive come l'organizzazione cambia il modo di creare valore.","ambiente esterno":"Le tecnologie digitali creano discontinuità nel contesto in cui l'organizzazione opera.","resistenza al cambiamento":"Fra gli elementi del modello ci sono gli ostacoli organizzativi e l'inerzia.","sociotecnico":"Lega la tecnologia ai cambiamenti di struttura e di organizzazione.","trasformazione digitale":"È una rassegna sistematica sul concetto stesso di trasformazione digitale."},"organizzazioni":[],"prova":"rassegna","sinossi":"Vial parte da un problema di definizione: tutti parlano di trasformazione digitale, ma la ricerca ne aveva studiato solo pezzi separati. Rivede 282 lavori e ricava per induzione un modello in otto elementi. La trasformazione digitale vi appare come un processo in cui le tecnologie digitali creano discontinuità, l'organizzazione risponde con scelte strategiche e cambia il modo in cui crea valore. Lungo il percorso incontra cambiamenti di struttura e ostacoli organizzativi, come le resistenze e l'inerzia, che decidono se gli esiti saranno positivi o negativi. L'autore propone di studiare le capacità dinamiche dell'organizzazione e le questioni etiche come due direzioni prioritarie. La rassegna è diventata uno dei riferimenti più citati sul tema e offre un vocabolario ordinato a chi progetta interventi. È una sintesi della letteratura e non porta dati nuovi, e la maggior parte degli studi rivisti viene dai sistemi informativi più che dalla psicologia delle organizzazioni.","tipo":"articolo","titolo":"Understanding digital transformation: A review and a research agenda","url":"https://doi.org/10.1016/j.jsis.2019.01.003","id":"vial-2019-digital"},{"anno":1995,"area":"evo","autori":"Karl E. Weick","autoriIds":["karl-e-weick"],"collegamenti":["maturana-varela","morgan","ballerini"],"concetti":["costruzione di senso","turbolenza ambientale","resilienza","cultura organizzativa"],"contesto":["emergenze"],"creata":"2026-11-04","etichetta":"Weick","evidenza":"","fonte":"Sensemaking in Organizations, Sage, 1995","inAzienda":"In una crisi un gruppo resta capace di agire finché riesce a costruire un'interpretazione comune di ciò che sta succedendo. Preparare i gruppi a parlarsi e a rivedere le proprie interpretazioni conta quanto avere un piano di emergenza.","leve":["app","rel","cul"],"macro":"tra","microtemi":["costruzione di senso","incertezza","crisi","narrazione","organizzazioni ad alta affidabilità"],"organizzazioni":["US Forest Service"],"prova":"caso studio","sinossi":"Karl Weick sostiene che le organizzazioni non reagiscono a una realtà già data, ma la costruiscono: le persone agiscono, osservano gli effetti delle proprie azioni e si raccontano che cosa sta succedendo. Questo processo di costruzione di senso diventa decisivo quando l'ambiente è incerto o qualcosa si interrompe. Weick lo mostra con casi come l'incendio di Mann Gulch del 1949, in cui una squadra di vigili del fuoco paracadutati perse il proprio senso di gruppo e tredici uomini morirono. Il caposquadra accese un controfuoco e vi si sdraiò dentro, salvandosi, ma gli altri non lo seguirono, perché il gesto non aveva senso nel quadro che condividevano. Il libro è teorico e si basa su casi, ma ha influenzato profondamente gli studi sulle crisi.","tipo":"libro","titolo":"Sensemaking in Organizations","url":"https://www.sagepub.com/shop/buy-a-book/sensemaking-in-organizations-1-4988","id":"weick"},{"anno":2019,"area":"nat","autori":"Mathew P. White, Ian Alcock, James Grellier, Benedict W. Wheeler, Terry Hartig e colleghi","autoriIds":["mathew-p-white","ian-alcock","james-grellier","benedict-w-wheeler","terry-hartig"],"collegamenti":["kaplan"],"concetti":["immersione nel bosco","stress lavorativo","benessere organizzativo","connessione con la natura"],"contesto":["natura"],"creata":"2026-11-04","doi":"10.1038/s41598-019-44097-3","etichetta":"White et al.","evidenza":"diretta","fonte":"Scientific Reports, 9, 7730, 2019","inAzienda":"Due ore alla settimana in ambienti naturali, anche distribuite in più uscite brevi, sono associate a una salute e a un benessere migliori. È un riferimento utile per progettare programmi di benessere aziendale regolari e realistici.","leve":["rig"],"macro":"ben","microtemi":["tempo in natura","salute","benessere","connessione con la natura"],"motivi":{},"organizzazioni":[],"prova":"indagine con questionario","sinossi":"Mathew White e i suoi colleghi dell'Università di Exeter analizzano i dati di un'indagine nazionale inglese su quasi ventimila adulti, a cui era stato chiesto quanto tempo avessero passato in ambienti naturali nella settimana precedente. Chi aveva trascorso almeno due ore in natura riferiva più spesso una buona salute e un buon benessere rispetto a chi non c'era stato affatto, mentre sotto le due ore non emergevano differenze. Il risultato valeva anche quando le due ore erano distribuite in più uscite brevi e per persone di età e condizioni diverse. I dati sono dichiarati dagli intervistati e raccolti in un solo momento, quindi descrivono un'associazione e non una causa.","tipo":"articolo","titolo":"Spending at least 120 minutes a week in nature is associated with good health and wellbeing","url":"https://doi.org/10.1038/s41598-019-44097-3","id":"white-2019-120-minutes"},{"anno":1999,"area":"nat","autori":"Andrew Whiten, Jane Goodall, William C. McGrew, Toshisada Nishida, Vernon Reynolds e colleghi","autoriIds":["andrew-whiten","jane-goodall","william-c-mcgrew","toshisada-nishida","vernon-reynolds"],"collegamenti":["schein","kawai"],"concetti":["cultura organizzativa"],"contesto":["primati"],"creata":"2026-11-05","doi":"10.1038/21415","etichetta":"Whiten et al.","evidenza":"funzionale","fonte":"Nature, 399(6737), 682-685, 1999","inAzienda":"Due sedi con la stessa tecnologia e le stesse regole possono avere abitudini diverse, e quelle differenze vanno osservate e capite prima di uniformarle.","leve":["app","rel"],"macro":"cul","microtemi":["cultura","norme","artefatti","cultura organizzativa","apprendimento sociale"],"motivi":{"apprendimento sociale":"Le differenze si spiegano con la trasmissione sociale delle abitudini.","artefatti":"L'uso di strumenti è una parte visibile della cultura di ogni comunità.","cultura":"Documenta differenze culturali fra comunità della stessa specie.","cultura organizzativa":"È un'analogia funzionale per le differenze di cultura fra sedi e reparti.","norme":"I comportamenti abituali di una comunità funzionano come norme locali."},"organizzazioni":[],"prova":"osservazione sul campo","sinossi":"Andrew Whiten, dell'Università di St Andrews, e colleghi, responsabili dei sette studi più lunghi sugli scimpanzé selvatici in Africa, mettono insieme i loro dati per rispondere a una domanda antica: gli animali hanno culture? Le osservazioni sommate coprono 151 anni di studio sul campo. Individuano 39 comportamenti, fra cui l'uso di strumenti, forme di pulizia reciproca e di corteggiamento, che sono abituali in alcune comunità e assenti in altre, in casi in cui le differenze di ambiente non bastano a spiegarli. Una comunità rompe le noci con pietre e un'altra, che ha noci e pietre, non lo fa. Secondo gli autori questa variazione è molto più ampia di quella documentata in qualunque altra specie a parte l'uomo. Ogni comunità ha un repertorio complessivo riconoscibile, una combinazione di abitudini che la distingue dalle altre. Il metodo esclude le spiegazioni ecologiche per confronto e non dimostra direttamente l'apprendimento sociale, che è stato poi indagato con esperimenti.","tipo":"articolo","titolo":"Cultures in chimpanzees","url":"https://doi.org/10.1038/21415","id":"whiten-1999-cultures"},{"anno":1948,"area":"sis","autori":"Norbert Wiener","autoriIds":["norbert-wiener"],"collegamenti":["ashby","bateson","seeley"],"concetti":["retroazione","regolazione distribuita","comunicazione","autonomia","misura della cultura"],"contesto":["sistemi"],"creata":"2026-11-04","etichetta":"Wiener","evidenza":"","fonte":"Cybernetics, MIT Press, 1948","inAzienda":"Un'organizzazione si corregge solo se riceve un segnale affidabile e tempestivo sugli effetti delle proprie azioni. Per questo il metodo misura prima e dopo ogni intervento: la misura è il segnale di ritorno che permette di correggere la rotta.","leve":["app","car"],"macro":"app","microtemi":["retroazione","autoregolazione","informazione","controllo","misura"],"organizzazioni":[],"prova":"teoria","sinossi":"Norbert Wiener, matematico al MIT, fonda con questo libro la cibernetica, la scienza del controllo e della comunicazione negli animali e nelle macchine. Il concetto centrale è la retroazione: un sistema confronta il risultato delle proprie azioni con l'obiettivo e usa la differenza per correggersi, come il timoniere che aggiusta la rotta. Wiener mostra che lo stesso principio regola un termostato, il puntamento di un cannone antiaereo e il movimento di un braccio, e che una retroazione difettosa produce oscillazioni e instabilità. Il libro è in gran parte matematico, ma le sue idee hanno influenzato la biologia, la psicologia e lo studio delle organizzazioni. Il nome viene dalla parola greca che indica il timoniere.","tipo":"libro","titolo":"Cybernetics","url":"https://openlibrary.org/works/OL4307531W","id":"wiener"},{"anno":1984,"area":"nat","autori":"Gerald S. Wilkinson","autoriIds":["gerald-s-wilkinson"],"collegamenti":["ostrom"],"concetti":["reciprocità","sicurezza psicologica"],"contesto":["pipistrelli"],"creata":"2026-11-04","doi":"10.1038/308181a0","etichetta":"Wilkinson","evidenza":"funzionale","fonte":"«Reciprocal food sharing in the vampire bat», Nature, 308, 1984","inAzienda":"La collaborazione fra colleghi e fra reparti regge nel tempo se gli aiuti vengono ricambiati e se qualcuno se ne ricorda. Rendere visibili gli scambi reciproci rafforza la fiducia più che chiederla.","leve":["rel"],"macro":"com","microtemi":["reciprocità","fiducia","scambi ripetuti","cooperazione","parentela"],"motivi":{"cooperazione":"Lo scambio di cibo fra pipistrelli vampiro è uno degli esempi più citati di cooperazione fra animali non imparentati.","fiducia":"I pipistrelli aiutano soprattutto chi li ha aiutati in passato, cioè chi si è dimostrato affidabile.","parentela":"Una parte degli scambi avviene fra parenti, ma lo scambio riguarda anche individui non imparentati.","reciprocità":"Lo studio documenta lo scambio reciproco di cibo fra pipistrelli vampiro.","scambi ripetuti":"Gli scambi avvengono fra individui che si incontrano spesso e possono quindi ricambiare."},"organizzazioni":[],"prova":"osservazione sul campo","sinossi":"Gerald Wilkinson osservò per anni in Costa Rica colonie di pipistrelli vampiro comuni, animali che si nutrono solo di sangue e rischiano di morire se restano senza cibo per due o tre notti di fila. Notò che gli individui che tornavano al rifugio sazi rigurgitavano parte del sangue per compagni rimasti a digiuno. Lo scambio avveniva soprattutto fra parenti stretti, ma anche fra animali non imparentati che condividevano spesso il rifugio e quindi si incontravano molte volte. Per verificare il ruolo della reciprocità condusse esperimenti in cattività con individui raccolti da colonie diverse, togliendo il cibo a uno alla volta. I pipistrelli tendevano a nutrire chi in passato aveva nutrito loro, come previsto dalla teoria dell'altruismo reciproco. Lo studio è diventato uno degli esempi più citati di cooperazione reciproca negli animali, e ricerche più recenti dello stesso filone hanno confermato il ruolo dei legami sociali. Il numero di osservazioni era limitato e il peso relativo di parentela e reciprocità è stato poi discusso.","tipo":"articolo","titolo":"Reciprocal food sharing in the vampire bat","url":"https://doi.org/10.1038/308181a0","id":"wilkinson"},{"anno":1984,"area":"nat","autori":"Edward O. Wilson","autoriIds":["edward-o-wilson"],"collegamenti":["benyus"],"concetti":["biofilia","connessione con la natura","autopoiesi","benessere organizzativo"],"contesto":["natura"],"creata":"2026-11-04","doi":"","etichetta":"Wilson","evidenza":"","fonte":"Harvard University Press, Cambridge (MA), 1984","inAzienda":"Se le persone hanno una tendenza innata a cercare il contatto con il mondo vivente, la presenza della natura negli spazi e nei tempi di lavoro risponde a un bisogno e non è un ornamento. Va però ricordato che si tratta di un'ipotesi ancora in verifica.","leve":["rig"],"macro":"ind","microtemi":["biofilia","connessione con la natura","evoluzione","benessere"],"motivi":{},"organizzazioni":[],"prova":"saggio","sinossi":"Edward O. Wilson, biologo di Harvard e massimo studioso delle formiche, propone in questo libro che gli esseri umani abbiano una tendenza innata a cercare il legame con le altre forme di vita, e la chiama biofilia. La spiega come un'eredità della lunga storia evolutiva vissuta dalla nostra specie in ambienti naturali. Il libro intreccia ricordi della ricerca sul campo in Amazzonia e nel Suriname con la riflessione teorica, e ha portato il termine nel dibattito scientifico. Più che un risultato dimostrato è un programma di ricerca, che gli studi successivi hanno messo alla prova un aspetto alla volta.","tipo":"libro","titolo":"Biophilia","url":"https://www.hup.harvard.edu/books/9780674074422","id":"wilson-1984-biophilia"},{"anno":2022,"area":"sis","autori":"Longqi Yang, David Holtz, Sonia Jaffe, Siddharth Suri, Shilpi Sinha e colleghi","autoriIds":["longqi-yang","david-holtz","sonia-jaffe","siddharth-suri","shilpi-sinha"],"collegamenti":["mintzberg","morrison-milliken"],"concetti":["lavoro a distanza e ibrido","comunicazione","lavoro di squadra"],"contesto":["tecnologia"],"creata":"2026-11-05","doi":"10.1038/s41562-021-01196-4","etichetta":"Yang et al.","evidenza":"","fonte":"Nature Human Behaviour, 6(1), 43-54, 2022","inAzienda":"Nel lavoro ibrido i giorni in presenza vanno usati soprattutto per i legami fra reparti, che a distanza si indeboliscono per primi.","leve":["rel"],"macro":"tra","microtemi":["lavoro a distanza","lavoro ibrido","comunicazione","informazione","coordinamento"],"motivi":{"comunicazione":"Mostra il passaggio dalla comunicazione sincrona a quella asincrona.","coordinamento":"Si riducono i ponti che coordinano parti lontane dell'organizzazione.","informazione":"Una rete più chiusa fa circolare meno informazioni nuove fra gruppi.","lavoro a distanza":"Misura gli effetti del lavoro da remoto esteso a tutta l'azienda.","lavoro ibrido":"I risultati sono la base per decidere come combinare presenza e distanza."},"organizzazioni":["Microsoft"],"prova":"studio osservazionale","sinossi":"La pandemia ha spostato all'improvviso molti lavoratori della conoscenza al lavoro da remoto, e gli autori usano questo passaggio come un esperimento naturale, sfruttando il fatto che alcuni lavoravano già a distanza prima. Analizzano mail, calendari, messaggi istantanei, chiamate e ore settimanali di 61.182 dipendenti statunitensi di Microsoft nei primi sei mesi del 2020. Il lavoro a distanza esteso a tutta l'azienda rende la rete di collaborazione più statica e più chiusa in compartimenti, con meno ponti fra parti lontane dell'organizzazione. Diminuisce la comunicazione sincrona e aumenta quella asincrona. Secondo gli autori questi cambiamenti possono rendere più difficile trasmettere conoscenza complessa e scambiare informazioni nuove fra gruppi. Lo studio ha influenzato il dibattito sul ritorno in ufficio e sulla progettazione del lavoro ibrido. Riguarda un'unica grande azienda tecnologica, un periodo eccezionale e i soli dati digitali, senza misure dirette di innovazione o di prestazione.","tipo":"articolo","titolo":"The effects of remote work on collaboration among information workers","url":"https://doi.org/10.1038/s41562-021-01196-4","id":"yang-2022-remote"}],"autori":[{"nome":"Albert Bandura","paroleChiave":[],"sintesi":"Indicò quattro fonti dell'autoefficacia: esperienze di successo, esempi altrui, persuasione e stati fisiologici.","temi":[],"teoria":"Le persone agiscono quando credono di poter riuscire, e questa convinzione si costruisce soprattutto con esperienze di successo.","id":"albert-bandura"},{"nome":"Albert O. Hirschman","paroleChiave":[],"sintesi":"Economista, mostrò che uscita e voce sono due meccanismi di recupero e che la lealtà ritarda l'uscita.","temi":[],"teoria":"Davanti a un peggioramento i membri di un'organizzazione se ne vanno o protestano; se la voce non ha canali, resta l'uscita.","id":"albert-o-hirschman"},{"nome":"Alex Thornton","paroleChiave":["insegnamento","apprendimento sociale","suricati","cognizione animale"],"sintesi":"Etologo, studia la cognizione e l'apprendimento sociale negli animali selvatici, dai suricati del Kalahari agli uccelli corvidi. Con Katherine McAuliffe ha fornito una delle prime prove solide di insegnamento attivo in un animale.","temi":[{"motivo":"Ha documentato l'insegnamento nei suricati.","tema":"apprendimento"},{"motivo":"Mostra come compiti graduati accelerano l'apprendimento.","tema":"esperienze di successo"}],"teoria":"L'insegnamento può esistere anche senza capacità cognitive complesse, come risposta graduale ai segnali di chi impara.","id":"alex-thornton"},{"altreOpere":["Psychological safety and learning behavior in work teams, 1999","Disrupted Routines (con R.M. Bohmer, G.P. Pisano), 2001","Teaming, 2012","The Fearless Organization, 2018","Right Kind of Wrong, 2023"],"nome":"Amy C. Edmondson","paroleChiave":["sicurezza psicologica","apprendimento di team","errori","teaming","autogestione"],"sintesi":"Il risultato nacque dallo studio di errori nella somministrazione di farmaci in reparti ospedalieri: i team migliori ne dichiaravano di più.","temi":[{"motivo":"Ha definito e misurato la sicurezza psicologica nei team.","tema":"sicurezza psicologica"},{"motivo":"Studia come i team imparano dagli errori e dalle tecnologie nuove.","tema":"apprendimento di team"},{"motivo":"Distingue gli errori da evitare da quelli da cui imparare.","tema":"errori"},{"motivo":"Ha studiato i limiti delle organizzazioni autogestite.","tema":"decentralizzazione"}],"teoria":"I team imparano quando le persone si sentono al sicuro nel segnalare errori e proporre idee.","url":"https://en.wikipedia.org/wiki/Amy_Edmondson","id":"amy-c-edmondson"},{"altreOpere":["Machiavellian Intelligence (a cura di, con R.W. Byrne), 1988","Cultures in chimpanzees (con J. Goodall e colleghi), 1999","Conformity to cultural norms of tool use in chimpanzees (con V. Horner, F.B.M. de Waal), 2005"],"anni":"1948","nome":"Andrew Whiten","paroleChiave":["cultura animale","primati","apprendimento sociale","intelligenza sociale","tradizioni"],"sintesi":"Zoologo e psicologo britannico, professore emerito all'Università di St Andrews, studia l'evoluzione dell'intelligenza sociale e della cultura nei primati. Ha coordinato la sintesi dei dati sulle culture degli scimpanzé pubblicata su Nature nel 1999 e ha condotto esperimenti sulla trasmissione sociale delle abitudini.","temi":[{"motivo":"Ha documentato le culture degli scimpanzé.","tema":"cultura"},{"motivo":"Ha studiato la conformità alle norme culturali nei primati.","tema":"norme"}],"teoria":"Molti animali, e in particolare le grandi scimmie, hanno tradizioni trasmesse socialmente, e la conformità al gruppo aiuta a mantenerle.","url":"https://en.wikipedia.org/wiki/Andrew_Whiten","id":"andrew-whiten"},{"nome":"Bernard M. Bass","paroleChiave":[],"sintesi":"Sviluppò il Multifactor Leadership Questionnaire e distinse leadership transazionale e trasformazionale.","temi":[],"teoria":"La leadership trasformazionale ispira, dà significato e fa crescere i collaboratori oltre lo scambio fra premio e prestazione.","id":"bernard-m-bass"},{"nome":"C.S. Holling","paroleChiave":[],"sintesi":"Ecologo canadese, introdusse il concetto di resilienza nello studio degli ecosistemi.","temi":[],"teoria":"Distingue la stabilità, cioè tornare in fretta all'equilibrio, dalla resilienza, cioè assorbire i disturbi senza perdere le proprie funzioni.","id":"c-s-holling"},{"nome":"Catherine J. Turco","paroleChiave":["etnografia","comunicazione","burocrazia","social media","organizzazione"],"sintesi":"Sociologa delle organizzazioni alla MIT Sloan School of Management, studia con metodi etnografici come cambiano le organizzazioni e il lavoro con i nuovi mezzi di comunicazione. Il suo libro The Conversational Firm racconta un'azienda tecnologica che ha aperto la comunicazione senza decentrare le decisioni.","temi":[{"motivo":"Ha studiato un'azienda che ha aperto la voce a tutti i dipendenti.","tema":"voce"},{"motivo":"Distingue la comunicazione aperta dal decentramento delle decisioni.","tema":"decentralizzazione"}],"teoria":"L'apertura della comunicazione e il decentramento dell'autorità sono due dimensioni diverse, e un'organizzazione può spingere molto sulla prima mantenendo la seconda.","id":"catherine-j-turco"},{"altreOpere":["People and Organizational Culture (con J. Chatman, D.F. Caldwell), 1991","Hidden Value (con J. Pfeffer), 2000","Organizational Ambidexterity: Past, Present, and Future (con M.L. Tushman), 2013","Lead and Disrupt (con M.L. Tushman), 2016"],"nome":"Charles A. O'Reilly","paroleChiave":["cultura organizzativa","valori","corrispondenza persona organizzazione","ambidestrismo","innovazione"],"sintesi":"Docente di management alla Stanford Graduate School of Business, ha studiato la cultura organizzativa, la corrispondenza fra persone e organizzazioni e la capacità delle imprese di innovare mentre sfruttano ciò che sanno fare. Con Jennifer Chatman e David Caldwell ha creato l'Organizational Culture Profile.","temi":[{"motivo":"Ha creato uno degli strumenti più usati per misurare la cultura.","tema":"misura della cultura"},{"motivo":"La cultura è il centro di molte sue ricerche.","tema":"cultura organizzativa"},{"motivo":"Ha studiato come le imprese esplorano mentre sfruttano.","tema":"esplorazione"}],"teoria":"La cultura si può misurare come insieme di valori condivisi, e la corrispondenza fra i valori della persona e quelli dell'organizzazione prevede impegno e permanenza.","url":"https://en.wikipedia.org/wiki/Charles_A._O%27Reilly_III","id":"charles-a-o-reilly"},{"altreOpere":["Maslach Burnout Inventory (con S.E. Jackson), 1981","The Truth About Burnout (con M.P. Leiter), 1997"],"anni":"1946","nome":"Christina Maslach","paroleChiave":["burnout","esaurimento","cinismo","sei aree del lavoro","psicologia sociale"],"sintesi":"Psicologa a Berkeley, autrice del Maslach Burnout Inventory, individuò sei aree del rapporto con il lavoro che proteggono o espongono al burnout.","temi":[{"motivo":"Ha definito e misurato il burnout.","tema":"burnout"},{"motivo":"L'esaurimento è la prima componente del burnout nel suo modello.","tema":"esaurimento"},{"motivo":"Il carico è la prima delle sei aree di squilibrio.","tema":"carico di lavoro"}],"teoria":"Il burnout è fatto di esaurimento, cinismo e senso di inefficacia, e dipende dal rapporto fra persona e lavoro, non dalla sola persona.","url":"https://en.wikipedia.org/wiki/Christina_Maslach","id":"christina-maslach"},{"altreOpere":["Skills, Tasks and Technologies (con D. Autor), 2011","Why Nations Fail (con J.A. Robinson), 2012","The Race between Man and Machine (con P. Restrepo), 2018","The Narrow Corridor (con J.A. Robinson), 2019","Power and Progress (con S. Johnson), 2023"],"anni":"1967","nome":"Daron Acemoglu","paroleChiave":["automazione","istituzioni","tecnologia","lavoro","disuguaglianza"],"sintesi":"Economista turco statunitense, insegna al MIT dal 1993 e ha ricevuto nel 2024 il premio Nobel per l'economia insieme a Simon Johnson e James Robinson. Studia le istituzioni, la crescita economica e gli effetti della tecnologia sul lavoro. Con Pascual Restrepo ha misurato gli effetti dei robot industriali su occupazione e salari.","temi":[{"motivo":"Ha misurato gli effetti dei robot sui mercati del lavoro.","tema":"automazione"},{"motivo":"Studia come istituzioni e tecnologie cambiano il contesto delle imprese.","tema":"ambiente esterno"},{"motivo":"Discute quale direzione dare alle nuove tecnologie.","tema":"intelligenza artificiale"}],"teoria":"La tecnologia non ha una direzione obbligata: può sostituire il lavoro o aumentarne il valore, e la scelta dipende da istituzioni, incentivi e potere.","url":"https://en.wikipedia.org/wiki/Daron_Acemoglu","id":"daron-acemoglu"},{"nome":"Deborah M. Gordon","paroleChiave":[],"sintesi":"Biologa a Stanford, studiò per decenni colonie di formiche del deserto in Arizona.","temi":[],"teoria":"Le formiche raccoglitrici regolano il foraggiamento dal ritmo degli incontri con le compagne che rientrano, senza ordini.","id":"deborah-m-gordon"},{"nome":"Denise M. Rousseau","paroleChiave":[],"sintesi":"Distinse contratti psicologici transazionali, basati sullo scambio, e relazionali, basati su fiducia e lealtà.","temi":[],"teoria":"Ogni persona ha un accordo implicito con l'organizzazione; quando lo sente violato, riduce l'impegno o se ne va.","id":"denise-m-rousseau"},{"altreOpere":["The Limits to Growth (con altri), 1972","Beyond the Limits (con D.L. Meadows, J. Randers), 1992","Leverage Points: Places to Intervene in a System, 1999","Thinking in Systems, 2008"],"anni":"1941-2001","nome":"Donella H. Meadows","paroleChiave":["pensiero sistemico","punti di leva","stock e flussi","sostenibilità","retroazione"],"sintesi":"Scienziata ambientale e coautrice dei Limiti dello sviluppo, ordinò i punti di intervento in un sistema dal meno al più efficace, dai parametri ai paradigmi.","temi":[{"motivo":"Ha classificato i punti in cui si interviene su un sistema.","tema":"punti di leva"},{"motivo":"Ha reso accessibile il linguaggio di stock e flussi.","tema":"stock e flussi"},{"motivo":"I cicli di retroazione sono al centro del suo pensiero.","tema":"retroazione"}],"teoria":"In un sistema esistono punti di leva dove una piccola spinta produce grandi effetti, spesso lontano da dove si cercano.","url":"https://en.wikipedia.org/wiki/Donella_Meadows","id":"donella-h-meadows"},{"altreOpere":["Process Consultation Revisited, 1998","Helping, 2011","Career Anchors (con J. Van Maanen), 4a ed. 2013","Humble Inquiry (con P.A. Schein), 2a ed. 2021"],"anni":"1928-2023","nome":"Edgar H. Schein","paroleChiave":["cultura organizzativa","assunti di base","consulenza di processo","indagine umile","relazione di aiuto"],"sintesi":"Professore al MIT, unì antropologia e psicologia per descrivere come una cultura nasce, si trasmette e cambia.","temi":[{"motivo":"Ha descritto i tre livelli della cultura.","tema":"cultura organizzativa"},{"motivo":"Gli assunti dati per scontati sono il livello profondo della sua teoria.","tema":"assunti di base"},{"motivo":"Ha proposto di chiedere invece di dire come forma di aiuto.","tema":"indagine umile"}],"teoria":"La cultura ha tre livelli: ciò che si vede, i valori dichiarati, gli assunti dati per scontati.","url":"https://en.wikipedia.org/wiki/Edgar_Schein","id":"edgar-h-schein"},{"altreOpere":["Rules, Games, and Common-Pool Resources (con R. Gardner, J. Walker), 1994","Understanding Institutional Diversity, 2005","Working Together (con A.R. Poteete, M.A. Janssen), 2010"],"anni":"1933-2012","nome":"Elinor Ostrom","paroleChiave":["beni comuni","autogoverno","istituzioni","regole condivise","azione collettiva"],"sintesi":"Premio Nobel per l'economia, documentò sistemi di gestione comune di pascoli, foreste e acque durati secoli e ne ricavò otto principi.","temi":[{"motivo":"Ha mostrato che le comunità possono gestire i beni comuni senza esaurirli.","tema":"beni comuni"},{"motivo":"Ha individuato i principi delle istituzioni che funzionano.","tema":"regole condivise"},{"motivo":"Ha studiato l'autogoverno delle risorse condivise.","tema":"autogoverno"}],"teoria":"Comunità di utenti gestiscono risorse comuni senza autorità centrale né mercato, se hanno regole chiare, controllo reciproco e sanzioni graduali.","url":"https://en.wikipedia.org/wiki/Elinor_Ostrom","id":"elinor-ostrom"},{"altreOpere":["Beyond Computation: Information Technology, Organizational Transformation and Business Performance (con L.M. Hitt), 2000","Race Against the Machine (con A. McAfee), 2011","The Second Machine Age (con A. McAfee), 2014","Machine, Platform, Crowd (con A. McAfee), 2017","The Productivity J-Curve (con D. Rock, C. Syverson), 2021"],"nome":"Erik Brynjolfsson","paroleChiave":["intelligenza artificiale","produttività","economia digitale","beni immateriali","lavoro"],"sintesi":"Economista, ha insegnato a lungo al MIT e dirige ora il Digital Economy Lab della Stanford University. Studia da decenni il rapporto fra tecnologie dell'informazione, organizzazione del lavoro e produttività. Con Andrew McAfee ha scritto libri molto letti sulla seconda età delle macchine. Lo studio sull'assistenza clienti con l'intelligenza artificiale generativa è uno dei primi esperimenti sul campo su larga scala.","temi":[{"motivo":"Studia sul campo gli effetti dell'intelligenza artificiale generativa sul lavoro.","tema":"intelligenza artificiale"},{"motivo":"Ha mostrato che la tecnologia rende solo insieme a cambiamenti organizzativi.","tema":"trasformazione digitale"},{"motivo":"La produttività è la variabile centrale delle sue ricerche.","tema":"produttività"}],"teoria":"Le tecnologie generali producono valore solo quando le organizzazioni investono in beni immateriali complementari, come processi, competenze e modi di lavorare, e per questo i guadagni arrivano in ritardo.","url":"https://en.wikipedia.org/wiki/Erik_Brynjolfsson","id":"erik-brynjolfsson"},{"altreOpere":["Diffusion of Innovations, 1a ed. 1962"],"anni":"1931-2004","nome":"Everett M. Rogers","paroleChiave":["diffusione delle innovazioni","primi adottanti","opinion leader","comunicazione"],"sintesi":"Sintetizzò centinaia di studi sulla diffusione di pratiche agricole, mediche e tecnologiche.","temi":[{"motivo":"Ha fondato lo studio della diffusione delle innovazioni.","tema":"diffusione delle innovazioni"},{"motivo":"Ha descritto le categorie di adottanti.","tema":"primi adottanti"},{"motivo":"Ha mostrato il ruolo dei leader di opinione nelle reti.","tema":"opinion leader"}],"teoria":"Le innovazioni si diffondono lungo reti di relazioni, con ritmi diversi fra innovatori, primi adottanti e ritardatari.","url":"https://en.wikipedia.org/wiki/Everett_Rogers","id":"everett-m-rogers"},{"nome":"Fabrizio Dell'Acqua","paroleChiave":["intelligenza artificiale","lavoro della conoscenza","produttività","qualità"],"sintesi":"Ricercatore alla Harvard Business School, studia come le persone lavorano con l'intelligenza artificiale e come cambiano produttività e qualità. È primo autore dell'esperimento con i consulenti di una grande società di consulenza strategica, da cui viene l'idea di frontiera tecnologica frastagliata.","temi":[{"motivo":"Ha condotto uno dei principali esperimenti sull'intelligenza artificiale nel lavoro di consulenza.","tema":"intelligenza artificiale"},{"motivo":"Ha mostrato quando l'uso dello strumento porta a soluzioni sbagliate.","tema":"decisioni sbagliate"}],"teoria":"Le capacità dell'intelligenza artificiale sono disomogenee: compiti in apparenza simili possono cadere dentro o fuori dalla sua portata, e affidarsi allo strumento fuori dalla frontiera peggiora i risultati.","id":"fabrizio-dell-acqua"},{"altreOpere":["Organizational Development and Change (con H.K. Sinangil), 2001","Benessere organizzativo (a cura di, con M. Bonaretti), 2003","La salute organizzativa degli infermieri. Guida pratica del questionario infermieristico sulla salute organizzativa, 2010","Benessere organizzativo in un campione di aziende sanitarie italiane (con M. Gualandri, R. Fida), 2012"],"nome":"Francesco Avallone","paroleChiave":["benessere organizzativo","salute organizzativa","pubblica amministrazione","sanità","ricerca-intervento"],"sintesi":"Psicologo del lavoro, è stato docente alla Sapienza Università di Roma e preside della Facoltà di Psicologia 2. Ha diffuso in Italia il concetto di benessere organizzativo e di salute organizzativa, curando con Mauro Bonaretti il manuale del Dipartimento della Funzione Pubblica. Ha sviluppato strumenti di misura usati nelle amministrazioni pubbliche e nella sanità.","temi":[{"motivo":"È il riferimento italiano del concetto di benessere organizzativo.","tema":"benessere organizzativo"},{"motivo":"Ha proposto metodologie di analisi e intervento sul clima organizzativo.","tema":"clima"},{"motivo":"Lega la misura del benessere alla ricerca-intervento.","tema":"ricerca-azione"}],"teoria":"Il benessere organizzativo è l'insieme dei nuclei culturali, dei processi e delle pratiche che animano la convivenza nei contesti di lavoro, e si può misurare e migliorare con la ricerca-intervento.","url":"https://centrodieccellenza.eu/en/researchers/avallone-francesco/","id":"francesco-avallone"},{"nome":"Gareth Morgan","paroleChiave":[],"sintesi":"Il libro mostra come ogni metafora illumini alcuni aspetti dell'organizzazione e ne nasconda altri.","temi":[],"teoria":"Le organizzazioni si leggono attraverso metafore diverse: macchina, organismo, cervello, cultura, sistema politico.","id":"gareth-morgan"},{"nome":"Gerald S. Wilkinson","paroleChiave":[],"sintesi":"Osservò in Costa Rica pipistrelli vampiro che rigurgitano sangue per i compagni rimasti a digiuno.","temi":[],"teoria":"I pipistrelli vampiro condividono il cibo con i parenti e con chi li ha aiutati in passato.","id":"gerald-s-wilkinson"},{"altreOpere":["Naven, 1936","Steps to an Ecology of Mind, 1972","Mind and Nature, 1979"],"anni":"1904-1980","nome":"Gregory Bateson","paroleChiave":["cibernetica","doppio legame","livelli di apprendimento","comunicazione","ecologia della mente"],"sintesi":"Antropologo e studioso della comunicazione, collegò cibernetica, ecologia e psichiatria nello studio delle relazioni.","temi":[{"motivo":"Ha distinto diversi livelli di apprendimento.","tema":"livelli di apprendimento"},{"motivo":"Ha studiato la comunicazione come sistema di relazioni.","tema":"comunicazione"},{"motivo":"Ha portato la cibernetica nelle scienze umane.","tema":"retroazione"}],"teoria":"Mente, relazione e ambiente formano un unico sistema; si impara a più livelli, fino a imparare a imparare.","url":"https://en.wikipedia.org/wiki/Gregory_Bateson","id":"gregory-bateson"},{"nome":"Gregory Vial","paroleChiave":["trasformazione digitale","sistemi informativi","strategia","organizzazione"],"sintesi":"Studioso di sistemi informativi alla HEC Montréal, si occupa di trasformazione digitale e di gestione dei dati nelle organizzazioni. La sua rassegna del 2019 sulla trasformazione digitale è fra i lavori più citati del campo.","temi":[{"motivo":"Ha costruito un modello di riferimento della trasformazione digitale.","tema":"trasformazione digitale"},{"motivo":"Lega la tecnologia ai cambiamenti di struttura dell'organizzazione.","tema":"sociotecnico"}],"teoria":"La trasformazione digitale è un processo in cui le tecnologie digitali creano discontinuità e l'organizzazione risponde cambiando strategia, struttura e modo di creare valore.","id":"gregory-vial"},{"nome":"Hans van Dijk","paroleChiave":["diversità","inclusione","gruppi di lavoro","meta-analisi","genere"],"sintesi":"Studioso di comportamento organizzativo alla Tilburg University, si occupa di diversità nei gruppi di lavoro, di inclusione e di disuguaglianze di genere. Con Marloes van Engen e Daan van Knippenberg ha firmato una meta-analisi molto citata su diversità e prestazione.","temi":[{"motivo":"Ha riassunto la ricerca sul rapporto fra diversità e prestazione.","tema":"diversità"},{"motivo":"Mostra il peso delle valutazioni soggettive nei risultati.","tema":"pregiudizi"}],"teoria":"La diversità non migliora né peggiora automaticamente le prestazioni dei gruppi, e una parte degli effetti negativi attribuiti alla diversità demografica dipende da chi giudica la prestazione.","id":"hans-van-dijk"},{"altreOpere":["The Structuring of Organizations, 1979","Mintzberg on Management, 1989","The Rise and Fall of Strategic Planning, 1994","Managers Not MBAs, 2004"],"anni":"1939","nome":"Henry Mintzberg","paroleChiave":["struttura organizzativa","configurazioni","adattamento reciproco","strategia","lavoro manageriale"],"sintesi":"Ricondusse le organizzazioni a configurazioni tipiche, come la burocrazia meccanica e l'adhocrazia.","temi":[{"motivo":"Ha descritto l'adattamento reciproco come meccanismo di coordinamento.","tema":"adattamento reciproco"},{"motivo":"Ha classificato i meccanismi di coordinamento.","tema":"coordinamento"},{"motivo":"Ha ricondotto le organizzazioni a configurazioni tipiche.","tema":"struttura organizzativa"}],"teoria":"Le organizzazioni si coordinano in pochi modi, come l'adattamento reciproco, la supervisione e la standardizzazione, e assumono configurazioni diverse.","url":"https://en.wikipedia.org/wiki/Henry_Mintzberg","id":"henry-mintzberg"},{"altreOpere":["Models of Man, 1957","Organizations (con J.G. March), 1958","The Sciences of the Artificial, 1969"],"anni":"1916-2001","nome":"Herbert A. Simon","paroleChiave":["razionalità limitata","decisione","organizzazioni","intelligenza artificiale","soddisfacimento"],"sintesi":"Premio Nobel per l'economia, studiò come le organizzazioni prendono decisioni con limiti di informazione e attenzione.","temi":[{"motivo":"Ha introdotto il concetto di razionalità limitata.","tema":"razionalità limitata"},{"motivo":"La decisione nelle organizzazioni è il centro del suo lavoro.","tema":"decisione"},{"motivo":"È stato uno dei pionieri dell'intelligenza artificiale.","tema":"intelligenza artificiale"}],"teoria":"Chi decide ha informazioni, tempo e attenzione limitati: la razionalità è limitata.","url":"https://en.wikipedia.org/wiki/Herbert_A._Simon","id":"herbert-a-simon"},{"nome":"Irving L. Janis","paroleChiave":[],"sintesi":"Analizzò decisioni politiche fallimentari, come la Baia dei Porci, individuando sintomi e rimedi del pensiero di gruppo.","temi":[],"teoria":"Gruppi molto coesi e sotto pressione tendono a zittire il dissenso e a decidere male.","id":"irving-l-janis"},{"nome":"Isabelle Le Breton-Miller","paroleChiave":["impresa familiare","successione","strategia","lungo periodo"],"sintesi":"Studiosa di imprese familiari alla HEC Montréal, lavora spesso con Danny Miller sulle strategie di lungo periodo e sulla successione nelle aziende di famiglia. Il loro modello integrato della successione è fra i più citati del campo.","temi":[{"motivo":"Ha costruito un modello integrato della successione nelle imprese familiari.","tema":"passaggio generazionale"},{"motivo":"Le imprese familiari sono il suo campo principale.","tema":"impresa familiare"}],"teoria":"Una successione riesce quando si tengono insieme famiglia, impresa e settore, la preparazione del successore e un passaggio graduale e concordato.","id":"isabelle-le-breton-miller"},{"nome":"James G. Kelly","paroleChiave":[],"sintesi":"Psicologo di comunità americano, tradusse concetti dell'ecologia in principi per progettare interventi nelle comunità.","temi":[],"teoria":"Quattro principi ecologici per intervenire nelle comunità: interdipendenza, ciclicità delle risorse, adattamento, successione.","id":"james-g-kelly"},{"altreOpere":["Organizations (con H.A. Simon), 1958","A Behavioral Theory of the Firm (con R.M. Cyert), 1963","A Garbage Can Model of Organizational Choice (con M.D. Cohen, J.P. Olsen), 1972","A Primer on Decision Making, 1994"],"anni":"1928-2018","nome":"James G. March","paroleChiave":["esplorazione","sfruttamento","apprendimento organizzativo","decisione","teoria comportamentale dell'impresa"],"sintesi":"L'articolo usa modelli di simulazione per mostrare che l'apprendimento tende a privilegiare lo sfruttamento a scapito dell'esplorazione.","temi":[{"motivo":"Ha definito il bilanciamento fra esplorazione e sfruttamento.","tema":"esplorazione"},{"motivo":"Ha studiato come le organizzazioni imparano.","tema":"apprendimento organizzativo"},{"motivo":"Ha descritto come si decide davvero nelle organizzazioni.","tema":"decisione"}],"teoria":"Le organizzazioni devono bilanciare lo sfruttamento di ciò che sanno fare e l'esplorazione di ciò che ancora non sanno.","url":"https://en.wikipedia.org/wiki/James_G._March","id":"james-g-march"},{"altreOpere":["In search of how people change (con C.C. DiClemente, J.C. Norcross), 1992","Changing for Good (con J.C. Norcross, C.C. DiClemente), 1994","The Transtheoretical Model of Health Behavior Change (con W.F. Velicer), 1997"],"anni":"1942-2023","nome":"James O. Prochaska","paroleChiave":["stadi del cambiamento","modello transteorico","comportamento","salute","ricaduta"],"sintesi":"Psicologo statunitense, è stato professore all'Università del Rhode Island. Dal 1983 ha guidato lo sviluppo del modello transteorico del cambiamento, nato dallo studio di persone che smettevano di fumare da sole. Il modello è stato poi applicato a molti comportamenti di salute e ai percorsi di cambiamento nelle organizzazioni.","temi":[{"motivo":"Ha descritto gli stadi del cambiamento personale.","tema":"cambiamento personale"},{"motivo":"Il suo modello nasce dallo studio del cambiamento di abitudini.","tema":"cambiamento di comportamento"}],"teoria":"Il cambiamento attraversa stadi diversi, dalla precontemplazione al mantenimento, e ogni stadio richiede processi di cambiamento diversi.","url":"https://en.wikipedia.org/wiki/James_O._Prochaska","id":"james-o-prochaska"},{"nome":"Janine M. Benyus","paroleChiave":[],"sintesi":"Biologa e divulgatrice, fondò il Biomimicry Institute.","temi":[],"teoria":"La biomimesi studia forme, processi e sistemi della natura per risolvere problemi umani.","id":"janine-m-benyus"},{"altreOpere":["The Social Psychology of Organizing, 1969","The Collapse of Sensemaking in Organizations: The Mann Gulch Disaster, 1993","Managing the Unexpected (con K.M. Sutcliffe), 2001"],"anni":"1936-2026","nome":"Karl E. Weick","paroleChiave":["costruzione di senso","organizzazioni ad alta affidabilità","crisi","organizzare"],"sintesi":"Studiò disastri come l'incendio di Mann Gulch per mostrare come il senso condiviso si costruisce e si perde.","temi":[{"motivo":"Ha fondato lo studio della costruzione di senso nelle organizzazioni.","tema":"costruzione di senso"},{"motivo":"Ha studiato come le organizzazioni gestiscono l'imprevisto.","tema":"organizzazioni ad alta affidabilità"},{"motivo":"Il caso di Mann Gulch è il suo studio classico su una crisi.","tema":"crisi"}],"teoria":"Le persone costruiscono il senso di ciò che accade agendo e raccontandoselo, soprattutto quando l'ambiente è incerto.","url":"https://en.wikipedia.org/wiki/Karl_E._Weick","id":"karl-e-weick"},{"nome":"Katherine C. Kellogg","paroleChiave":["algoritmi","controllo","lavoro","tecnologia","cambiamento organizzativo"],"sintesi":"Docente di gestione e organizzazione alla MIT Sloan School of Management, studia come le tecnologie e le riforme cambiano il lavoro e il potere nelle organizzazioni, dagli ospedali alle imprese che usano algoritmi. Con Melissa Valentine e Angèle Christin ha scritto la rassegna di riferimento sul controllo algoritmico.","temi":[{"motivo":"Studia gli algoritmi che organizzano il lavoro.","tema":"intelligenza artificiale"},{"motivo":"Molti dei suoi casi riguardano lavoro organizzato da piattaforme.","tema":"piattaforme"},{"motivo":"Descrive le forme di resistenza al controllo algoritmico.","tema":"resistenza"}],"teoria":"Gli algoritmi sono un nuovo terreno conteso del controllo sul lavoro: dirigono, valutano e disciplinano, e i lavoratori rispondono con forme nuove di resistenza.","id":"katherine-c-kellogg"},{"altreOpere":["Principles of Topological Psychology, 1936","Resolving Social Conflicts, 1948","Field Theory in Social Science, 1951"],"anni":"1890-1947","nome":"Kurt Lewin","paroleChiave":["dinamica di gruppo","ricerca-azione","teoria del campo","cambiamento","partecipazione"],"sintesi":"Fondatore della psicologia sociale sperimentale, emigrato negli Stati Uniti nel 1933, studiò il campo di forze in cui si muovono persone e gruppi.","temi":[{"motivo":"Ha fondato la ricerca-azione.","tema":"ricerca-azione"},{"motivo":"Ha descritto il cambiamento come scongelamento, cambiamento e ricongelamento.","tema":"scongelamento"},{"motivo":"Ha letto il comportamento come funzione della persona e dell'ambiente.","tema":"teoria del campo"}],"teoria":"Il comportamento è funzione della persona e dell'ambiente; il cambiamento passa da scongelamento, cambiamento e ricongelamento.","url":"https://en.wikipedia.org/wiki/Kurt_Lewin","id":"kurt-lewin"},{"nome":"L. David Mech","paroleChiave":[],"sintesi":"Biologo che aveva reso popolare il termine alfa, ne chiese l'abbandono dopo anni di osservazioni sui lupi selvatici.","temi":[],"teoria":"I branchi in natura sono famiglie guidate dai genitori; il lupo alfa dominante nasceva da osservazioni su lupi estranei in cattività.","id":"l-david-mech"},{"altreOpere":["Group decision-making in animals (con T.J. Roper), 2003","Consensus decision making in animals (con T.J. Roper), 2005"],"nome":"Larissa Conradt","paroleChiave":["decisioni collettive","comportamento animale","consenso","evoluzione"],"sintesi":"Biologa evoluzionista, studia le decisioni collettive negli animali. Con Timothy Roper ha scritto lavori molto citati sul confronto fra decisioni prese da un solo individuo e decisioni condivise.","temi":[{"motivo":"Ha modellato le decisioni collettive negli animali.","tema":"decisione collettiva"},{"motivo":"Indica quando conviene seguire un solo individuo.","tema":"quando decentrare"}],"teoria":"Nei gruppi animali le decisioni condivise sono in genere più vantaggiose di quelle dispotiche, perché evitano le scelte estreme.","id":"larissa-conradt"},{"nome":"Longqi Yang","paroleChiave":["lavoro a distanza","reti di collaborazione","comunicazione","dati digitali"],"sintesi":"Ricercatore di Microsoft, studia con dati su larga scala come le persone collaborano e comunicano al lavoro. È primo autore dello studio su oltre sessantamila dipendenti sugli effetti del lavoro da remoto sulle reti di collaborazione.","temi":[{"motivo":"Ha misurato gli effetti del lavoro da remoto sulla collaborazione.","tema":"lavoro a distanza"},{"motivo":"Studia il passaggio dalla comunicazione sincrona a quella asincrona.","tema":"comunicazione"}],"teoria":"Il lavoro a distanza esteso a tutta l'organizzazione rende le reti di collaborazione più chiuse e statiche e riduce i ponti fra gruppi.","id":"longqi-yang"},{"altreOpere":["Social networks predict patch discovery in a wild population of songbirds (con D.R. Farine, J. Morand-Ferron, B.C. Sheldon), 2012","Experimentally induced innovations lead to persistent culture via conformity in wild birds, 2015"],"nome":"Lucy M. Aplin","paroleChiave":["cultura animale","apprendimento sociale","reti sociali","conformità","uccelli"],"sintesi":"Etologa, studia l'apprendimento sociale e la cultura negli uccelli con esperimenti in popolazioni selvatiche e con l'analisi delle reti sociali. È nota per gli esperimenti sulle cinciallegre del bosco di Wytham, vicino a Oxford, sulla nascita delle tradizioni.","temi":[{"motivo":"Ha mostrato che le innovazioni viaggiano lungo i legami sociali.","tema":"diffusione per relazioni"},{"motivo":"Ha documentato la conformità sociale negli uccelli selvatici.","tema":"conformità"}],"teoria":"Negli animali le innovazioni si diffondono lungo le reti sociali e diventano tradizioni stabili grazie alla conformità.","id":"lucy-m-aplin"},{"nome":"Ludwig von Bertalanffy","paroleChiave":[],"sintesi":"Biologo austriaco, propose una teoria generale valida per sistemi biologici, psicologici e sociali, contro la scomposizione in parti isolate.","temi":[],"teoria":"Organismi, persone e organizzazioni sono sistemi aperti che scambiano materia, energia e informazione con l'ambiente.","id":"ludwig-von-bertalanffy"},{"nome":"M. Lance Frazier","paroleChiave":["sicurezza psicologica","voce","fiducia","meta-analisi"],"sintesi":"Studioso di comportamento organizzativo, si occupa di sicurezza psicologica, voce e fiducia nei gruppi. È primo autore della meta-analisi di riferimento sulla sicurezza psicologica.","temi":[{"motivo":"Ha riassunto la ricerca sulla sicurezza psicologica.","tema":"sicurezza psicologica"},{"motivo":"Studia la fiducia interpersonale nei gruppi.","tema":"fiducia"}],"teoria":"La sicurezza psicologica spiega prestazione e comportamenti di cittadinanza anche al netto di concetti vicini come il buon rapporto con il capo.","id":"m-lance-frazier"},{"nome":"Mario Gualandri","paroleChiave":["benessere organizzativo","sanità","stress","equità"],"sintesi":"Psicologo, è primo autore con Roberta Fida e Francesco Avallone di uno studio sul benessere organizzativo in un ampio campione di aziende sanitarie locali italiane, condotto con il Multidimensional Organizational Health Questionnaire.","temi":[{"motivo":"Ha studiato il benessere organizzativo nelle aziende sanitarie italiane.","tema":"benessere organizzativo"},{"motivo":"Individua il carico come fattore principale di stress.","tema":"carico di lavoro"}],"teoria":"Nella sanità il benessere organizzativo dipende soprattutto da carico di lavoro, sicurezza, conflitto, apertura all'innovazione ed equità.","id":"mario-gualandri"},{"nome":"Marlon Nieuwenhuis","paroleChiave":["spazi di lavoro","piante","psicologia sociale","produttività"],"sintesi":"Psicologo sociale, è primo autore degli esperimenti sul campo che confrontano uffici spogli e uffici con piante in aziende dei Paesi Bassi e del Regno Unito, condotti con Craig Knight, Tom Postmes e Alexander Haslam.","temi":[{"motivo":"Ha condotto esperimenti sul campo con piante negli uffici.","tema":"piante indoor"},{"motivo":"Studia gli effetti del modo di arredare gli uffici.","tema":"spazi di lavoro"}],"teoria":"Arricchire lo spazio di lavoro con piante migliora concentrazione, soddisfazione e produttività rispetto agli uffici snelli e spogli.","id":"marlon-nieuwenhuis"},{"nome":"Masao Kawai","paroleChiave":[],"sintesi":"Il primatologo seguì per anni la diffusione di nuovi comportamenti nel gruppo di macachi dell'isola di Koshima.","temi":[],"teoria":"Il lavaggio delle patate inventato da una giovane femmina si diffuse lungo le relazioni e si fermò alla periferia del gruppo.","id":"masao-kawai"},{"nome":"Michael Y. Lee","paroleChiave":["autogestione","gerarchia","decentralizzazione","forme organizzative"],"sintesi":"Studioso di organizzazione, si occupa di forme organizzative meno gerarchiche e di autogestione. Con Amy Edmondson ha scritto la rassegna più citata sulle organizzazioni autogestite.","temi":[{"motivo":"Ha definito le organizzazioni che decentralizzano l'autorità in modo radicale.","tema":"decentralizzazione"},{"motivo":"Studia i limiti della distribuzione dell'autorità.","tema":"guida distribuita"}],"teoria":"Un'organizzazione autogestita decentralizza l'autorità in modo radicale, formale e sistematico, e incontra limiti precisi nella gestione delle tensioni e delle decisioni difficili.","id":"michael-y-lee"},{"nome":"Michaéla C. Schippers","paroleChiave":["riflessività","team","innovazione","apprendimento"],"sintesi":"Psicologa delle organizzazioni alla Rotterdam School of Management dell'Università Erasmus, studia la riflessività dei team, l'apprendimento e la definizione degli obiettivi. Con Michael West e Jeremy Dawson ha mostrato il legame fra riflessività e innovazione nei team sanitari.","temi":[{"motivo":"La riflessività di team è il centro delle sue ricerche.","tema":"riflessività"},{"motivo":"Studia come i team imparano riflettendo.","tema":"apprendimento di team"}],"teoria":"I team che riflettono insieme sul proprio modo di lavorare innovano di più, soprattutto quando le richieste di lavoro sono alte.","id":"michaela-c-schippers"},{"nome":"Morten Bennedsen","paroleChiave":["impresa familiare","successione","governance","redditività"],"sintesi":"Economista danese, ha insegnato all'Università di Copenaghen e all'INSEAD e studia le imprese familiari, la loro governance e le scelte di successione. Con i colleghi ha misurato con dati danesi l'effetto delle successioni in famiglia sulla redditività.","temi":[{"motivo":"Ha misurato gli effetti economici della successione in famiglia.","tema":"passaggio generazionale"},{"motivo":"Le imprese familiari sono il suo campo di ricerca.","tema":"family business"}],"teoria":"Affidare la guida a un familiare invece che a un esterno ha in media un costo misurabile sui risultati, soprattutto nei settori dinamici e nelle imprese più grandi.","id":"morten-bennedsen"},{"nome":"Muzafer Sherif","paroleChiave":[],"sintesi":"Nell'esperimento in un campo estivo dell'Oklahoma, due gruppi di ragazzi entrarono in conflitto durante le gare e si riconciliarono lavorando insieme a problemi comuni.","temi":[],"teoria":"Due gruppi in competizione diventano ostili; li riavvicinano obiettivi che nessuno dei due può raggiungere da solo.","id":"muzafer-sherif"},{"nome":"Nalise Hähn","paroleChiave":["design biofilico","piante","uffici","benessere"],"sintesi":"Ricercatrice sugli edifici e sul design biofilico, è prima autrice di uno studio di caso sull'introduzione e la rimozione di piante in un edificio per uffici, condotto con Emmanuel Essah e Tijana Blanusa.","temi":[{"motivo":"Ha misurato gli effetti di un intervento biofilico in un ufficio reale.","tema":"design biofilico"},{"motivo":"Il suo caso consiste nell'introdurre e togliere piante.","tema":"piante indoor"}],"teoria":"La presenza di piante negli uffici migliora la percezione di attenzione e produttività e la soddisfazione per l'ambiente, mentre ha effetti scarsi su salute e motivazione.","id":"nalise-hahn"},{"altreOpere":["Measuring and Explaining Management Practices Across Firms and Countries (con J. Van Reenen), 2007","Does Working from Home Work? (con J. Liang, J. Roberts, Z.J. Ying), 2015","Measuring Economic Policy Uncertainty (con S.R. Baker, S.J. Davis), 2016","Hybrid working from home improves retention without damaging performance (con R. Han, J. Liang), 2024"],"anni":"1973","nome":"Nicholas Bloom","paroleChiave":["lavoro ibrido","lavoro da casa","pratiche di gestione","produttività","incertezza"],"sintesi":"Economista britannico, insegna alla Stanford University e studia le pratiche di gestione, l'incertezza economica e il lavoro da casa. Con John Van Reenen ha creato un grande archivio internazionale sulla qualità della gestione nelle imprese. I suoi esperimenti sul lavoro da casa e sul lavoro ibrido sono fra i più citati del campo.","temi":[{"motivo":"Ha condotto l'esperimento di riferimento sul lavoro ibrido.","tema":"lavoro ibrido"},{"motivo":"Il suo studio su Ctrip è il classico del lavoro da casa.","tema":"lavoro a distanza"},{"motivo":"Mostra che il lavoro ibrido riduce le dimissioni.","tema":"turnover"}],"teoria":"Le pratiche di gestione spiegano una parte importante delle differenze di produttività fra imprese, e il lavoro da casa ben organizzato può migliorare la ritenzione senza danneggiare le prestazioni.","url":"https://en.wikipedia.org/wiki/Nicholas_Bloom","id":"nicholas-bloom"},{"nome":"Norbert Wiener","paroleChiave":[],"sintesi":"Matematico al MIT, fondò la cibernetica studiando il controllo e la comunicazione negli animali e nelle macchine.","temi":[],"teoria":"Un sistema si regola con la retroazione: confronta ciò che accade con ciò che dovrebbe accadere e corregge.","id":"norbert-wiener"},{"altreOpere":["The Fifth Discipline Fieldbook, 1994","Presence, 2004","The Necessary Revolution, 2008"],"anni":"1947","nome":"Peter M. Senge","paroleChiave":["organizzazione che apprende","pensiero sistemico","modelli mentali","visione condivisa"],"sintesi":"Direttore al MIT, divulgò il pensiero sistemico presso i dirigenti con le cinque discipline.","temi":[{"motivo":"Ha reso popolare l'idea di organizzazione che apprende.","tema":"organizzazione che apprende"},{"motivo":"I modelli mentali sono una delle sue cinque discipline.","tema":"modelli mentali"},{"motivo":"La visione condivisa è un'altra delle cinque discipline.","tema":"visione condivisa"}],"teoria":"L'organizzazione che apprende poggia su pensiero sistemico, modelli mentali, visione condivisa e apprendimento in gruppo.","url":"https://en.wikipedia.org/wiki/Peter_Senge","id":"peter-m-senge"},{"nome":"Ravi S. Gajendran","paroleChiave":["telelavoro","autonomia","relazioni sul lavoro","meta-analisi"],"sintesi":"Studioso di comportamento organizzativo, si occupa di lavoro a distanza, flessibilità e relazioni sul lavoro. Con David Harrison ha firmato la meta-analisi di riferimento sul telelavoro.","temi":[{"motivo":"È autore della meta-analisi più citata sul telelavoro.","tema":"lavoro a distanza"},{"motivo":"Individua l'autonomia come meccanismo dei benefici.","tema":"autonomia"}],"teoria":"Il telelavoro produce benefici soprattutto attraverso l'autonomia percepita, ma oltre una certa intensità indebolisce i rapporti con i colleghi.","id":"ravi-s-gajendran"},{"nome":"Robert A. Karasek","paroleChiave":[],"sintesi":"Su dati di lavoratori svedesi e americani, mostrò che i lavori con richieste alte e bassa autonomia producono più tensione.","temi":[],"teoria":"Lo stress nasce dall'incontro fra richieste alte e poco controllo sul proprio lavoro.","id":"robert-a-karasek"},{"nome":"Robert M. Seyfarth","paroleChiave":["primati","comunicazione animale","cognizione sociale","richiami d'allarme"],"sintesi":"Primatologo, ha studiato a lungo con Dorothy Cheney la comunicazione e la cognizione sociale dei primati in Africa, dai cercopitechi del Kenya ai babbuini del Botswana. Lo studio del 1980 sui richiami d'allarme è il classico della comunicazione referenziale negli animali.","temi":[{"motivo":"Ha mostrato che i richiami d'allarme trasmettono informazioni specifiche.","tema":"comunicazione"},{"motivo":"Studia il contenuto informativo dei segnali animali.","tema":"informazione"}],"teoria":"I segnali degli animali possono indicare oggetti ed eventi specifici del mondo, e la capacità di usarli bene si affina con l'esperienza.","id":"robert-m-seyfarth"},{"nome":"Rodger W. Griffeth","paroleChiave":["turnover","dimissioni","risorse umane","meta-analisi"],"sintesi":"Studioso di gestione delle risorse umane, ha lavorato a lungo sulle cause delle dimissioni volontarie insieme a Peter Hom. La loro meta-analisi del 2000 è stata per anni la rassegna quantitativa di riferimento sul turnover.","temi":[{"motivo":"È autore della meta-analisi di riferimento sul turnover.","tema":"turnover"},{"motivo":"Ha individuato i segnali che anticipano le uscite.","tema":"segnali di declino"}],"teoria":"Le dimissioni sono precedute da segnali misurabili, come le intenzioni di uscita e i comportamenti di ritiro, che permettono di intervenire prima.","id":"rodger-w-griffeth"},{"nome":"Roger S. Ulrich","paroleChiave":[],"sintesi":"Studio su cartelle cliniche di pazienti operati alla cistifellea in un ospedale della Pennsylvania.","temi":[],"teoria":"I pazienti con una finestra sugli alberi recuperavano in media prima di quelli che vedevano un muro.","id":"roger-s-ulrich"},{"nome":"Ronald A. Heifetz","paroleChiave":[],"sintesi":"Docente a Harvard, descrisse la leadership come mobilitare le persone ad affrontare problemi difficili, invece che dare risposte.","temi":[],"teoria":"Distingue i problemi tecnici, che un esperto risolve, da quelli adattivi, che chiedono alle persone di cambiare valori e abitudini.","id":"ronald-a-heifetz"},{"nome":"Serge Moscovici","paroleChiave":[],"sintesi":"Mostrò con esperimenti sulla percezione dei colori che una minoranza costante produce conversioni più profonde dell'adesione alla maggioranza.","temi":[],"teoria":"Una minoranza coerente e costante può cambiare l'opinione della maggioranza.","id":"serge-moscovici"},{"nome":"Shakked Noy","paroleChiave":["intelligenza artificiale","economia del lavoro","produttività","scrittura"],"sintesi":"Economista formato al MIT, è primo autore con Whitney Zhang dell'esperimento pubblicato su Science sugli effetti di ChatGPT nei compiti di scrittura professionale. Le sue ricerche riguardano l'economia del lavoro e le tecnologie nuove.","temi":[{"motivo":"Ha misurato con un esperimento l'effetto di ChatGPT sul lavoro d'ufficio.","tema":"intelligenza artificiale"},{"motivo":"Il risultato principale riguarda tempi e qualità del lavoro.","tema":"produttività"}],"teoria":"Gli strumenti generativi aumentano soprattutto la produttività di chi parte da livelli più bassi, e in questo modo riducono le differenze fra lavoratori in certi compiti.","id":"shakked-noy"},{"nome":"Sharda S. Nandram","paroleChiave":["semplificazione","autogestione","assistenza domiciliare","imprenditorialità"],"sintesi":"Docente alla Nyenrode Business University nei Paesi Bassi, studia l'imprenditorialità e le forme organizzative semplificate. Ha scritto il primo libro internazionale su Buurtzorg Nederland, da cui ha ricavato la teoria della semplificazione integrante.","temi":[{"motivo":"Ha studiato il caso più noto di team autonomi nella cura.","tema":"decentralizzazione"},{"motivo":"L'autonomia dei team è centrale nella sua teoria.","tema":"autonomia"}],"teoria":"Un'organizzazione innova quando toglie ciò che non serve al lavoro con il cliente e integra ciò che serve, lasciando ai team le decisioni sul loro lavoro.","id":"sharda-s-nandram"},{"altreOpere":["Resistance to change: Developing an individual differences measure, 2003","Change Recipients' Reactions to Organizational Change: A 60-Year Review (con M. Vakola, A. Armenakis), 2011"],"nome":"Shaul Oreg","paroleChiave":["resistenza al cambiamento","differenze individuali","cambiamento organizzativo","misura"],"sintesi":"Psicologo delle organizzazioni all'Università Ebraica di Gerusalemme, studia la resistenza al cambiamento e le reazioni delle persone ai cambiamenti organizzativi. Ha costruito una delle scale più usate per misurare la disposizione individuale a resistere al cambiamento.","temi":[{"motivo":"Ha costruito la scala di riferimento sulla resistenza al cambiamento.","tema":"resistenza al cambiamento"},{"motivo":"Studia come le persone reagiscono ai cambiamenti.","tema":"cambiamento personale"}],"teoria":"La resistenza al cambiamento ha una componente stabile della persona, fatta di ricerca della routine, reazione emotiva, rigidità e sguardo breve, che si somma al modo in cui il cambiamento viene gestito.","id":"shaul-oreg"},{"nome":"Solomon E. Asch","paroleChiave":[],"sintesi":"Negli esperimenti sulla lunghezza delle linee, i partecipanti dovevano rispondere dopo complici che davano risposte sbagliate all'unanimità.","temi":[],"teoria":"Molte persone si allineano a un giudizio palesemente sbagliato del gruppo, ma basta un solo alleato perché la conformità crolli.","id":"solomon-e-asch"},{"nome":"Stavroula Leka","paroleChiave":["rischi psicosociali","stress lavoro correlato","salute occupazionale","politiche europee"],"sintesi":"Psicologa della salute occupazionale, si occupa di rischi psicosociali, stress lavoro correlato e politiche per la salute mentale al lavoro, collaborando con organizzazioni europee e internazionali. Ha coordinato lo sviluppo di PRIMA-EF, il quadro europeo per la gestione dei rischi psicosociali.","temi":[{"motivo":"Ha lavorato al quadro europeo sullo stress lavoro correlato.","tema":"stress lavoro correlato"},{"motivo":"Inquadra il benessere al lavoro nella gestione del rischio.","tema":"benessere organizzativo"}],"teoria":"I rischi psicosociali si gestiscono con lo stesso ciclo degli altri rischi, valutando e intervenendo sull'organizzazione del lavoro a livello di impresa e di politiche pubbliche.","id":"stavroula-leka"},{"nome":"Stephen Kaplan","paroleChiave":[],"sintesi":"Psicologo ambientale all'Università del Michigan, sviluppò con Rachel Kaplan la teoria del recupero dell'attenzione.","temi":[],"teoria":"La natura ripristina l'attenzione affaticata grazie a fascinazione, sensazione di essere altrove, estensione e compatibilità.","id":"stephen-kaplan"},{"nome":"Talya N. Bauer","paroleChiave":["onboarding","socializzazione organizzativa","nuovi assunti","ritenzione"],"sintesi":"Psicologa delle organizzazioni alla Portland State University, studia l'inserimento dei nuovi assunti, la socializzazione organizzativa e il rapporto con il capo. La sua meta-analisi del 2007 sull'adattamento dei nuovi arrivati è il riferimento del campo.","temi":[{"motivo":"Ha definito i meccanismi dell'inserimento dei nuovi assunti.","tema":"onboarding"},{"motivo":"L'accettazione sociale è una delle condizioni del suo modello.","tema":"appartenenza"}],"teoria":"L'inserimento riesce quando il nuovo assunto conquista in fretta chiarezza sul ruolo, fiducia nelle proprie capacità e accettazione sociale.","id":"talya-n-bauer"},{"nome":"Thomas D. Seeley","paroleChiave":[],"sintesi":"Biologo a Cornell, ricostruì con esperimenti sugli alveari come migliaia di api coordinano raccolta e lavorazione senza un centro.","temi":[],"teoria":"Ha mostrato che l'alveare regola la raccolta sulla capacità di lavorazione con la danza del tremito, e che lo sciame sceglie il nuovo nido con un confronto fra esploratrici fino a una soglia, senza un capo.","id":"thomas-d-seeley"},{"nome":"W. Ross Ashby","paroleChiave":[],"sintesi":"Psichiatra e cibernetico inglese, formulò la legge per cui solo la varietà interna può assorbire la varietà esterna.","temi":[],"teoria":"Legge della varietà necessaria: un sistema governa un ambiente solo se ha al suo interno abbastanza varietà di risposte.","id":"w-ross-ashby"}],"ponti":[{"creata":"2026-11-04","leva":"car","limite":"Le api cambiano compito senza costi. Le persone hanno competenze, contratti e identità professionali diverse, e lo spostamento da un compito all'altro richiede tempo, formazione e accordo.","macro":"ben","meccanismo":"Seeley ha documentato che nell'alveare le bottinatrici, quando rientrano con il nettare, devono consegnarlo ad api addette alla lavorazione. Se l'attesa per la consegna si allunga, significa che la raccolta supera la capacità di lavorazione: la bottinatrice smette allora di reclutare compagne per la raccolta e fa la danza del tremito, che richiama altre api alla lavorazione. Nessuna ape conosce le scorte complessive, è il tempo di attesa a fare da segnale. Gordon ha descritto un meccanismo simile nelle formiche raccoglitrici, che decidono se uscire in base alla frequenza con cui incontrano le compagne che rientrano cariche.","natura":["seeley","gordon","bonabeau-1999-swarm"],"ordine":2,"persone":["karasek","bakker-demerouti","wiener","meadows"],"ricerca":"Karasek, e poi Bakker e Demerouti, hanno mostrato che la tensione da lavoro cresce quando le richieste superano a lungo il controllo e le risorse a disposizione. Wiener e Meadows hanno spiegato che un sistema si regola solo se l'effetto di ciò che accade torna come informazione a chi può intervenire: quando questo ritorno arriva in ritardo, il lavoro si accumula prima che qualcuno se ne accorga.","tema":"Accorgersi presto dei colli di bottiglia","temi":["carichi","team"],"id":"colli-di-bottiglia"},{"creata":"2026-11-04","leva":"rel","limite":"Lo stormo ha un solo scopo, restare unito ed evitare i predatori. Un'organizzazione deve anche scegliere la propria direzione, e il coordinamento fra vicini non può sostituire quella scelta.","macro":"tra","meccanismo":"Ballerini e colleghi hanno ricostruito in tre dimensioni il volo degli stormi di storni e hanno trovato che ogni uccello regola il proprio movimento su sei o sette vicini, scelti per posizione e non entro una distanza fissa. Questa regola mantiene lo stormo compatto anche quando cambia forma e densità, senza che alcun individuo veda lo stormo intero. Seyfarth, Cheney e Marler hanno mostrato che i cercopitechi verdi usano richiami d'allarme diversi per il leopardo, l'aquila e il serpente, e che ogni richiamo produce subito la fuga adatta a quel predatore.","natura":["ballerini","bonabeau-1999-swarm","seyfarth-1980-alarm"],"ordine":3,"persone":["mintzberg","lawrence-lorsch","ashby","weick","yang-2022-remote"],"ricerca":"Mintzberg, e prima Lawrence e Lorsch, hanno mostrato che quando l'ambiente è incerto il coordinamento avviene soprattutto per adattamento reciproco fra colleghi, perché le regole scritte non possono prevedere ogni situazione. Ashby ha dimostrato che per governare un ambiente vario serve una varietà di risposte interne, e Weick che nelle crisi la tenuta di un gruppo dipende dalla capacità di dare un senso comune a ciò che sta accadendo.","tema":"Coordinarsi in fretta quando cambiano le condizioni","temi":["team","comunicazione","resilienza"],"id":"coordinarsi-in-fretta"},{"creata":"2026-11-05","leva":"app","limite":"Le tradizioni animali riguardano comportamenti semplici e non hanno significati simbolici né rapporti di potere come le culture umane. L'analogia vale per il modo in cui un comportamento si trasmette e si stabilizza, non per il contenuto della cultura.","macro":"cul","meccanismo":"Whiten e colleghi hanno confrontato comunità di scimpanzé di diverse regioni dell'Africa e hanno trovato decine di comportamenti, come rompere le noci con le pietre, presenti in alcune comunità e assenti in altre che vivono in ambienti simili: la differenza non dipende dall'ambiente ma da ciò che ogni comunità ha imparato e trasmesso. Aplin e colleghi hanno introdotto in alcune popolazioni di cinciallegre una tecnica per aprire una mangiatoia e hanno osservato che diventava una tradizione locale, perché ogni uccello tende ad adottare la variante più diffusa nel proprio gruppo, e che la tradizione durava anche quando gli individui venivano sostituiti da nuove generazioni.","natura":["whiten-1999-cultures","aplin-2015-innovations","kawai"],"ordine":11,"persone":["schein","oreilly-1991-culture","asch","bauer-2007-newcomer"],"ricerca":"Schein ha mostrato che la cultura di un'organizzazione risiede negli assunti che le persone danno per scontati più che nei valori dichiarati. O'Reilly e colleghi l'hanno misurata come corrispondenza fra i valori della persona e quelli dell'organizzazione. Asch ha dimostrato che la pressione della maggioranza spinge le persone ad adeguarsi anche quando la maggioranza sbaglia, e Bauer e colleghi che i nuovi assunti imparano la cultura attraverso l'inserimento e l'accettazione da parte del gruppo.","tema":"Perché ogni sede ha le sue abitudini","temi":["cultura"],"id":"cultura-che-si-trasmette"},{"creata":"2026-11-04","leva":"gui","limite":"Le api di uno sciame hanno un unico interesse, la sopravvivenza della colonia. In azienda gli interessi delle persone divergono e il potere influisce sulle valutazioni, per cui una soglia di consenso da sola non protegge dalle pressioni.","macro":"lea","meccanismo":"Seeley ha studiato come uno sciame di api sceglie il nuovo nido. Molte esploratrici visitano i siti possibili ciascuna per conto proprio e li segnalano alle compagne con una danza tanto più lunga quanto migliore è il sito; la scelta avviene quando su un sito si raduna un numero sufficiente di esploratrici, una soglia di consenso. Couzin e colleghi hanno mostrato che nei gruppi in movimento bastano pochi individui informati per orientare tutti, senza che gli altri sappiano chi siano. Conradt e Roper hanno calcolato che affidarsi a un solo individuo conviene soltanto nei gruppi piccoli e quando la sua informazione è nettamente migliore di quella degli altri.","natura":["seeley-nido","couzin-2005-leadership","gordon","conradt-2003-group"],"ordine":1,"persone":["bienefeld-grote","pearce-conger","janis","asch","simon","lee-2017-selfmanaging","nandram-2015-buurtzorg"],"ricerca":"Pearce e Conger, e Bienefeld e Grote, hanno mostrato che la guida condivisa migliora i risultati quando resta chiaro chi risponde della decisione finale. Janis ha descritto il pensiero di gruppo, che porta un gruppo coeso a decidere male quando il confronto avviene prima delle valutazioni individuali, e Asch ha mostrato quanto la pressione del gruppo scoraggi il dissenso.","tema":"Decidere in tanti senza un capo","temi":["decisioni","leadership"],"id":"decidere-senza-capo"},{"creata":"2026-11-04","leva":"app","limite":"Kawai osservò per anni un gruppo piccolo e isolato, in condizioni molto diverse da quelle di un'azienda. La storia della «centesima scimmia», attribuita a questo studio, è una leggenda senza fondamento e non va usata.","macro":"cam","meccanismo":"Kawai ha descritto come, nel gruppo di macachi dell'isola di Koshima, l'abitudine di lavare le patate dolci, introdotta da una giovane femmina, si diffuse prima fra i coetanei e i parenti e poi fra le madri, mentre i maschi adulti, ai margini delle relazioni del gruppo, in gran parte non la adottarono: il comportamento nuovo si propagò lungo i legami sociali, non lungo la gerarchia. Aplin e colleghi hanno ottenuto lo stesso risultato sperimentalmente nelle cinciallegre di Wytham Woods: una tecnica insegnata a due soli uccelli per popolazione si diffuse attraverso i loro legami sociali fino a raggiungere in media tre uccelli su quattro.","natura":["kawai","aplin-2015-innovations"],"ordine":4,"persone":["rogers-e","moscovici","coch-french","lewin","kegan-lahey","oreg-2003-resistance"],"ricerca":"Rogers ha mostrato che le innovazioni si diffondono attraverso le reti di relazioni personali, a partire da pochi primi adottanti. Moscovici ha dimostrato che una minoranza coerente e costante può cambiare l'opinione della maggioranza, e Coch e French che coinvolgere le persone nella definizione del cambiamento ne riduce la resistenza. Kegan e Lahey hanno descritto gli impegni non dichiarati che frenano il cambiamento delle singole persone anche quando lo desiderano.","tema":"Diffondere un cambiamento in azienda","temi":["cambiamento","innovazione"],"id":"far-attecchire-il-nuovo"},{"creata":"2026-11-05","leva":"app","limite":"Nei suricati la progressione segue l'età e i richiami dei piccoli in modo quasi automatico. Nelle persone serve che chi impara possa dire quando si sente pronto, e che chi insegna abbia tempo riconosciuto per farlo.","macro":"app","meccanismo":"Thornton e McAuliffe hanno osservato che nei suricati del Kalahari gli adulti offrono ai piccoli prede vive, come scorpioni, preparandole in modo diverso secondo l'età: ai più piccoli le danno morte, poi rese inoffensive togliendo il pungiglione, infine intatte. La progressione è regolata dai richiami dei piccoli, che cambiano con l'età, e permette loro di imparare a cacciare prede pericolose senza correre rischi eccessivi.","natura":["thornton-2006-teaching"],"ordine":12,"persone":["bandura","bauer-2007-newcomer","edmondson-2001-disrupted"],"ricerca":"Bandura ha mostrato che la fiducia nelle proprie capacità cresce soprattutto con esperienze di riuscita graduate e osservando altri che riescono. Bauer e colleghi hanno trovato che l'inserimento dei nuovi assunti riesce quando costruisce chiarezza di ruolo, fiducia in sé e accettazione da parte del gruppo, ed Edmondson e colleghi che un modo di lavorare nuovo viene adottato meglio quando è preceduto da preparazione e da prime prove in condizioni protette.","tema":"Insegnare il mestiere ai nuovi arrivati","temi":["apprendimento","retention"],"id":"insegnare-il-mestiere"},{"creata":"2026-11-04","leva":"rig","limite":"L'associazione è piccola e quasi sempre correlazionale, quindi non sappiamo se il legame con la natura renda più felici o se le persone più serene cerchino di più la natura. Il libro di Kimmerer è un saggio narrativo, non una ricerca empirica.","macro":"ind","meccanismo":"Capaldi e colleghi hanno riunito in una meta-analisi gli studi che misurano insieme il legame con la natura e la felicità, e hanno trovato un'associazione piccola ma costante. Lumber e colleghi hanno mostrato che il legame con la natura cresce soprattutto con il contatto diretto, le emozioni, la compassione verso gli altri esseri viventi, il significato e la bellezza, e meno con la conoscenza di nozioni. Kimmerer, botanica e membro della nazione Potawatomi, descrive questo legame come un rapporto di reciprocità con il mondo vivente.","natura":["capaldi-2014-connectedness","lumber-2017-pathways","wilson-1984-biophilia","kellert-1993-biophilia","kimmerer-2013-sweetgrass"],"ordine":10,"persone":["deci-ryan","bandura"],"ricerca":"Deci e Ryan hanno mostrato che il benessere delle persone dipende dalla soddisfazione di tre bisogni, autonomia, competenza e relazione, e Bandura che la fiducia nelle proprie capacità cresce con le esperienze di riuscita. Il legame con la natura si aggiunge a questi fattori come una risorsa personale che si può coltivare.","tema":"Il legame personale con la natura","temi":["stress","motivazione"],"id":"legame-con-la-natura"},{"creata":"2026-11-04","leva":"gui","limite":"È un esempio a rovescio: serve a smontare una metafora sbagliata, non a sostituirla con un'altra metafora presa dai lupi.","macro":"lea","meccanismo":"L'immagine del lupo alfa, il capo che domina il branco con la forza, nasce da osservazioni su lupi adulti estranei fra loro messi insieme in cattività. Mech, che aveva contribuito a diffondere il termine, ha mostrato dopo anni di osservazioni in natura che il branco selvatico è una famiglia guidata dai genitori, e ha chiesto di abbandonare il termine.","natura":["mech"],"ordine":6,"persone":["bass","detert-burris","edmondson","heifetz"],"ricerca":"Bass ha mostrato che la guida che dà senso al lavoro e fa crescere le persone ottiene risultati migliori di quella che si limita a scambiare premi e controlli. Detert e Burris, ed Edmondson, hanno trovato che le persone segnalano i problemi quando il responsabile è disponibile ad ascoltare e chi parla non viene punito. Heifetz ha mostrato che molti problemi richiedono una guida che aiuti il gruppo a cambiare, non risposte imposte dall'alto.","tema":"Il mito del capo dominante","temi":["leadership"],"id":"mito-del-capo"},{"creata":"2026-11-04","leva":"rel","limite":"Per i pipistrelli lo scambio è una questione di sopravvivenza. In azienda passa da ruoli e incentivi, e un sistema di premi solo individuali può scoraggiarlo.","macro":"com","meccanismo":"Wilkinson ha osservato in Costa Rica che i pipistrelli vampiro, che rischiano di morire dopo due o tre notti senza cibo, rigurgitano sangue per i compagni rimasti a digiuno, e che lo fanno soprattutto verso i parenti e verso chi li ha aiutati in passato: lo scambio regge perché gli animali si ricordano di chi ha dato. Le reti fra funghi e radici scambiano effettivamente acqua e nutrienti con le piante, mentre l'idea degli alberi madre che nutrono i giovani attraverso queste reti è stata messa in dubbio da Karst e colleghi.","natura":["wilkinson","micorrize"],"ordine":5,"persone":["ostrom","rousseau","sherif","hirschman"],"ricerca":"Ostrom ha documentato che le comunità che gestiscono risorse comuni durano nel tempo quando le regole sono condivise e qualcuno ne controlla il rispetto. Rousseau ha mostrato che la fiducia si incrina quando vengono violate aspettative reciproche mai dichiarate, e Sherif che gruppi in competizione tornano a collaborare quando hanno uno scopo che nessuno può raggiungere da solo.","tema":"Aiutarsi e scambiarsi risorse","temi":["conflitti","fiducia"],"id":"reciprocita"},{"creata":"2026-11-04","leva":"rig","limite":"Molti studi sono piccoli o di laboratorio e gli effetti misurati sono spesso di breve durata. Il contatto con la natura non compensa un carico di lavoro mal distribuito.","macro":"ben","meccanismo":"In questo caso la natura non è un'analogia, ma un fattore che agisce direttamente sulle persone. Rachel e Stephen Kaplan hanno mostrato che gli ambienti naturali permettono all'attenzione volontaria, affaticata dal lavoro mentale, di riposare. Lee e colleghi hanno trovato che una pausa di quaranta secondi guardando l'immagine di un tetto verde riduce gli errori in un compito successivo, e Bratman e colleghi che una camminata di novanta minuti nel verde riduce la tendenza a rimuginare.","natura":["kaplan","kaplan-1989-experience","lee-2015-green-roof","bratman-2015-rumination","white-2019-120-minutes","alvarsson-2010-sound","li-2010-forest-bathing","meneguzzo-2022-terapia"],"ordine":8,"persone":["sonnentag-fritz","maslach","bakker-demerouti","karasek"],"ricerca":"Maslach, e Bakker e Demerouti, hanno mostrato che il logorio nasce da carichi elevati sostenuti con poche risorse. Sonnentag e Fritz hanno trovato che il recupero richiede distacco psicologico dal lavoro e rilassamento, e che senza recupero le energie non si ricostituiscono da un giorno all'altro.","tema":"Recuperare attenzione ed energie","temi":["stress"],"id":"recuperare-energie"},{"creata":"2026-11-04","leva":"app","limite":"Un ecosistema non ha uno scopo, un'organizzazione sì: il grado di resilienza va deciso in funzione di quello scopo e dei costi che si è disposti a sostenere.","macro":"tra","meccanismo":"Holling ha distinto, negli ecosistemi, la stabilità, cioè la capacità di tornare rapidamente all'equilibrio dopo un disturbo, dalla resilienza, cioè la capacità di assorbire un disturbo senza perdere le proprie funzioni. Ha mostrato che un sistema gestito soltanto per la resa massima, per esempio una foresta con una sola specie, può essere stabile in condizioni normali e crollare al primo disturbo serio. Benyus propone di studiare le soluzioni con cui i sistemi viventi hanno superato questi disturbi.","natura":["holling","benyus"],"ordine":7,"persone":["march","ashby","kelly","weick","bertalanffy"],"ricerca":"March ha mostrato che le organizzazioni che investono solo nello sfruttamento di ciò che sanno già fare perdono la capacità di adattarsi. Ashby ha dimostrato che un sistema può governare un ambiente vario solo se dispone di altrettante risposte possibili, e Kelly che chi interviene su una comunità deve conoscerne le interdipendenze e i cicli delle risorse.","tema":"Reggere un imprevisto grave senza bloccarsi","temi":["resilienza","innovazione"],"id":"reggere-uno-shock"},{"creata":"2026-11-04","leva":"rig","limite":"Le prove sulle piante negli ambienti interni sono discordanti, e i rapporti di settore sul design biofilico non sono studi controllati. Per questo ogni intervento va misurato.","macro":"ben","meccanismo":"Anche qui la natura agisce direttamente sulle persone. Ulrich osservò che i pazienti operati con la finestra rivolta verso gli alberi lasciavano l'ospedale prima e chiedevano meno analgesici, Boubekri e colleghi che gli impiegati con più luce naturale dormono più a lungo, e Nieuwenhuis e colleghi che la presenza di piante negli uffici aumenta la produttività riferita e misurata. Browning e colleghi, e Kellert e Calabrese, hanno organizzato questi risultati in schemi applicabili alla progettazione degli spazi.","natura":["ulrich","boubekri-2014-daylight","bringslimark-2009-plants","browning-2014-patterns","kellert-2015-practice","alvarsson-2010-sound","nieuwenhuis-2014-green","hahn-2020-biophilic"],"ordine":9,"persone":["bakker-demerouti","sonnentag-fritz","avallone-2003-benessere","gualandri-2012-benessere"],"ricerca":"Bakker e Demerouti hanno mostrato che le risorse del lavoro, fra cui le condizioni dell'ambiente fisico, proteggono dall'esaurimento. Sonnentag e Fritz hanno trovato che il recupero durante la giornata dipende anche da dove e come si fanno le pause.","tema":"Progettare spazi che rigenerano","temi":["benessere-spazi"],"id":"spazi-che-rigenerano"}],"vocabolario":[{"nome":"appartenenza","definizione":"Il legame della persona con il gruppo e con l'organizzazione, e ciò che la porta a restare o ad andarsene.","sinonimi":["appartenenza","lealtà","uscita","turnover","onboarding","relazione"]},{"nome":"apprendimento organizzativo","definizione":"Il modo in cui un'organizzazione modifica le proprie regole e pratiche alla luce dell'esperienza.","sinonimi":["apprendimento organizzativo","organizzazione che apprende","apprendimento","modelli mentali","visione condivisa","livelli di apprendimento","routine"]},{"nome":"autoefficacia","definizione":"La convinzione di saper svolgere con successo un compito specifico.","sinonimi":["autoefficacia","fiducia in sé","esperienze di successo","padronanza","modellamento","competenza"]},{"nome":"autonomia","definizione":"La possibilità di decidere come, quando e in che ordine svolgere il proprio lavoro.","sinonimi":["autonomia","controllo","margine decisionale","controllo del tempo","empowerment"]},{"nome":"autopoiesi","definizione":"La proprietà dei sistemi viventi di produrre continuamente i propri componenti e di rispondere all'ambiente secondo la propria organizzazione.","sinonimi":["autopoiesi","chiusura operativa","accoppiamento strutturale","perturbazione","cognizione","organismo","evoluzione"]},{"nome":"benessere organizzativo","definizione":"La qualità della vita lavorativa in un'organizzazione: clima, carichi, relazioni, equità e ambiente fisico.","sinonimi":["benessere organizzativo","benessere"]},{"nome":"beni comuni","definizione":"Le risorse condivise da più persone o reparti, e le regole che ne evitano l'esaurimento.","sinonimi":["beni comuni","regole condivise","monitoraggio"]},{"nome":"biofilia","definizione":"L'ipotesi di una tendenza umana innata a cercare il legame con le altre forme di vita.","sinonimi":["biofilia","valori della natura"]},{"nome":"biomimesi","definizione":"Lo studio delle soluzioni dei sistemi viventi per risolvere problemi umani.","sinonimi":["biomimesi","natura come modello"]},{"nome":"burnout","definizione":"Lo stato di esaurimento, distacco cinico e sensazione di inefficacia prodotto da uno squilibrio prolungato fra persona e lavoro.","sinonimi":["burnout","esaurimento","cinismo"]},{"nome":"cambiamento organizzativo","definizione":"Il cambiamento di strutture, processi e cultura di un'organizzazione e il modo in cui viene guidato.","sinonimi":["cambiamento","cambiamento culturale","punti di leva","fusioni","obiettivi di sistema"]},{"nome":"cambiamento personale","definizione":"Il processo con cui una persona modifica abitudini e comportamenti, e gli ostacoli che lo frenano.","sinonimi":["cambiamento personale","cambiamento di comportamento","immunità al cambiamento","impegni nascosti","assunzioni","stadi del cambiamento","ricaduta"]},{"nome":"carico di lavoro","definizione":"La quantità e la distribuzione del lavoro fra persone e reparti, con i suoi accumuli e i suoi colli di bottiglia.","sinonimi":["carico di lavoro","colli di bottiglia","flusso di lavoro","turni","costi nascosti","scarto","compiti ripetuti","produttività"]},{"nome":"comunicazione","definizione":"Il modo in cui le informazioni circolano fra persone, reparti e livelli dell'organizzazione.","sinonimi":["comunicazione","informazione","comunicazione in copia","sapere tacito","reti di relazioni"]},{"nome":"conflitto fra gruppi","definizione":"La rivalità fra gruppi che nasce dalla competizione e dall'identificazione con il proprio gruppo.","sinonimi":["conflitto fra gruppi","noi e loro","favoritismo","identità sociale","competizione","obiettivi sovraordinati","pregiudizi"]},{"nome":"conformità","definizione":"La tendenza ad adeguare giudizi e comportamenti a quelli della maggioranza.","sinonimi":["conformità","pressione del gruppo","alleato","dissenso"]},{"nome":"connessione con la natura","definizione":"Il legame personale con il mondo naturale e le esperienze che lo rafforzano.","sinonimi":["connessione con la natura","rapporto uomo natura","bellezza","emozione","esperienza diretta","cura","saperi tradizionali","sostenibilità"]},{"nome":"contingenza","definizione":"Il principio secondo cui la struttura migliore di un'organizzazione dipende dall'incertezza del suo ambiente.","sinonimi":["contingenza","differenziazione","integrazione","incertezza ambientale","ambiente esterno","struttura","struttura organizzativa","configurazioni","standardizzazione","risposta all'ambiente","adattamento"]},{"nome":"contratto psicologico","definizione":"L'insieme delle promesse implicite che persona e organizzazione ritengono di essersi scambiate.","sinonimi":["contratto psicologico","aspettative","violazione"]},{"nome":"coordinamento senza centro","definizione":"Il coordinamento di molti individui che nasce da interazioni locali, senza che qualcuno veda l'insieme o lo diriga.","sinonimi":["coordinamento senza capo","interazioni locali","reti locali","vicini topologici","intelligenza collettiva","risposta rapida"]},{"nome":"costruzione di senso","definizione":"Il processo con cui un gruppo interpreta ciò che sta accadendo, decisivo nelle crisi.","sinonimi":["costruzione di senso","doppio legame","ecologia della mente","contesto"]},{"nome":"cultura organizzativa","definizione":"L'insieme degli assunti che un'organizzazione ha imparato e dà per scontati, visibili negli artefatti e dichiarati nei valori.","sinonimi":["cultura","cultura organizzativa","assunti di base","artefatti","valori","valori dichiarati","norme","coerenza","precultura","apprendimento sociale","narrazione"]},{"nome":"decentralizzazione","definizione":"Lo spostamento delle decisioni verso chi è più vicino all'informazione e al problema.","sinonimi":["decentralizzazione","delega","quando decentrare","autogoverno"]},{"nome":"decisione collettiva","definizione":"Il processo con cui un gruppo sceglie fra più opzioni, e le condizioni che rendono la scelta accurata.","sinonimi":["decisione collettiva","decisione di gruppo","decisione","soglia di quorum","confronto fra opzioni","decisioni rare","decisioni sbagliate"]},{"nome":"design biofilico","definizione":"La progettazione di edifici e spazi che porta al loro interno elementi, forme e processi naturali.","sinonimi":["design biofilico","design","spazi di lavoro","materiali naturali","acqua","psicologia ambientale","preferenze ambientali"]},{"nome":"diffusione delle innovazioni","definizione":"Il percorso con cui un comportamento o una tecnologia nuova passa da pochi adottanti al resto di un gruppo.","sinonimi":["diffusione delle innovazioni","diffusione per relazioni","primi adottanti","opinion leader","adozione","giovani","periferia del gruppo","centesima scimmia","innovazione"]},{"nome":"diversità","definizione":"Le differenze di età, provenienza, formazione e punto di vista nei gruppi, e le condizioni in cui aiutano o ostacolano il lavoro.","sinonimi":["diversità","inclusione","equità"]},{"nome":"esplorazione e sfruttamento","definizione":"Il dilemma fra perfezionare ciò che si sa già fare e cercare possibilità nuove dai risultati incerti.","sinonimi":["esplorazione","sfruttamento"]},{"nome":"guida distribuita","definizione":"La guida che passa da una persona all'altra secondo il compito e le competenze, dentro una cornice che lascia chiara la responsabilità finale.","sinonimi":["guida distribuita","leadership condivisa","responsabilità finale","individui informati","sistemi multi-team"]},{"nome":"immersione nel bosco","definizione":"Il tempo trascorso negli ambienti forestali e i suoi effetti misurati su stress e salute.","sinonimi":["immersione nel bosco","terapia forestale","odori e fitoncidi","sistema immunitario","tempo in natura","camminata","natura"]},{"nome":"impresa familiare","definizione":"Le imprese controllate da una famiglia e il passaggio della guida fra generazioni.","sinonimi":["impresa familiare","passaggio generazionale","successione familiare","successione","famiglia"]},{"nome":"influenza minoritaria","definizione":"La capacità di una minoranza coerente e costante di cambiare l'opinione della maggioranza.","sinonimi":["influenza minoritaria","conversione"]},{"nome":"intelligenza artificiale","definizione":"Gli effetti dell'intelligenza artificiale, generativa e non, sui compiti, sulle competenze e sulla produttività.","sinonimi":["intelligenza artificiale"]},{"nome":"lavoro a distanza e ibrido","definizione":"Il lavoro svolto in parte o del tutto fuori dalla sede, e i suoi effetti su prestazioni, relazioni e permanenza.","sinonimi":["lavoro a distanza","lavoro ibrido"]},{"nome":"lavoro di squadra","definizione":"Il modo in cui un gruppo coordina il lavoro, si passa le informazioni e impara insieme.","sinonimi":["team","coordinamento","adattamento reciproco","coesione","ruoli","apprendimento di team","apprendimento di gruppo","riflessività"]},{"nome":"leadership adattiva","definizione":"La guida che aiuta un gruppo ad affrontare problemi che richiedono di cambiare valori e abitudini, e non solo di applicare soluzioni note.","sinonimi":["leadership adattiva","sfide adattive","problemi tecnici"]},{"nome":"luce naturale","definizione":"Gli effetti della luce del giorno su sonno, ritmi biologici ed energia di chi lavora.","sinonimi":["luce naturale","ritmi circadiani"]},{"nome":"misura della cultura","definizione":"Gli strumenti che descrivono la cultura di un'organizzazione e la confrontano con quella desiderata.","sinonimi":["misura della cultura","valori in competizione","flessibilità e controllo","misura"]},{"nome":"mito del capo dominante","definizione":"L'idea, smentita dalla ricerca, che un gruppo funzioni grazie a un capo che domina con la forza.","sinonimi":["dominanza","lupo alfa","leggende"]},{"nome":"motivazione intrinseca","definizione":"La spinta a lavorare che nasce dall'interesse per il lavoro stesso, non da premi o controlli esterni.","sinonimi":["motivazione intrinseca","coinvolgimento","incentivi","felicità"]},{"nome":"paesaggio sonoro","definizione":"Gli effetti dei suoni naturali e del rumore sul recupero dallo stress e sulla concentrazione.","sinonimi":["suoni naturali","rumore"]},{"nome":"partecipazione","definizione":"Il coinvolgimento delle persone nelle decisioni e nella progettazione dei cambiamenti che le riguardano.","sinonimi":["partecipazione","ricerca-azione","consulenza di processo","indagine umile"]},{"nome":"pensiero di gruppo","definizione":"La tendenza di un gruppo coeso a cercare l'accordo a scapito della valutazione critica delle alternative.","sinonimi":["pensiero di gruppo","avvocato del diavolo"]},{"nome":"piante negli uffici","definizione":"Gli effetti della presenza di piante negli ambienti interni su benessere e prestazioni.","sinonimi":["piante indoor"]},{"nome":"razionalità limitata","definizione":"Il fatto che chi decide disponga di informazioni, tempo e attenzione limitati, e scelga quindi la prima soluzione soddisfacente.","sinonimi":["razionalità limitata","soddisfacimento"]},{"nome":"reciprocità","definizione":"Lo scambio di aiuti e risorse che regge nel tempo perché chi dà si ricorda di chi ha dato.","sinonimi":["reciprocità","scambi ripetuti","cooperazione","parentela","simbiosi","condivisione delle risorse"]},{"nome":"recupero dell'attenzione","definizione":"La teoria secondo cui gli ambienti naturali permettono all'attenzione volontaria, affaticata dal lavoro mentale, di riposare.","sinonimi":["recupero dell'attenzione","attenzione","fatica mentale","fascinazione"]},{"nome":"recupero","definizione":"Il ritorno delle energie fisiche e mentali dopo lo sforzo, attraverso distacco, riposo e pause adeguate.","sinonimi":["recupero","recupero dallo stress","distacco psicologico","rilassamento","pause rigenerative","micro-pause","ruminazione","sonno","salute mentale"]},{"nome":"regolazione distribuita","definizione":"Il modo in cui un sistema adegua il lavoro alle condizioni attraverso segnali locali, senza un centro che decida ogni spostamento.","sinonimi":["regolazione distribuita","regolazione","autoregolazione","danza del tremito","foraggiamento","segnali","divisione del lavoro"]},{"nome":"resilienza","definizione":"La capacità di assorbire un disturbo senza perdere le proprie funzioni.","sinonimi":["resilienza","stabilità","disturbo","efficienza e fragilità","crisi","emergenza","organizzazioni ad alta affidabilità","segnali di declino"]},{"nome":"resistenza al cambiamento","definizione":"Le reazioni cognitive, emotive e di comportamento con cui le persone si oppongono a un cambiamento.","sinonimi":["resistenza","resistenza al cambiamento","scongelamento","teoria del campo"]},{"nome":"reti fra piante e funghi","definizione":"Le associazioni fra funghi e radici e il dibattito scientifico sul loro ruolo nello scambio di risorse fra alberi.","sinonimi":["reti micorriziche","alberi madre","evidenze contestate"]},{"nome":"retroazione","definizione":"Il ritorno dell'informazione sugli effetti di un'azione a chi può correggerla.","sinonimi":["retroazione","cicli di retroazione","stock e flussi","pensiero sistemico"]},{"nome":"sicurezza psicologica","definizione":"La convinzione condivisa in un gruppo che si possa parlare apertamente, ammettere errori e chiedere aiuto senza essere puniti.","sinonimi":["sicurezza psicologica","errori","fiducia"]},{"nome":"silenzio organizzativo","definizione":"La rinuncia diffusa a segnalare problemi e proposte, che impedisce alle informazioni di arrivare a chi decide.","sinonimi":["silenzio organizzativo","informazione che non risale","convinzioni manageriali","clima"]},{"nome":"sistemi aperti","definizione":"L'idea che un'organizzazione viva di scambi continui di persone, informazioni e risorse con il proprio ambiente.","sinonimi":["sistema aperto","scambio con l'ambiente","equifinalità","olismo","confini organizzativi","interdipendenza","ciclicità delle risorse","psicologia di comunità"]},{"nome":"sistemi sociotecnici","definizione":"La progettazione congiunta della tecnologia e dell'organizzazione del lavoro.","sinonimi":["sociotecnico","diagnosi","analisi organizzativa multidimensionale","profili di comunità","lettura delle organizzazioni","metafore"]},{"nome":"stile di guida","definizione":"Il modo in cui un responsabile esercita la propria influenza sui collaboratori.","sinonimi":["stile di guida","comportamento del capo","leadership trasformazionale","leadership transazionale","ispirazione","sviluppo dei collaboratori","guida"]},{"nome":"stress lavorativo","definizione":"La tensione che nasce quando, per lungo tempo, le richieste del lavoro superano le risorse e il controllo di chi lavora.","sinonimi":["stress lavorativo","stress lavoro correlato","domanda-controllo","richieste-risorse","risorse del lavoro","rischi psicosociali","fisiologia dello stress","salute"]},{"nome":"teoria dichiarata e teoria in uso","definizione":"Lo scarto fra i principi che un'organizzazione dichiara e quelli che guidano davvero i comportamenti.","sinonimi":["teoria dichiarata","teoria in uso","routine difensive","doppio ciclo"]},{"nome":"trasformazione digitale","definizione":"L'introduzione di tecnologie digitali e il cambiamento dell'organizzazione del lavoro che richiede.","sinonimi":["trasformazione digitale","piattaforme","automazione"]},{"nome":"turbolenza ambientale","definizione":"La condizione di un ambiente in cui i cambiamenti nascono dall'intreccio di molti attori e sono difficili da prevedere.","sinonimi":["turbolenza ambientale","complessità ambientale","incertezza","pianificazione"]},{"nome":"varietà necessaria","definizione":"Il principio secondo cui un sistema governa un ambiente vario solo se dispone di altrettanta varietà di risposte.","sinonimi":["varietà necessaria","varietà","complessità"]},{"nome":"vista sul verde","definizione":"Gli effetti della vista su alberi, prati e piante sul recupero e sull'attenzione.","sinonimi":["vista sul verde"]},{"nome":"voce","definizione":"L'espressione di idee, preoccupazioni e proposte rivolte a chi può cambiare le cose.","sinonimi":["voce","proposte di miglioramento","porta aperta","ordine di parola"]}]};